import{n as e}from"./rolldown-runtime-8BhlS34s.js";var t;function n(){return(n=e((()=>{t={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`ACP-runtime-instellingen voor het inschakelen van dispatch, het selecteren van backends, het beperken van toegestane doelagents en het selecteren van het projectiegedrag voor gestreamde beurten.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`Toegestane ACP-agents`},help:{"v1-f2mw0d-3a":`Lijst met ACP-doelagent-ID's die zijn toegestaan voor ACP-runtime-sessies. Leeg betekent geen aanvullende beperking via deze lijst.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`ACP-backend`},help:{"v1-1s1l6bz-2v":`Standaard backend-ID voor de ACP-runtime (bijvoorbeeld: acpx). Moet overeenkomen met een geregistreerde backend van een ACP-runtime-plug-in.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`Standaard ACP-agent`},help:{"v1-7donnu-2c":`ACP-doelagent-ID die als terugvaloptie wordt gebruikt wanneer bij het starten van ACP geen expliciet doel is opgegeven.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`ACP-dispatch ingeschakeld`},help:{"v1-1ug9t9m-3w":`Onafhankelijke dispatchschakelaar voor ACP-sessiebeurten (standaard: true). Stel in op false om ACP-opdrachten beschikbaar te houden terwijl de uitvoering van ACP-beurten wordt geblokkeerd.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACP ingeschakeld`},help:{"v1-1uonl1v-2a":`Algemene schakelaar voor ACP-functionaliteit. Laat uitgeschakeld tenzij de ACP-runtime en het beleid zijn geconfigureerd.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`ACP-terugvalbackends`},help:{"v1-1wvdifq-5m":`Geordende lijst met ID's van ACP-terugvalbackends die worden geprobeerd wanneer de primaire backend faalt met UNAVAILABLE (bijvoorbeeld: snelheidslimiet bereikt / quotum uitgeput). Elk item moet overeenkomen met een geregistreerde backend van een ACP-runtimeplug-in.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`Installatieopdracht voor ACP-runtime`},help:{"v1-1jjuv9m-39":"Optionele installatie-/configuratieopdracht voor de beheerder die door `/acp install` en `/acp doctor` wordt getoond wanneer de ACP-backendkoppeling ontbreekt."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`ACP-stream`},help:{"v1-1bka5p-2v":`Instellingen voor ACP-streamingprojectie voor blokgrootte, zichtbaarheid van metadata en levering zonder duplicaten.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`Leveringsmodus voor ACP-stream`},help:{"v1-19gdmx1-3s":`ACP-leveringswijze: live streamt geprojecteerde uitvoer stapsgewijs, final_only buffert alle geprojecteerde ACP-uitvoer totdat gebeurtenissen het einde van de beurt aangeven.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`Herhalingsonderdrukking voor ACP-stream`},help:{"v1-manh32-3d":`Bij true (standaard) worden herhaalde projectieregels voor ACP-status en -tools binnen een beurt onderdrukt, terwijl onbewerkte ACP-gebeurtenissen ongewijzigd blijven.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`Tagzichtbaarheid voor ACP-stream`},help:{"v1-1ybhx22-34":`Zichtbaarheidsoverschrijvingen per sessionUpdate voor ACP-projectie (bijvoorbeeld usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`Agenten`},help:{"v1-2rc4v8-55":`Hoofdniveau van de runtimeconfiguratie voor agents. Onderdelen op hetzelfde hoofdniveau beheren de infrastructuur en standaardinstellingen voor alle agents; agents.defaults beheert het gedrag van de agentlus; agentitems kunnen beide overschrijven waar dit wordt ondersteund.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`Standaardinstellingen voor agents`},help:{"v1-1af7k5b-5a":`Gedeelde standaardinstellingen die agents overnemen, tenzij ze per item in agents.entries worden overschreven. Gebruik standaardinstellingen om consistent basisgedrag af te dwingen en dubbele configuratie per agent te verminderen.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`Doel voor overname van authenticatie`},help:{"v1-2d16wl-2x":`Eigenaar voor upgradecompatibiliteit van de overgenomen opslag van inloggegevens, totdat de inloggegevens per agent zijn verplaatst.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`Eigenaar voor overname van authenticatie`},help:{"v1-1a1s7nm-4s":`Agent waarvan de oude opslag van inloggegevens de bron voor overname blijft nadat de standaardmarkering is uitgefaseerd. Wordt automatisch vastgelegd tijdens de upgrade als de vorige eigenaar niet main was.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`Maximaal aantal tekens per bootstrapbestand`},help:{"v1-drlo3i-37":`Maximaal aantal tekens van elk bootstrapbestand in de werkruimte dat in de systeemprompt wordt ingevoegd voordat het wordt afgekapt (standaard: 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`Maximaal totaal aantal tekens voor bootstrapbestanden`},help:{"v1-1evwsjb-2c":`Maximaal totaal aantal tekens voor alle ingevoegde bootstrapbestanden in de werkruimte (standaard: 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`Compactie`},help:{"v1-1qxdwz8-5p":`Gedrag bij het comprimeren wanneer de context de tokenlimieten nadert, inclusief de strategie en het wegschrijven van geheugen vóór het comprimeren. Gebruik dit wanneer langdurige sessies stabiele continuïteit nodig hebben bij beperkte contextvensters.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`Ingebouwde automatische compressie`},help:{"v1-1et7vwu-5l":`Schakel ingebouwde proactieve automatische compactie in (standaard: true). Stel in op false om ingebouwde compactie op basis van drempelwaarden te stoppen, terwijl overloopherstel van OpenClaw, voorafgaande compactie en handmatige /compact behouden blijven.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`Beleid voor identifiers bij compactie`},help:{"v1-hby01l-4l":`Beleid voor het behouden van identifiers in compactiesamenvattingen: "strict" voegt ingebouwde richtlijnen voor het behouden van ondoorzichtige identifiers aan het begin toe (standaard), terwijl "off" dit voorvoegsel uitschakelt.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`Recente tokens behouden bij compactie`},help:{"v1-tgysub-5h":`Minimaal tokenbudget dat tijdens compactie behouden blijft uit het meest recente gespreksvenster. Gebruik hogere waarden om de continuïteit van de directe context te beschermen en lagere waarden om meer oudere geschiedenis te behouden.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-1il6xj6-17":`Groottedrempel van actief transcript voor compactie`},help:{"v1-u715n1-90":`Drempelwaarde in bytes die normale voorafgaande lokale compactie activeert wanneer het transcriptvenster dat het model ziet (sinds de laatste compactie of reset) deze grootte bereikt (bytes of tekenreeksen zoals "20mb"). Stel in op 0 of laat oningesteld om uit te schakelen. Beperkt ook de grootte van native rollout-transcripten van de Codex app-server; te grote native threads beginnen opnieuw met een schone lei.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`Geheugenopslag vóór compactie`},help:{"v1-18q0ve9-55":`Instellingen voor geheugenopslag vóór compactie, waarbij een agent informatie naar het geheugen schrijft voordat ingrijpende compactie plaatsvindt. Houd dit ingeschakeld voor lange sessies, zodat belangrijke context wordt opgeslagen voordat er grondig wordt ingekort.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`Geheugenopslag vóór compactie ingeschakeld`},help:{"v1-9xllgp-5o":`Schakelt geheugenopslag vóór compactie in, voordat de runtime de geschiedenis sterker inkort bij het naderen van tokenlimieten. Laat dit ingeschakeld, tenzij u neveneffecten op het geheugen bewust wilt uitschakelen in omgevingen met beperkte middelen.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-10u43o5-1d":`Drempelwaarde voor transcriptgrootte bij geheugenopslag vóór compactie`},help:{"v1-1rzov1e-93":`Dwingt geheugenopslag vóór compactie af wanneer het voor het model zichtbare transcriptvenster deze drempelwaarde bereikt (bytes of tekenreeksen zoals "2mb"). Na compactie omvat dit het behouden laatste deel en de daaropvolgende beurten, niet de verwijderde geschiedenis. Gebruik dit om vastlopen bij lange sessies te voorkomen, zelfs wanneer tokentellers verouderd zijn; stel in op 0 om uit te schakelen.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Emodel":{label:{"v1-z6o9nc-12":`Modeloverschrijving voor geheugenopslag vóór compactie`},help:{"v1-1r3ctyu-7w":`Optionele overschrijving van provider/model die alleen wordt gebruikt voor beurten voor geheugenopslag vóór compactie. Stel dit in op een lokaal model zoals ollama/qwen3:8b wanneer het extraheren van blijvende geheugeninformatie niet via het betaalde model van de actieve sessie moet verlopen. De overschrijving is exact en neemt de terugvalketen van het actieve model niet over.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`Zachte drempelwaarde voor geheugenopslag vóór compactie`},help:{"v1-1dqo2l1-5c":`Drempelafstand tot compactie (in tokens) die geheugenopslag vóór compactie activeert. Gebruik eerdere drempelwaarden om gegevens veiliger te bewaren, of krappere drempelwaarden om minder vaak op te slaan.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`Voorafgaande compactiecontrole tijdens de beurt`},help:{"v1-am6gbh-6x":`Optionele voorafgaande controle voor ingebedde OpenClaw-toollussen die contextdruk detecteert nadat een toolresultaat is toegevoegd en vóór de volgende modelaanroep. Wanneer deze is ingeschakeld, gebruikt OpenClaw het bestaande herstelmechanisme voor voorafgaande controles om toolresultaten in te korten of compactie uit te voeren voordat het opnieuw probeert.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`Voorafgaande compactiecontrole tijdens de beurt ingeschakeld`},help:{"v1-engbwe-5u":`Schakel gestructureerde controles op contextdruk tijdens de beurt in voor ingebedde OpenClaw-toollussen. Standaard: false. Laat dit uitgeschakeld, tenzij lange sessies met veel toolgebruik de contextlimiet overschrijden voordat de normale compactie aan het einde van de beurt kan plaatsvinden.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`Compactiemodus`},help:{"v1-1unahwc-76":`Modus voor de compactiestrategie: "safeguard" (de effectieve standaard wanneer niet ingesteld) past waarborgen toe om recente context te behouden, terwijl "default" basissamenvatting zonder deze waarborgen gebruikt. Stel alleen "default" in als samenvatting met safeguard problemen veroorzaakt bij uw provider.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`Afwijkend compactiemodel`},help:{"v1-cfeys9-6q":`Optionele provider/model of geconfigureerde alias zonder prefix die alleen wordt gebruikt voor samenvattingen bij compactie. Aliassen zonder prefix worden vóór verzending omgezet; een geconfigureerde letterlijke model-ID krijgt voorrang als deze overeenkomt met een alias. Laat dit oningesteld om het primaire agentmodel te blijven gebruiken.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`Gebruiker informeren over compactie`},help:{"v1-lvymm8-bv":`Indien ingeschakeld worden korte meldingen over contextonderhoud naar de gebruiker gestuurd: wanneer de compactie begint en eindigt (bijvoorbeeld '🧹 Context wordt gecomprimeerd...' en '🧹 Compactie voltooid'), en wanneer alle pogingen om vóór de compactie het geheugen weg te schrijven zijn uitgeput, waardoor het antwoord met beperkte context wordt voortgezet (bijvoorbeeld '⚠️ Geheugenonderhoud is tijdelijk mislukt; je antwoord wordt voortgezet.'). Standaard uitgeschakeld om contextonderhoud stil en onopvallend te houden.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`Contextsecties na compactie`},help:{"v1-1n0ln2u-5f":`Namen van H2/H3-secties in AGENTS.md die na compactie opnieuw worden ingevoegd, indien expliciet ingesteld. Laat deze instelling oningesteld of stel [] in om het opnieuw invoegen uit te schakelen. Stel expliciet ["Session Startup", "Red Lines"] in om het oude standaardpaar in te schakelen.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`Indexsynchronisatie na compactie`},help:{"v1-ekpjeq-6l":`Bepaalt de modus voor het opnieuw indexeren van het sessiegeheugen na compactie: "off", "async" of "await" (standaard: "async"). Gebruik "await" voor maximale actualiteit, "async" voor minder vertraging bij compactie en "off" alleen wanneer de synchronisatie van het sessiegeheugen elders wordt afgehandeld.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`Compactieprovider`},help:{"v1-kiwk91-86":`ID van een geregistreerde compactieproviderplug-in die wordt gebruikt voor het samenvatten. Wanneer deze is ingesteld en de provider is geregistreerd, wordt de methode summarize() ervan aangeroepen in plaats van de ingebouwde summarizeInStages-pijplijn. Valt terug op de ingebouwde functionaliteit als de provider faalt. Laat deze instelling oningesteld om de standaard ingebouwde samenvattingsfunctie te gebruiken.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`Kwaliteitsbewaking voor compactie`},help:{"v1-u9ognp-4k":`Instellingen voor herhaalde kwaliteitscontroles van samenvattingen bij compactie in safeguard-modus. In safeguard-modus is dit standaard ingeschakeld; stel enabled: false in om samenvattingscontroles en het opnieuw genereren over te slaan.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`Kwaliteitsbewaking bij compactie ingeschakeld`},help:{"v1-1xk2vt3-36":`Schakelt kwaliteitscontroles van samenvattingen en herhaalde pogingen tot opnieuw genereren in voor compactie in safeguard-modus. Standaard: true in safeguard-modus.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`Maximaal aantal nieuwe pogingen voor kwaliteitsbewaking bij compactie`},help:{"v1-n7l46y-3y":`Maximaal aantal pogingen om opnieuw te genereren nadat een samenvatting in safeguard-modus de kwaliteitscontrole niet heeft doorstaan. Gebruik lage waarden om extra vertraging en tokenkosten te beperken.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`Recente gespreksbeurten behouden bij compactie`},help:{"v1-y34ihi-5k":`Aantal meest recente gespreksbeurten van de gebruiker/assistent dat ongewijzigd behouden blijft buiten de samenvatting in safeguard-modus (standaard: 3). Verhoog dit aantal om de exacte recente gesprekscontext te behouden, of verlaag het om de besparing door compactie te maximaliseren.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`Denkniveau bij compactie`},help:{"v1-1vafgaw-g1":`Denkniveau dat alleen wordt gebruikt voor ingebouwde OpenClaw-compactiesamenvattingen: "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra" of "inherit". Standaard wordt de compactievoorkeur van de provider gebruikt, anders "low"; bij native lokaal Ollama heeft "off" de voorkeur. Stel "inherit" in om het sessieniveau te hergebruiken. Expliciete instellingen hebben voorrang op de standaardwaarden van de provider, en het geselecteerde niveau wordt begrensd door het daadwerkelijke compactiemodel en de runtime. Native compactie via Codex app-server negeert deze instelling omdat het compactieverzoek geen afzonderlijke overschrijving van het denkniveau per bewerking ondersteunt. OpenClaw registreert dan een waarschuwing.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`Time-out voor compactie (seconden)`},help:{"v1-2bhn29-7m":`Veiligheidslimiet in seconden voor elk ingebouwd compactiemodelverzoek (standaard: 180). Bij compactie in meerdere fasen wordt de tijdslimiet vernieuwd zodra elk opeenvolgend verzoek begint, waardoor de volledige compactie langer kan duren; compactie die door een plug-in wordt beheerd, krijgt één tijdslimiet voor de volledige bewerking.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`Contextinjectie`},help:{"v1-u18x0-7u":`Bepaalt hoe bootstrapbestanden van de werkruimte in de ingebedde runtime worden geïnjecteerd: "always" gebruikt normale injectie (standaard), "continuation-skip" slaat daarvoor in aanmerking komende vervolgbeurten over na een geregistreerde beurt met volledige bootstrap, en "never" schakelt injectie uit. Heeft geen invloed op de voorbereiding van prompts via de CLI.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`Standaardcontextlimieten`},help:{"v1-1coeez8-5d":`Gerichte standaardbudgetten per agentcontext voor geselecteerde omvangrijke fragmenten en ingevoegde promptblokken. Gebruik dit om begrensde lees- en invoeggroottes af te stemmen zonder onbeperkte aanroeppaden opnieuw open te stellen.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`Standaard maximumaantal tekens voor memory_get`},help:{"v1-1qb40qv-4v":`Standaard maximumaantal tekens dat memory_get retourneert voordat metadata over afkapping en een vervolgmelding worden toegevoegd. Verhoog dit om de eerdere, grotere fragmenten te benaderen, maar houd het begrensd.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`Standaard maximumaantal tekens na compactie`},help:{"v1-64qo8g-5r":`Standaard maximumaantal tekens uit AGENTS.md dat behouden blijft bij het invoegen van vernieuwde context na compactie. Verlaag dit om herstel na compactie goedkoper te maken, of verhoog het voor agents die afhankelijk zijn van langere opstartinstructies.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`Werkmap`},help:{"v1-1y8wlxn-6a":`Werkmap voor uitvoeringen waarin de agent antwoordt, los van de initialisatie- en geheugenbestanden van de werkruimte. Agentspecifieke cwd en bij het starten van een sessie ingestelde cwd hebben voorrang. Ondersteunt ~ en relatieve paden; een afwijkende cwd vereist een uitvoering buiten de sandbox.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`Beslismodel`},help:{"v1-7nd7ze-64":`Optionele provider/model voor getypeerde keuzes, scores en booleaanse waarschijnlijkheden. Niet ingesteld of leeg schakelt beslisaanroepen uit. Ondersteunende plug-ins sturen afgebakende taakgegevens naar deze provider; chat- en hulpmodellen blijven ongewijzigd.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`Ingebedde OpenClaw`},help:{"v1-1keek32-3k":`Beveiligingsinstellingen voor de ingebedde OpenClaw-runner die bepalen hoe lokale agentinstellingen in de werkruimte worden vertrouwd en toegepast in OpenClaw-sessies.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`Terugval bij cyberbeleid`},help:{"v1-xvv6wl-2r":`Automatische escalatie naar Daybreak bij weigeringen op basis van het cyberbeleid van OpenAI in de ingebedde runtime, wanneer opnieuw uitvoeren veilig is.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`Wachttijd voor terugval bij cyberbeleid`},help:{"v1-16smtrl-25":`Hoelang een niet-beschikbaar escalatiedoel wordt overgeslagen tijdens de huidige sessie.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`Modus voor terugval bij cyberbeleid`},help:{"v1-rzsd2b-2h":`Schakel automatische escalatie in ("auto", standaard) of laat weigeringen van de provider definitief blijven ("off").`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emodel":{label:{"v1-1oxd3p3-r":`Model voor terugval bij cyberbeleid`},help:{"v1-1aaj8nn-1t":`Provider/model dat wordt gebruikt als doel voor automatische escalatie bij cyberbeleid.`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`Uitvoeringscontract voor ingebedde OpenClaw`},help:{"v1-1fch2ig-66":`Uitvoeringscontract voor ingebedde OpenClaw: "default" behoudt het standaardgedrag van de runner, terwijl "strict-agentic" gestructureerde planbewaking en niet-zichtbaar herstel van beurten inschakelt voor ondersteunde uitvoeringen met de GPT-5-familie van OpenAI/OpenAI Codex.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`Beleid voor projectinstellingen van ingebedde OpenClaw`},help:{"v1-fdyy04-65":'Hoe ingebedde OpenClaw omgaat met `.openclaw/settings.json` in de werkruimte: "sanitize" (standaard) verwijdert shellPath/shellCommandPrefix, "ignore" schakelt projectinstellingen volledig uit en "trusted" past projectinstellingen ongewijzigd toe.'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`Experimentele agentopties`},help:{"v1-cvv5cl-2w":`Experimentele standaardopties voor agents. Laat deze uitgeschakeld, tenzij u bewust een previewfunctie test.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`Afgeslankte modus voor lokale modellen inschakelen (experimenteel)`},help:{"v1-gj06u6-7b":`Geavanceerde override voor probleemoplossing die optionele tools zoals browser, automations en message beperkt. Standaard uitgeschakeld; ondersteunde lokale runtimes gebruiken automatisch Tool Search zonder deze beperking. Expliciet toegestane tools en vereiste bezorgtools blijven behouden.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`Standaard snelle modus voor agents`},help:{"v1-zv4y98-2z":`Standaardbeleid voor de snelle modus van de agentlus ("auto", true of false). Instellingen voor afzonderlijke agents hebben voorrang.`}},"agents%2Edefaults%2Eheartbeat%2EagentId":{label:{"v1-1kugcom-f":`Heartbeat-agent`},help:{"v1-1jynxej-3w":`Agent die verantwoordelijk is voor heartbeat-uitvoeringen op de achtergrond wanneer er geen heartbeat-configuratie per agent bestaat. Laat dit oningesteld om de geconfigureerde standaardroutering te behouden.`}},"agents%2Edefaults%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Beleid voor directe heartbeat-bezorging`},help:{"v1-nhyxa9-41":`Bepaalt of heartbeats mogen worden bezorgd in directe chats/DM's: "allow" (standaard) staat bezorging via DM toe en "block" blokkeert verzending naar directe ontvangers.`}},"agents%2Edefaults%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Time-out voor heartbeat (seconden)`},help:{"v1-1se21py-5f":`Maximale tijd in seconden voor een heartbeat-agentbeurt voordat deze wordt afgebroken. Laat dit leeg om agents.defaults.timeoutSeconds te gebruiken als deze is ingesteld, anders wordt het heartbeat-interval gebruikt met een maximum van 600 seconden.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`Maximale menselijke vertraging (ms)`},help:{"v1-vnmvli-1m":`Maximale vertraging in ms voor aangepaste humanDelay (standaard: 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`Minimale menselijke vertraging (ms)`},help:{"v1-5nrtr5-1l":`Minimale vertraging in ms voor aangepaste humanDelay (standaard: 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`Modus voor menselijke vertraging`},help:{"v1-k7hyg3-1n":`Vertragingsstijl voor antwoorden in blokken ("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`Maximale afbeeldingsafmeting (px)`},help:{"v1-vju8x-2u":`Maximale zijdelengte van afbeeldingen in pixels bij het opschonen van afbeeldingsgegevens in transcripten en toolresultaten (standaard: 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`Terugvalmodellen voor afbeeldingen`},help:{"v1-1kgx5i9-1b":`Terugvalmodellen voor afbeeldingen in volgorde van voorkeur (provider/model).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`Afbeeldingsmodel`},help:{"v1-dstqyh-2c":`Optioneel afbeeldingsmodel (provider/model) dat wordt gebruikt wanneer het primaire model geen afbeeldingsinvoer ondersteunt.`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`Afbeeldingskwaliteit`},help:{"v1-1uyxc5s-6u":`Voorkeur voor mediacompressie van de afbeeldingstool: "auto" past zich aan de limieten van de provider en het model en het aantal afbeeldingen aan, "efficient" bespaart tokens en bytes, "balanced" behoudt de huidige middenweg en "high" behoudt meer details voor schermafbeeldingen en documentafbeeldingen.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`Terugvalmodellen voor het genereren van afbeeldingen`},help:{"v1-oljfk4-1m":`Terugvalmodellen voor het genereren van afbeeldingen, in volgorde (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`Model voor het genereren van afbeeldingen`},help:{"v1-g4yw0h-2o":`Optioneel model voor het genereren van afbeeldingen (provider/model) dat door de gedeelde functie voor het genereren van afbeeldingen wordt gebruikt.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`Time-out voor het genereren van afbeeldingen (ms)`},help:{"v1-9yesfj-31":`Standaardtime-out in milliseconden voor verzoeken aan de provider bij image_generate-aanroepen. timeoutMs per aanroep overschrijft deze instelling.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`Terugvalmodellen voor het genereren van muziek`},help:{"v1-wyg9xe-1m":`Terugvalmodellen voor het genereren van muziek, in volgorde (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`Model voor het genereren van muziek`},help:{"v1-xs1e2h-2o":`Optioneel model voor het genereren van muziek (provider/model) dat door de gedeelde functie voor het genereren van muziek wordt gebruikt.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`Terugvalmodellen voor het genereren van video's`},help:{"v1-wpbf1e-1m":`Geordende terugvalmodellen voor videogeneratie (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`Model voor videogeneratie`},help:{"v1-hfmlbl-2o":`Optioneel model voor videogeneratie (provider/model) dat wordt gebruikt door de gedeelde videogeneratiefunctie.`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`Time-out voor videogeneratie (ms)`},help:{"v1-1bqj80s-4i":`Standaardtime-out voor aanvragen bij de provider in milliseconden voor video_generate-aanroepen. timeoutMs per aanroep overschrijft deze waarde, en deze waarde overschrijft de standaardwaarden van de provider.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`Terugvalmodellen`},help:{"v1-t4djq2-24":`Geordende terugvalmodellen (provider/model). Worden gebruikt wanneer het primaire model faalt.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`Primair model`},help:{"v1-1i8a1v4-v":`Primair model (provider/model).`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`Modelbeleid`},help:{"v1-z0txb7-2e":`Expliciet beleid voor modeloverschrijvingen. Laat dit weg of laat allow leeg om elk model toe te staan.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`Toegestane modellen`},help:{"v1-1fqace-3x":`Toegestane modelreferenties voor overschrijvingen. Accepteert aliassen, volledige "provider/model"-referenties en jokertekens voor providers zoals "openai/*". Een lege waarde staat elk model toe.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`Modellen`},help:{"v1-13cvq23-4i":`Geconfigureerde modelcatalogus en instellingen per model. Vermeldingen bieden aliassen, parameters, runtimemetadata en overschrijvingen voor Code Mode; ze beperken modeloverschrijvingen niet.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`Modelruntime voor de standaardagent`},help:{"v1-6km9kx-41":`Optioneel runtimebeleid per model voor de standaardagent. Gebruik dit voor modelspecifieke runtime-uitzonderingen in plaats van een runtime voor de hele agent in te stellen.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`Modelruntime-ID voor de standaardagent`},help:{"v1-1co96w7-4a":`Modelruntime-ID voor de standaardagent: "openclaw", "auto", een geregistreerde pluginharnas-ID zoals "codex", of een ondersteunde CLI-backendalias zoals "claude-cli".`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Codemodus`},help:{"v1-rsdl5o-6x":`OpenClaw Code Mode voor precies deze provider en dit model: Aan schakelt de modus geforceerd in, Uit schakelt deze uit en Standaard neemt tools.codeMode.enabled over. Agentspecifieke activeringsinstellingen hebben voorrang. Dit verandert niets aan de geselecteerde runtime of de native Code Mode van Codex.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`Bereik van modelselectie`},help:{"v1-sj8owq-bl":`Bereik voor chatopdrachten en modelupdates voor Gateway-sessies zonder expliciet bereik: "session" (standaard) wijzigt alleen de huidige sessie, "agent" werkt ook het primaire model van die agent bij en "global" werkt ook de gedeelde terugvaloptie agents.defaults.model bij. Expliciete bereikvlaggen hebben voorrang; voor het wijzigen van geconfigureerde standaardwaarden zijn eigenaars- of beheerdersrechten vereist. Telegram-callbackkeuzemenu's en de ingebouwde lokale TUI blijven beperkt tot de sessie.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`Maximale PDF-grootte (MB)`},help:{"v1-1uig1dr-1u":`Maximale PDF-bestandsgrootte in megabytes voor de PDF-tool (standaard: 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`Maximaal aantal PDF-pagina's`},help:{"v1-11na7hp-1y":`Maximaal aantal PDF-pagina's dat de PDF-tool verwerkt (standaard: 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`Terugvalmodellen voor PDF`},help:{"v1-89ebd8-19":`Geordende terugvalmodellen voor PDF (provider/model).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`PDF-model`},help:{"v1-2ktkxt-2y":`Optioneel PDF-model (provider/model) voor de PDF-analysetool. Gebruikt standaard imageModel en daarna het sessiemodel.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`Hoofdmap van repository`},help:{"v1-j3sh74-2h":`Optionele hoofdmap van de repository die wordt weergegeven in de runtimeregel van de systeemprompt (overschrijft automatische detectie).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`CDP-bronpoortbereik voor sandboxbrowser`},help:{"v1-1jkowdc-2b":`Optionele CIDR-toelatingslijst voor inkomend CDP-verkeer aan de containerrand (bijvoorbeeld 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`Netwerk voor sandboxbrowser`},help:{"v1-8m74ud-5w":`Docker-netwerk voor sandboxbrowsercontainers (standaard: openclaw-sandbox-browser). Gebruik het speciaal hiervoor bedoelde standaardnetwerk of een aangepast bridgenetwerk; "none" wordt niet ondersteund omdat browserbesturing gepubliceerde CDP-poorten vereist.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`Aansluiting op containernamespace toestaan voor Docker-sandbox`},help:{"v1-qm39de-4c":`GEVAARLIJKE nooduitzondering die Docker-netwerkmodus container:<id> toestaat voor de sandbox. Hiermee wordt aangesloten op de namespace van een andere container en wordt de sandboxisolatie verzwakt.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`Docker-GPU's voor de sandbox`},help:{"v1-jj0yhw-4k":`Optionele waarde voor GPU-doorgifte in Docker die aan --gpus wordt doorgegeven, bijvoorbeeld "all" of "device=GPU-uuid". Vereist een compatibele hostruntime, zoals NVIDIA Container Toolkit.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`Doel voor verouderde sessieopslag`},help:{"v1-1xkej6i-2g":`Eigenaar voor upgradecompatibiliteit van uitgefaseerde main-agent-rijen en vaste verouderde sessieopslag.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`Eigenaar van verouderde sessieopslag`},help:{"v1-ommm7e-5w":`Agent die na het uitfaseren van de standaardmarkering eigenaar is van uitgefaseerde main-agent-rijen of rijen zonder scope in een vaste verouderde sessieopslag. Wordt tijdens de upgrade automatisch vastgelegd wanneer de vorige eigenaar niet main of de enige agent was.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`Optionele standaardlijst met toegestane vaardigheden die wordt overgenomen door agents die agents.entries.*.skills niet opgeven. Laat deze weg om vaardigheden niet te beperken, stel [] in om overnemende agents geen vaardigheden te geven en houd er rekening mee dat een expliciete agents.entries.*.skills deze standaard vervangt in plaats van ermee te worden samengevoegd.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`Aanmaken van bootstrapbestanden voor de werkruimte overslaan`},help:{"v1-kbstgw-5v":`Slaat het automatisch aanmaken van bootstrapbestanden voor de werkruimte over, maar niet de injectie van bestaande bestanden. Stel voor de ingebedde runtime agents.defaults.contextInjection in op "never" om injectie uit te schakelen, tenzij dit per agent wordt overschreven.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`Overgeslagen optionele bootstrapbestanden`},help:{"v1-1j2z4yj-4c":`Optionele bootstrapbestanden die niet in agentwerkruimten moeten worden aangemaakt. Geldige waarden: SOUL.md, USER.md, IDENTITY.md (HEARTBEAT.md wordt geaccepteerd, maar heeft geen effect).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`Opstartcontext`},help:{"v1-1ugsihy-5o":`Door de runtime beheerde inleiding voor de eerste beurt bij "/new" en "/reset" zonder argumenten. Hiermee bepaal je of recente dagelijkse geheugenbestanden vooraf in de eerste prompt worden geladen, in plaats van het model te laten beslissen wat het moet lezen.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`Opstartcontext toepassen op`},help:{"v1-wav4a5-36":`Bepaalt welke resetopdrachten zonder argumenten opstartcontext krijgen: neem "new", "reset" of beide op (standaard: ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`Aantal dagen dagelijks geheugen voor opstartcontext`},help:{"v1-4i5xcm-3p":`Aantal gedateerde geheugenbestanden om te laden, teruggeteld vanaf vandaag in de ingestelde tijdzone van de gebruiker (standaard: 2 voor vandaag + gisteren).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`Opstartcontext inschakelen`},help:{"v1-1d5vz2u-4i":`Schakel de inleiding met opstartcontext in voor sessieresets zonder argumenten (standaard: true). Schakel dit uit om terug te vallen op gedrag dat alleen op de prompt is gebaseerd, zonder dagelijks geheugen dat door de runtime wordt geladen.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`Maximumaantal bytes per bestand voor opstartcontext`},help:{"v1-11cbian-41":`Maximumaantal toegestane bytes per dagelijks geheugenbestand bij het opbouwen van de opstartcontext (standaard: 16384). Bestanden die deze veilige leeslimiet overschrijden, worden overgeslagen.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`Maximumaantal tekens per bestand voor opstartcontext`},help:{"v1-10z53s-2u":`Maximumaantal tekens dat van elk geladen dagelijks geheugenbestand in de opstartinleiding wordt behouden (standaard: 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`Maximaal totaal aantal tekens in opstartcontext`},help:{"v1-sf676u-54":`Maximaal totaal aantal tekens dat uit alle geladen dagelijkse geheugenbestanden in de opstartinleiding wordt behouden (standaard: 2800). Zodra deze limiet is bereikt, worden aanvullende bestanden in de inleiding afgekapt.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Delegatiemodus voor subagents`},help:{"v1-pqewbk-5o":`Sterkte van de uitsluitend via de prompt gestuurde delegatie aan subagents. Standaard "prefer" in de hoofdsessie van elke agent en "suggest" elders; "prefer" geeft de agent een nadrukkelijke instructie om niet-triviaal werk via sessions_spawn te delegeren.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`Doel van systeemagent`},help:{"v1-1wwimo9-34":`Doelinstellingen voor achtergrondinferentie door de OpenClaw-systeemagent en Custodian, plus geselecteerde leesbewerkingen door operators zonder expliciet bereik.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`Eigenaar van systeemagent`},help:{"v1-15rvt92-8c":`Agent waarvan het model en de inloggegevens worden gebruikt voor achtergrondraadplegingen door de systeemagent en Custodian. Wordt ook gebruikt wanneer models.list, models.authStatus, skills.status, doctor.memory.status of een infer-CLI-opdracht die de model- of authenticatiestatus van een agent bepaalt, geen agentId of --agent opgeeft; een expliciete agentId in de aanvraag heeft altijd voorrang.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`Typinterval (seconden)`},help:{"v1-1y701ox-42":`Bepaalt voor elke agent het interval in seconden waarmee de typindicator actief wordt gehouden. Verhoog dit om de updatefrequentie te verlagen voor alle kanalen die typindicatoren ondersteunen.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`Typmodus`},help:{"v1-m2hvpw-3m":`Bepaalt wanneer de typindicatie voor agents begint: "never", "instant", "thinking" of "message". typingMode per agent overschrijft deze standaardinstelling.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`Hulpmodel`},help:{"v1-1wg7h1a-7s":`Optioneel goedkoper model (provider/model of alias) voor korte interne taken, zoals het genereren van titels en voortgangsbeschrijvingen. Als dit niet is ingesteld, wordt het door de primaire provider opgegeven kleine model gebruikt indien beschikbaar (anders het primaire model); stel een lege tekenreeks in om routering naar het hulpmodel uit te schakelen.`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`Terugvalmodellen voor spraak`},help:{"v1-faazv4-1b":`Geordende lijst met terugvalmodellen voor spraak (provider/model).`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`Spraakmodel`},help:{"v1-1yeh3h4-2t":`Optioneel spraakmodel (provider/model) dat wordt gebruikt voor spraak, transcriptie en realtime spraakfuncties.`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`Time-out voor spraak (ms)`},help:{"v1-1sbergs-32":`Standaardtime-out voor aanvragen aan de provider in milliseconden voor spraakmodelbewerkingen, wanneer de aanroeper time-outs ondersteunt.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`Werkruimte`},help:{"v1-1lssx8l-5w":`Standaardwerkruimte van de agent voor initialisatie- en geheugenbestanden. Wordt ook gebruikt als werkmap wanneer agents.defaults.cwd niet is ingesteld. Stel dit expliciet in bij uitvoering via wrappers, zodat padresolutie deterministisch blijft.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`Agentlijst`},help:{"v1-yurood-5l":`Expliciete lijst van geconfigureerde agents met ID's en optionele overschrijvingen voor model, tools, identiteit en werkruimte. Houd ID's in de loop van de tijd stabiel, zodat koppelingen, goedkeuringen en sessieroutering deterministisch blijven.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`Verouderde agentruntime`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`ID van verouderde agentruntime`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`Maximumaantal tekens voor agentbootstrap`},help:{"v1-rsf1es-4j":`Overschrijving per agent van het maximumaantal tekens voor elk bootstrapbestand uit de werkruimte dat aan de systeemprompt van deze agent wordt toegevoegd. Laat weg om agents.defaults.bootstrapMaxChars over te nemen.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`Maximumaantal tekens voor agentbootstrap in totaal`},help:{"v1-1bal68p-4y":`Overschrijving per agent van het maximumaantal tekens in totaal voor alle bootstrapbestanden uit de werkruimte die aan de systeemprompt van deze agent worden toegevoegd. Laat weg om agents.defaults.bootstrapTotalMaxChars over te nemen.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`Contextinjectie voor agent`},help:{"v1-1j68ys8-50":`Overschrijving per agent voor de injectie van bootstrapbestanden uit de werkruimte in de ingebedde runtime. Laat weg om agents.defaults.contextInjection over te nemen. Heeft geen invloed op promptvoorbereiding via de CLI.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`Contextlimieten voor agent`},help:{"v1-f1qxq8-3c":`Optionele overschrijvingen per agent voor de gerichte instellingen van het contextbudget. Weggelaten velden nemen agents.defaults.contextLimits over.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`Maximumaantal tekens voor memory_get van agent`},help:{"v1-12hlmsv-1v":`Overschrijving per agent van het standaard maximale tekenbudget voor memory_get.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`Maximumaantal tekens na contextverdichting voor agent`},help:{"v1-15s0npd-1w":`Agentspecifieke overschrijving van de maximale lengte van het AGENTS.md-fragment na compactie.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`Werkmap van agent`},help:{"v1-mv43ak-6a":`Werkmap voor de antwoorduitvoeringen van deze agent. Overschrijft agents.defaults.cwd, maar niet de cwd die bij het starten van een sessie is ingesteld; bootstrap- en geheugenbestanden blijven in de werkruimte. Ondersteunt ~ en relatieve paden; een afwijkende cwd vereist uitvoering buiten een sandbox.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`Beslismodel voor agent`},help:{"v1-1mih8bf-3j":`Beslismodel per agent. Indien niet ingesteld, wordt agents.defaults.decisionModel overgenomen; een lege tekenreeks schakelt beslisaanroepen voor deze agent uit.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`Ingebedde OpenClaw voor agent`},help:{"v1-uoomza-4b":`Optionele agentspecifieke overschrijvingen voor ingebedde OpenClaw. Gebruik dit om strikter GPT-5-uitvoeringsgedrag voor specifieke agents in te schakelen zonder de algemene standaardinstelling te wijzigen.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`Uitvoeringscontract voor ingebedde OpenClaw van agent`},help:{"v1-1d1jaoi-7k":`Optionele agentspecifieke overschrijving van het uitvoeringscontract voor ingebedde OpenClaw. Stel "strict-agentic" in om gestructureerde planregistratie en niet-zichtbaar beurtherstel voor die agent in te schakelen bij ondersteunde uitvoeringen met modellen uit de OpenAI/OpenAI Codex GPT-5-familie, of "default" om het standaardgedrag van de uitvoerder over te nemen.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`Experimentele opties voor agent`},help:{"v1-1r06jov-2a":`Agentspecifieke experimentele opties. Weggelaten velden nemen agents.defaults.experimental over.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`Afgeslankte lokale-modelmodus voor agent`},help:{"v1-5o3tgx-58":`Override per agent voor probleemoplossing in de beperkte modus voor lokale modellen. Schakel deze alleen in als het beperken van optionele tools een aangetoonde modelfout oplost, zonder tools voor alle agents te beperken.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`Standaardinstelling voor snelle modus van agent`},help:{"v1-1ujydjc-3o":`Optionele standaardinstelling per agent voor de snelle modus ("auto", true of false). Wordt toegepast wanneer er geen afwijkende instelling voor de snelle modus per bericht of sessie is ingesteld.`}},"agents%2Eentries%2E*%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Beleid voor directe heartbeat-berichten`},help:{"v1-11gl9l0-41":`Afwijkend beleid per agent voor de aflevering van heartbeats via directe berichten/DM's; gebruik "block" voor agents die heartbeat-meldingen alleen naar andere bestemmingen dan DM's mogen sturen.`}},"agents%2Eentries%2E*%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Heartbeat-time-out (seconden)`},help:{"v1-kdetv4-6s":`Maximale tijd per agent in seconden voor een heartbeat-agentbeurt voordat deze wordt afgebroken. Laat dit oningesteld om de samengevoegde heartbeat-time-out over te nemen, vervolgens agents.defaults.timeoutSeconds indien ingesteld, en anders het heartbeat-interval met een maximum van 600 seconden.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`Identiteitsavatar`},help:{"v1-pzp9gr-1t":`Avatar van de agent (pad relatief aan de werkruimte, http(s)-URL of data-URI).`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`Modelbeleid voor agent`},help:{"v1-17d5je8-2r":`Beleid per agent voor afwijkende modelkeuzes. Een expliciete lijst met toegestane modellen vervangt het standaardbeleid voor deze agent.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`Toegestane agentmodellen`},help:{"v1-v1ueke-5b":`Toegestane modelverwijzingen voor afwijkende modelkeuzes voor deze agent. Accepteert aliassen, volledige "provider/model"-verwijzingen en voorvoegsels met een afsluitend jokerteken, zoals "provider/*" of "provider/namespace/*"; indien leeg is elk model toegestaan.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`Afwijkende modelinstellingen voor agent`},help:{"v1-nld1vq-1v":`Overschrijvingen van de modelcatalogus per agent, met volledige provider/model-ID's als sleutels.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`Modelruntime van agent`},help:{"v1-7b59y-3s":`Optioneel runtimebeleid per model voor deze agent. Gebruik dit voor agentspecifieke modeluitzonderingen in plaats van een runtime voor de hele agent in te stellen.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`Modelruntime-ID van agent`},help:{"v1-1ckfc39-46":`Modelruntime-ID per agent: "openclaw", "auto", een geregistreerde plugin-harness-ID zoals "codex", of een ondersteunde CLI-backendalias zoals "claude-cli".`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Codemodus`},help:{"v1-91zu7f-7m":`OpenClaw Code Mode voor deze agent en deze exacte provider/model-combinatie: Aan schakelt de modus geforceerd in, Uit schakelt deze uit en Standaard neemt eerst de activeringsinstelling van de agent over, vervolgens de gedeelde modeloverschrijving en daarna tools.codeMode.enabled. Dit verandert niets aan de geselecteerde runtime of de native Code Mode van Codex.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`Standaardinstelling voor redenering van agent`},help:{"v1-13ly0xf-3m":`Optionele standaardzichtbaarheid van redenering per agent (on|off|stream). Is van toepassing wanneer er geen overschrijving voor redenering per bericht of sessie is ingesteld.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`Runtime van agent`},help:{"v1-avjgkf-3l":`Optionele runtimebeschrijving voor deze agent. Gebruik embedded voor standaarduitvoering met OpenClaw of acp voor standaardinstellingen van een externe ACP-harness.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`ACP-runtime van agent`},help:{"v1-91zvdk-3i":`Standaardinstellingen voor de ACP-runtime van deze agent wanneer runtime.type=acp. ACP-overschrijvingen op bindingsniveau blijven per gesprek voorrang hebben.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`ACP-harnessagent voor de agent`},help:{"v1-1pm98vp-37":`Optionele ID van de ACP-harnessagent voor deze OpenClaw-agent (bijvoorbeeld codex, claude, cursor, gemini, openclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`ACP-backend van de agent`},help:{"v1-1u3cdsg-2n":`Optionele ACP-backendoverschrijving voor de ACP-sessies van deze agent (valt terug op de globale instelling acp.backend).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`ACP-werkmap van de agent`},help:{"v1-d9p9rf-1t":`Optionele standaardwerkmap voor de ACP-sessies van deze agent.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`ACP-modus van de agent`},help:{"v1-yatuk4-21":`Optionele standaardmodus voor ACP-sessies van deze agent (persistent of oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`Runtimetype van de agent`},help:{"v1-139fbk6-2r":`Runtimetype voor deze agent: "embedded" (standaardruntime van OpenClaw) of "acp" (standaardinstellingen voor de ACP-harness).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`CDP-bronbereik voor de sandboxbrowser van de agent`},help:{"v1-1q1qyso-1d":`Overschrijving per agent voor de lijst met toegestane CDP-bronnen in CIDR-notatie.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`Netwerk voor de sandboxbrowser van de agent`},help:{"v1-13bdfww-4c":`Agentspecifieke overschrijving van het Docker-netwerk voor de sandboxbrowser. Gebruik een bridgenetwerk; "none" wordt niet ondersteund omdat browserbesturing gepubliceerde CDP-poorten vereist.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`Deelname aan containernamespace toestaan voor Docker in de agentsandbox`},help:{"v1-1xtnseb-2i":`GEVAARLIJKE agentspecifieke overschrijving voor deelname aan containernamespaces in de Docker-netwerkmodus van de sandbox.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`Docker-GPU's voor de agentsandbox`},help:{"v1-1kek1n2-1t":`Agentspecifieke overschrijving van Docker-GPU-doorgifte voor sandboxcontainers.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`Vaardigheidsfilter voor de agent`},help:{"v1-igchue-6v":`Optionele lijst met toegestane vaardigheden voor deze agent. Als deze ontbreekt, neemt de agent agents.defaults.skills over wanneer dit is ingesteld; anders blijven vaardigheden onbeperkt. Stel [] in om geen vaardigheden toe te staan. Een expliciete lijst vervangt de overgenomen standaardinstellingen volledig in plaats van ermee te worden samengevoegd.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`Limieten voor Skills van de agent`},help:{"v1-1sv10v9-4y":`Optionele agentspecifieke overschrijvingen voor de budgetten van het vaardighedensubsysteem. Gebruik dit wanneer een agent een ander promptbudget voor vaardigheden nodig heeft, zonder een tweede generiek pad voor contextlimieten toe te voegen.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`Maximumaantal tekens in de Skills-prompt van de agent`},help:{"v1-dys63y-52":`Overschrijving per agent van het tekenbudget voor de skills-prompt. Dit breidt het bestaande pad skills.limits.maxSkillsPromptChars uit in plaats van hetzelfde budget via contextLimits te regelen.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Delegatiemodus voor subagenten`},help:{"v1-1rkgh6p-4s":`Overschrijving per agent van de delegatiesterkte voor subagenten. Laat dit weg om "prefer" te gebruiken in de hoofdsessie van deze agent en "suggest" elders; een expliciete waarde "prefer" of "suggest" heeft altijd voorrang.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`Standaarddenkniveau van de agent`},help:{"v1-173q7vy-43":`Optioneel standaarddenkniveau per agent. Overschrijft agents.defaults.thinkingDefault voor deze agent wanneer er geen overschrijving per bericht of sessie is ingesteld.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`Aanvullingen op de lijst met toegestane tools voor de agent`},help:{"v1-1550ui9-46":`Aanvullende lijst met toegestane tools per agent, bovenop het globale beleid en het profielbeleid. Houd deze beperkt om onbedoelde uitbreiding van bevoegdheden bij gespecialiseerde agenten te voorkomen.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`Toolbeleid van de agent per provider`},help:{"v1-mthxv9-4t":`Providerspecifieke overschrijvingen van het toolbeleid per agent om mogelijkheden per kanaal te beheren. Gebruik dit wanneer een afzonderlijke agent bij één provider strengere beperkingen nodig heeft dan bij andere.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`Codemodus van de agent`},help:{"v1-118t8u5-65":`Opties voor Code Mode per agent. Een expliciete waarde voor enabled overschrijft de gedeelde modelinstellingen en de globale standaardinstellingen voor activering; een agentspecifieke codeMode-override voor het model heeft voorrang. Andere opties worden samengevoegd met tools.codeMode en krijgen daarbij voorrang, zonder de activering te wijzigen.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`Time-out voor agentuitvoering (seconden)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`GitHub CLI-identiteitsoverschrijving voor agent`},help:{"v1-mjwdh4-38":`Volledige overschrijving van de beheerde GitHub CLI-identiteit en Git-auteur voor deze agent. Laat dit weg om de systeemidentiteit over te nemen.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`E-mailadres van Git-auteur voor agent`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`Naam van Git-auteur voor agent`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`Type GitHub-inloggegevens voor agent`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`GitHub-profielversie voor agent`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`Lijst met toegestane berichtacties voor agent`},help:{"v1-1g5gov3-67":`Lijst met toegestane berichtacties per agent voor de message-tool. Stel voor openbare sandboxagents een minimale lijst in, zoals ["send"], zodat lezen, bewerken, verwijderen, reageren en andere providerspecifieke berichtacties verborgen en geblokkeerd blijven.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`Contextoverschrijdende berichten voor agent (tussen providers)`},help:{"v1-pehesn-49":`Overschrijving per agent voor het verzenden tussen providers. Neemt de globale instelling over (standaard: true). Stel in op false om berichtenverkeer tussen providers voor deze agent te blokkeren.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`Contextoverschrijdende agentberichten (dezelfde provider)`},help:{"v1-s9u09h-4t":`Berichtbeveiliging per agent voor het verzenden naar andere gesprekken bij dezelfde provider. Stel zowel deze instelling als allowAcrossProviders in op false voor openbare agents die alleen binnen het huidige gesprek mogen communiceren.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`Toolprofiel van agent`},help:{"v1-1du76ix-57":`Afwijkende toolprofielselectie per agent wanneer een agent een andere basisset aan mogelijkheden nodig heeft. Gebruik dit spaarzaam, zodat beleidsverschillen tussen agents bewust gekozen en controleerbaar blijven.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`Agentzwerm`},help:{"v1-420ljs-2c":`Afwijkende zwerminstellingen per agent. Waarden worden samengevoegd met de configuratie tools.swarm op het hoogste niveau en krijgen daarbij voorrang.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`Typemodus van agent`},help:{"v1-oxir52-2e":`Overschrijft voor één agent het standaardbeleid voor het starten van de typindicator, zonder andere agents te wijzigen.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`Hulpmodel van agent`},help:{"v1-1v9oskz-2z":`Optioneel afwijkend hulpmodel per agent voor korte interne taken. Overschrijft agents.defaults.utilityModel.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`Generatie van agenteigenaarschap`},help:{"v1-m2hp61-8g":`Persistente generatiemarkering voor eigenaarschap bij meerdere agents. "explicit" betekent dat achtergrondkanalen, heartbeat, raadplegingen van systeemagents, Talk, cron en losse CLI-bewerkingen een eigenaar voor het specifieke interactieoppervlak moeten bepalen of anders veilig moeten worden geblokkeerd. OpenClaw stelt dit automatisch in bij het aanmaken of migreren van een vloot; laat dit weg bij één enkele agent.`}},approvals:{label:{"v1-1m405m7-9":`Goedkeuringen`},help:{"v1-4y3in-5w":`Instellingen voor het routeren van goedkeuringsverzoeken voor exec en plug-ins naar chatbestemmingen buiten de oorspronkelijke sessie. Houd deze uitgeschakeld tenzij beheerders expliciet inzicht in goedkeuringen buiten de sessie nodig hebben.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`Doorsturen van exec-goedkeuringen`},help:{"v1-1r2mozk-5v":`Groepeert instellingen voor het doorsturen van exec-goedkeuringen, waaronder inschakeling, routeringsmodus, filters en expliciete bestemmingen. Configureer dit wanneer goedkeuringsverzoeken operationele kanalen moeten bereiken in plaats van alleen de oorspronkelijke thread.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`Agentfilter voor goedkeuringen`},help:{"v1-xbuhd3-5i":'Optionele lijst met toegestane agent-ID\'s waarvoor goedkeuringen mogen worden doorgestuurd, bijvoorbeeld `["primary", "ops-agent"]`. Gebruik dit om de reikwijdte van het doorsturen te beperken en te voorkomen dat kanalen meldingen krijgen over niet-gerelateerde agents.'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`Exec-goedkeuringen doorsturen`},help:{"v1-1t0whe8-5s":`Schakelt het doorsturen van exec-goedkeuringsverzoeken naar geconfigureerde bestemmingen in (standaard: false). Houd dit uitgeschakeld in omgevingen met een laag risico en schakel het alleen in wanneer menselijke goedkeurders verzoeken in kanalen moeten kunnen zien.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`Doorstuurmodus voor goedkeuringen`},help:{"v1-1dedfo4-69":`Bepaalt waar goedkeuringsverzoeken naartoe worden gestuurd: "session" gebruikt de oorspronkelijke chat, "targets" gebruikt geconfigureerde bestemmingen en "both" stuurt via beide routes. Gebruik "session" als basis en breid dit alleen uit wanneer de operationele workflow redundantie vereist.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`Sessiefilter voor goedkeuringen`},help:{"v1-smeg8e-5u":'Optionele filters voor sessiesleutels die overeenkomen met deeltekenreeksen of regex-achtige patronen, bijvoorbeeld `["discord:", "^agent:ops:"]`. Gebruik specifieke patronen zodat alleen de beoogde goedkeuringscontexten naar gedeelde bestemmingen worden doorgestuurd.'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`Doelen voor het doorsturen van goedkeuringen`},help:{"v1-17ah848-5u":`Expliciete afleverdoelen die worden gebruikt wanneer de doorstuurmodus doelen omvat, elk met kanaal- en bestemmingsgegevens. Beperk doellijsten volgens het principe van minimale rechten en valideer elke bestemming voordat u breed doorsturen inschakelt.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`Account-ID van goedkeuringsdoel`},help:{"v1-16zopng-5e":`Optionele accountselectie voor kanaalconfiguraties met meerdere accounts wanneer goedkeuringen via een specifieke accountcontext moeten worden gerouteerd. Gebruik dit alleen wanneer voor het doelkanaal meerdere identiteiten zijn geconfigureerd.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`Kanaal van goedkeuringsdoel`},help:{"v1-ji1igl-59":`Kanaal-/provider-ID voor het afleveren van doorgestuurde goedkeuringen, zoals discord, slack of een kanaal-ID van een plug-in. Gebruik alleen geldige kanaal-ID's, zodat goedkeuringen niet ongemerkt mislukken door onbekende routes.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`Thread-ID van goedkeuringsdoel`},help:{"v1-1axynw7-59":`Optionele doelthread of doelonderwerp voor kanalen die het afleveren van doorgestuurde goedkeuringen in threads ondersteunen. Gebruik dit om goedkeuringsverkeer binnen operationele threads te houden in plaats van in hoofdkanalen.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`Bestemming van goedkeuringsdoel`},help:{"v1-1ijng7e-5n":`Bestemmings-ID binnen het doelkanaal (kanaal-ID, gebruikers-ID of hoofdbericht van een thread, afhankelijk van de provider). Controleer de betekenis per provider, omdat de indeling van bestemmingen verschilt per kanaalintegratie.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`Doorsturen van plugingoedkeuringen`},help:{"v1-1m6pzxv-6b":`Bundelt de instellingen voor het doorsturen van plugingoedkeuringen, waaronder inschakeling, routeringsmodus, filters en expliciete doelen. Staat los van het doorsturen van exec-goedkeuringen. Configureer dit hier wanneer verzoeken om plugingoedkeuring operationele kanalen moeten bereiken.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`Agentfilter voor plugingoedkeuringen`},help:{"v1-jb1bra-4b":'Optionele lijst met toegestane agent-ID\'s waarvoor plugingoedkeuringen mogen worden doorgestuurd, bijvoorbeeld `["primary", "ops-agent"]`. Gebruik dit om het bereik van het doorsturen te beperken.'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`Plugingoedkeuringen doorsturen`},help:{"v1-1ntctaf-3v":`Schakelt het doorsturen van verzoeken om plugingoedkeuring naar geconfigureerde bestemmingen in (standaard: false). Staat los van approvals.exec.enabled.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`Doorstuurmodus voor plugingoedkeuringen`},help:{"v1-1h62vy4-3z":`Bepaalt waar verzoeken om plugingoedkeuring naartoe worden gestuurd: "session" gebruikt de oorspronkelijke chat, "targets" gebruikt de geconfigureerde doelen en "both" stuurt ze naar beide.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`Sessiefilter voor plugingoedkeuringen`},help:{"v1-1eppxmt-57":'Optionele filters voor sessiesleutels die overeenkomen met deeltekenreeksen of regex-patronen, bijvoorbeeld `["discord:", "^agent:ops:"]`. Gebruik specifieke patronen zodat alleen goedkeuringsverzoeken uit de beoogde contexten worden doorgestuurd.'}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`Doelen voor het doorsturen van plugingoedkeuringen`},help:{"v1-o92qze-3k":`Expliciete afleverdoelen die worden gebruikt wanneer de doorstuurmodus voor plugingoedkeuringen doelen omvat, elk met kanaal- en bestemmingsgegevens.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`Account-ID van doel voor plugingoedkeuringen`},help:{"v1-1wf3lqn-3j":`Optionele accountselectie voor kanaalconfiguraties met meerdere accounts wanneer plugingoedkeuringen via een specifieke accountcontext moeten worden gerouteerd.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`Doelkanaal voor plugingoedkeuringen`},help:{"v1-1mzhzi9-34":`Kanaal-/provider-ID voor het afleveren van doorgestuurde plugingoedkeuringen, zoals discord, slack of een pluginkanaal-ID.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`Thread-ID van doel voor plugingoedkeuringen`},help:{"v1-1scaw9c-2v":`Optionele doelthread of doelonderwerp voor kanalen die het afleveren van doorgestuurde plugingoedkeuringen in threads ondersteunen.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`Doelbestemming voor plugingoedkeuringen`},help:{"v1-sh5te1-31":`Bestemmings-ID binnen het doelkanaal (kanaal-ID, gebruikers-ID of hoofbericht van een thread, afhankelijk van de provider).`}},attachments:{label:{"v1-8925gh-b":`Bijlagen`},help:{"v1-1xvgkss-40":`Overkoepelend bewaargedrag dat wordt gedeeld door providers en tools die media opslaan. Gebruik ttlHours wanneer algemeen tijdelijk opgeslagen media na een bepaalde termijn moeten worden opgeruimd.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`Bewaarduur van bijlagen (TTL in uren)`},help:{"v1-1g90day-9e":`Optionele bewaartermijn in uren voor opgeslagen media die door de algemene mtime-opschoonronde worden verwerkt. Laat dit oningesteld om die opschoonronde uit te schakelen, of stel waarden in zoals 24 (1 dag) of 168 (7 dagen) om oudere klaargezette media periodiek te verwijderen. Beheerde uitgaande media (in chats gegenereerde bijlagen) zijn uitgesloten en volgen een eigen bewaarbeleid dat rekening houdt met SQLite en transcripten.`}},audio:{label:{"v1-11wczsp-5":`Audio`}},auth:{label:{"v1-5xz433-4":`Authenticatie`},help:{"v1-1eu3aud-5c":`Hoofdconfiguratie voor authenticatieprofielen, gebruikt voor providerreferenties met meerdere profielen en een failovervolgorde op basis van afkoelperiodes. Houd profielen minimaal en expliciet, zodat het automatische failovergedrag controleerbaar blijft.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`Volgorde van authenticatieprofielen`},help:{"v1-1x6kknp-1w":`Geordende authenticatieprofiel-ID's per provider (gebruikt voor automatische failover).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`Authenticatieprofielen`},help:{"v1-kzoqcn-1j":`Benoemde authenticatieprofielen (provider + modus + optioneel e-mailadres).`}},bindings:{label:{"v1-1hcih9f-8":`Toetsbindingen`},help:{"v1-y7hrzb-4i":`Bindingsregels op het hoogste niveau voor routering en blijvend eigenaarschap van ACP-gesprekken. Gebruik type=route voor normale routering en type=acp voor blijvende ACP-harnessbindingen.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`Afwijkende instellingen voor ACP-binding`},help:{"v1-1t4lisi-44":`Optionele afwijkende ACP-instellingen per binding voor bindings[].type=acp. Deze laag overschrijft de standaardinstellingen van agents.entries.*.runtime.acp voor het overeenkomende gesprek.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`Backend voor ACP-binding`},help:{"v1-rsrbkp-2x":`Afwijkende ACP-backend voor deze binding (valt terug op de ACP-backend van de agentruntime en vervolgens op de globale acp.backend).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`Werkmap voor ACP-binding`},help:{"v1-ngpkj0-1y":`Afwijkende werkmap voor ACP-sessies die vanuit deze koppeling worden aangemaakt.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`Label voor ACP-koppeling`},help:{"v1-azce82-23":`Leesbaar label voor ACP-status en -diagnostiek in dit gekoppelde gesprek.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`Modus voor ACP-koppeling`},help:{"v1-cgq8xv-1v":`Afwijkende ACP-sessiemodus voor deze koppeling (persistent of oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`Agent-ID voor koppeling`},help:{"v1-17ra0cl-4m":`ID van de doelagent die verkeer ontvangt wanneer aan de bijbehorende overeenkomstregel voor de koppeling wordt voldaan. Gebruik alleen geldige, geconfigureerde agent-ID's zodat de routering tijdens de uitvoering niet mislukt.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`Overeenkomstregel voor koppeling`},help:{"v1-sc1w2e-51":`Regelobject dat bepaalt wanneer een koppeling van toepassing is, inclusief het kanaal en optionele beperkingen voor accounts of peers. Houd regels specifiek om te voorkomen dat een agent onbedoeld de afhandeling in andere contexten overneemt.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`Account-ID voor koppeling`},help:{"v1-1d209g7-56":`Optionele accountselector voor kanaalconfiguraties met meerdere accounts, zodat de koppeling slechts op één identiteit van toepassing is. Gebruik dit wanneer de route tot een specifiek account moet worden beperkt en laat het anders oningesteld.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`Kanaal voor koppeling`},help:{"v1-d22m5-54":"Kanaal- of provider-ID waarop deze koppeling van toepassing is, zoals `telegram`, `discord` of een kanaal-ID van een plug-in. Gebruik de geconfigureerde kanaalsleutel exact, zodat de koppeling betrouwbaar wordt geëvalueerd."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`Guild-ID voor koppeling`},help:{"v1-jzzfj1-4x":`Optionele beperking op basis van een guild-/server-ID in Discord-stijl voor het evalueren van koppelingen in implementaties met meerdere servers. Gebruik dit wanneer dezelfde peer-ID's in verschillende guilds kunnen voorkomen.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`Peerselectie voor koppeling`},help:{"v1-gcjxff-4i":`Optionele peerselectie voor specifieke gesprekken op basis van peertype en peer-ID. Gebruik dit wanneer slechts één direct gesprek, één groep of één kanaal aan een agent moet worden toegewezen.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`Peer-ID voor koppeling`},help:{"v1-86fbh7-4b":`Gespreks-ID die wordt gebruikt voor peerselectie, zoals een chat-ID, kanaal-ID of groeps-ID van de provider. Neem deze exact over om te voorkomen dat overeenkomsten ongemerkt uitblijven.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`Peertype voor koppeling`},help:{"v1-uufscp-4x":`Gesprekstype van de peer: "direct", "group", "channel" of het verouderde "dm" (verouderde alias voor direct). Gebruik bij voorkeur "direct" voor nieuwe configuraties en stem kind af op de kanaalsemantiek.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`Rollen voor koppeling`},help:{"v1-6s891m-4k":`Optionele filterlijst op basis van rollen, gebruikt door providers die rollen aan de chatcontext toevoegen. Gebruik dit om verkeer van rollen met verhoogde rechten of operationele rollen naar gespecialiseerde agents te routeren.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`Team-ID voor koppeling`},help:{"v1-hh9ps2-48":`Optionele beperking op basis van een team-/werkruimte-ID, gebruikt door providers die chats onder teams indelen. Voeg dit toe wanneer koppelingen tot de context van één werkruimte beperkt moeten blijven.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`Sessie voor koppeling`},help:{"v1-x325l2-4v":`Optionele routespecifieke sessie-instellingen voor gesprekken die onder deze binding vallen. Gebruik dit wanneer een specifieke route dezelfde agent moet behouden, maar de sessiecontinuïteit anders moet isoleren.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`DM-sessiebereik voor binding`},help:{"v1-10sg3xw-4s":`Optionele afwijkende instelling voor het DM-sessiebereik van deze routebinding. Behoud bijvoorbeeld globaal session.dmScope="main" en gebruik "per-account-channel-peer" voor geselecteerde directe gesprekspartners.`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`Groepssessiebereik voor binding`},help:{"v1-1ys2u7k-6n":`Optionele afwijkende instelling voor het sessiebereik van groepen/kanalen voor deze routebinding. "per-group" houdt overeenkomende chatruimtes gescheiden en laat ze op de achtergrond volgen door de hoofdsessie van de agent, ongeacht dmScope; "main" voegt hun context samen in main en vereist geen monitoring.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`Bindingstype`},help:{"v1-172mhtk-3o":`Type binding. Gebruik "route" voor normale routering (of laat dit weg bij oudere routevermeldingen) en "acp" voor permanente ACP-gespreksbindingen.`}},broadcast:{label:{"v1-awqjh0-j":`Groepsthreads voor agents`},help:{"v1-1tz72sr-6b":`Gebruik groepsthreads voor agents om meerdere geconfigureerde agents aan één inkomend gesprek te laten werken, elk in een eigen sessie. Items met een kanaalaanduiding ondersteunen een beperkt aantal vervolgrondes; verouderde arrays met WhatsApp-peers blijven beperkt tot één ronde.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`Deelnemers en opties voor agentgroepen`},help:{"v1-1b63zmt-7d":`Gebruik een peer-ID met een kanaalaanduiding (bijvoorbeeld "telegram:-100123") om een array van agent-ID's of een strikt object met agents, mentionGating, maxRounds en maxTurns te configureren. Items met een kanaalaanduiding hebben voorrang op verouderde WhatsApp-peersleutels en staan maximaal 16 agents toe.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`Deelnemers aan agentgroepen`},help:{"v1-g5o0ky-43":`Agent-ID's van deelnemers uit agents.entries (maximaal: 16). Elke deelnemer gebruikt een eigen sessie voor dit kanaal, account, gesprek en deze thread.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`Maximaal aantal rondes voor de agentgroep`},help:{"v1-i6v4jc-5a":`Maximaal aantal rondes per inkomend bericht, inclusief de eerste ronde (geheel getal: 1–4, standaard: 1). In vervolgrondes worden antwoorden van andere deelnemers in beperkte omvang gedeeld, met vermelding van de afzender. De rondes stoppen wanneer alle deelnemers passen.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`Maximaal aantal beurten voor de agentgroep`},help:{"v1-1kiv8dy-72":`Maximaal aantal deelnemersbeurten per inkomend bericht over alle rondes (geheel getal: 1–32, standaard: agents.length). Beurten worden gereserveerd voordat parallelle uitvoering wordt gestart; dit beperkt agentbeurten, niet afzonderlijke berichtdelen of verzendingen via tools. Budgetten worden na een herstart niet hervat.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`Selectie via vermeldingen voor de agentgroep`},help:{"v1-uay9zu-5u":`Selecteer alleen deelnemers die expliciet met een @vermelding worden genoemd als er overeenkomsten zijn; voer anders alle deelnemers uit (standaard: true). Alleen namen of emoji selecteren geen deelnemers. Toegestane lijsten voor kanalen en toelatingsregels blijven van toepassing.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`Strategie voor de agentgroep`},help:{"v1-p4k9hu-4q":`Uitvoeringsvolgorde van deelnemers: "parallel" (standaard) voert agents gelijktijdig uit, terwijl "sequential" ze in de geconfigureerde volgorde uitvoert. Elke ronde wordt voltooid voordat de volgende begint.`}},browser:{label:{"v1-13dzmen-7":`Browser`},help:{"v1-5b74wi-5l":`Instellingen voor de browserruntime voor lokale of externe CDP-verbindingen, profielroutering en het gedrag van schermafbeeldingen en momentopnamen. Behoud de standaardinstellingen, tenzij uw automatiseringsworkflow aangepaste instellingen voor browsertransport vereist.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`Importeren van systeemprofiel toestaan`},help:{"v1-1lsvlxw-5w":`Hiermee kunnen macOS-hosts cookies uit een lokaal systeemprofiel van een browser uit de Chrome-familie importeren in een beheerd OpenClaw-browserprofiel. Schakel dit uit om het importeren van cookies uit browserprofielen en het bijbehorende toestemmingsverzoek van macOS Keychain te voorkomen.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`Browsermodus voor alleen verbinden`},help:{"v1-xaw7xm-4s":`Beperkt de browsermodus tot alleen verbinden, zonder lokale browserprocessen te starten. Gebruik dit wanneer alle browsersessies extern worden beheerd door een externe CDP-provider.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`CDP-URL van browser`},help:{"v1-2n72jb-65":`URL van het CDP/DevTools-eindpunt waarmee verbinding wordt gemaakt met een extern beheerde browserinstantie. Gebruik dit voor gecentraliseerde browserhosts, tunnels of verbindingen met bestaande sessies, en beperk de toegang tot de URL tot vertrouwde netwerkpaden.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`Standaardbrowserprofiel`},help:{"v1-a6xo96-52":`Naam van het standaardbrowserprofiel dat wordt geselecteerd wanneer aanroepers niet expliciet een profiel kiezen. Gebruik standaard een stabiel profiel met beperkte rechten om onbedoeld gebruik van statusgegevens uit andere contexten te beperken.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`Browser ingeschakeld`},help:{"v1-19qr4oj-56":`Schakelt browserfunctionaliteit in de gateway in, zodat browsertools en CDP-gestuurde workflows kunnen worden uitgevoerd. Schakel dit uit wanneer browserautomatisering niet nodig is om het aanvalsoppervlak en de opstartbelasting te beperken.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`Browserevaluatie ingeschakeld`},help:{"v1-1oa79mq-59":`Schakelt evaluatiehulpmiddelen aan de browserzijde in om scripts tijdens runtime te evalueren, waar dit wordt ondersteund. Laat dit uitgeschakeld, tenzij uw workflows evaluatiefunctionaliteit vereisen die verder gaat dan momentopnamen en navigatie.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`Pad naar uitvoerbaar browserbestand`},help:{"v1-1plb4ki-6i":`Expliciet pad naar het uitvoerbare browserbestand wanneer automatische detectie niet volstaat voor uw hostomgeving. Gebruik een stabiel absoluut pad of een pad dat begint met ~ voor de thuismap van uw besturingssysteem, zodat het opstartgedrag na elke herstart voorspelbaar blijft.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`Relay voor browserextensies`},help:{"v1-6ywlwr-4e":`Compatibiliteitsinstellingen voor relay-authenticatie van Chrome-extensies. Houd de overgangsperiode voor verouderde authenticatie alleen aan zolang oudere gekoppelde extensies of externe CDP-clients die nog nodig hebben.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`Verouderde browserrelay-authenticatie toestaan`},help:{"v1-pj2e90-63":`Accepteert tijdelijk verouderde relay-authenticatie via Bearer, Basic en het token-subprotocol. Standaard: true gedurende één migratieperiode. Stel dit in op false zodra alle extensies en externe CDP-clients Browser Relay Authentication v2 gebruiken.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`Headless-modus voor browser`},help:{"v1-1rswq8j-5a":`Dwingt af dat de browser in headless-modus wordt gestart wanneer het lokale startprogramma browserinstanties start. Houd headless ingeschakeld voor serveromgevingen en schakel dit alleen uit wanneer foutopsporing via een zichtbare gebruikersinterface nodig is.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`Browsermodus zonder sandbox`},help:{"v1-slntux-4w":`Schakelt de flags voor sandboxisolatie van Chromium uit voor omgevingen waarin sandboxing tijdens de uitvoering mislukt. Laat dit waar mogelijk uitgeschakeld, omdat de bescherming door procesisolatie wordt verminderd.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`Browserprofielen`},help:{"v1-1x8lf05-51":`Verbindingsschema voor benoemde browserprofielen, gebruikt voor expliciete routering naar CDP-poorten of URL's met optionele metadata. Houd profielnamen consistent en vermijd overlappende eindpuntdefinities.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`Browserprofielmodus voor alleen verbinden`},help:{"v1-2b5zs0-5a":`Profielspecifieke instelling die het lokaal starten van de browser overslaat en alleen verbinding maakt met een bestaand CDP-eindpunt. Handig wanneer één profiel extern wordt beheerd, terwijl andere lokaal worden gestart.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`CDP-poort van browserprofiel`},help:{"v1-gx1yiq-49":`Lokale CDP-poort per profiel die wordt gebruikt om via een poort in plaats van een URL verbinding te maken met browserinstanties. Gebruik unieke poorten per profiel om verbindingsconflicten te voorkomen.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`CDP-URL van browserprofiel`},help:{"v1-x491r0-64":`URL van het CDP/DevTools-eindpunt per profiel, gebruikt voor expliciete browserroutering op profielnaam. Gebruik dit voor externe CDP-hosts, tunnels of profielen voor bestaande sessies die verbinding moeten maken via een actief Chrome DevTools-eindpunt.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`Browserprofielstuurprogramma`},help:{"v1-17byyx6-5r":`Browserdrivermodus per profiel. Gebruik "openclaw" (of het verouderde "clawd") voor CDP-gebaseerde profielen, "existing-session" voor verbinding via Chrome DevTools MCP of "extension" voor de geauthenticeerde relay van de Chrome-extensie.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`Pad naar uitvoerbaar bestand voor browserprofiel`},help:{"v1-29azyv-4w":`Pad naar het uitvoerbare browserbestand per profiel voor lokaal gestarte beheerde browserprofielen. Overschrijft browser.executablePath en accepteert paden die beginnen met ~ voor de thuismap van het besturingssysteem.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`Headless-modus voor browserprofiel`},help:{"v1-p4jtgv-4u":`Profielspecifieke overschrijving van de headless-instelling voor lokaal gestarte browserinstanties. Gebruik dit als één profiel headless moet blijven zonder browser.headless voor alle andere profielen af te dwingen.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`Chrome MCP-argumenten voor browserprofiel`},help:{"v1-rc45ke-5g":`Extra Chrome DevTools MCP-argumenten per profiel voor verbinding via existing-session, zoals --no-usage-statistics. Eindpuntargumenten hier overschrijven de ingebouwde automatische verbinding of de selectie van de browser-URL.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`Chrome MCP-opdracht voor browserprofiel`},help:{"v1-1xpty8o-2h":`Chrome DevTools MCP-opdracht per profiel voor verbinding via existing-session. Standaard ingesteld op npx.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`Map met gebruikersgegevens voor browserprofiel`},help:{"v1-5xvgex-9h":`Chromium-gebruikersgegevensmap per profiel voor het koppelen aan een bestaande sessie via Chrome DevTools MCP. Gebruik dit voor Brave, Edge, Chromium of niet-standaard Chrome-profielen wanneer de ingebouwde automatische verbinding de verkeerde browsergegevensmap zou kiezen op de geselecteerde host of het geselecteerde browserknooppunt. Paden die beginnen met ~ worden uitgebreid naar de thuismap van het besturingssysteem.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`Standaardinstellingen voor browsersnapshots`},help:{"v1-v19wdy-4y":`Standaardconfiguratie voor het vastleggen van snapshots wanneer aanroepers geen expliciete snapshotopties opgeven. Pas dit aan voor consistent vastleggedrag via verschillende kanalen en automatiseringspaden.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`Browsersnapshotmodus`},help:{"v1-joeyxp-5c":`Standaardextractiemodus voor snapshots die bepaalt hoe pagina-inhoud wordt omgezet voor gebruik door de agent. Kies de modus die leesbaarheid, getrouwheid en tokengebruik in evenwicht brengt voor uw workflows.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`SSRF-beleid voor de browser`},help:{"v1-1qbp9im-5e":`Beveiligingsinstellingen tegen server-side request forgery voor browser- en netwerkophaalpaden die interne hosts kunnen bereiken. Behoud restrictieve standaardinstellingen in productie en sta alleen expliciet goedgekeurde doelen toe.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`Toegestane hostnamen voor de browser`},help:{"v1-1rng39-2k":`Exacte hostnamen of letterlijke IP-adressen die zijn toegestaan bij controles van het SSRF-beleid voor de browser. Houd de lijst zo kort mogelijk.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`Uniek lokaal IPv6-bereik toestaan voor de browser`},help:{"v1-1glx5cy-2c":`Sta unieke lokale IPv6-adressen (fc00::/7) toe voor vertrouwde proxyomgevingen met fictieve IP-adressen.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`Browser: RFC 2544-benchmarkbereik toestaan`},help:{"v1-10ateu3-2i":`IP-adressen in het RFC 2544-benchmarkbereik (198.18.0.0/15) toestaan voor vertrouwde proxyomgevingen met fictieve IP-adressen.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`Browser: geblokkeerde hostnamen`},help:{"v1-nug0we-6k":`Hostnaampatronen die worden geweigerd vóór DNS-resolutie en toestemmingsregels, ook als toegang tot privénetwerken is ingeschakeld. Ondersteunt exacte hostnamen en "*.example.com" voor uitsluitend subdomeinen; voeg "example.com" afzonderlijk toe om het hoofddomein te blokkeren. Een lege of niet-ingestelde waarde voegt geen blokkeringen toe.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`Browser: privénetwerk toestaan (gevaarlijk)`},help:{"v1-17103pi-4m":`Staat toegang tot adresbereiken van privénetwerken toe vanuit browsertools. Standaard uitgeschakeld als er geen waarde is ingesteld; schakel dit alleen in voor expliciet vertrouwde bestemmingen op privénetwerken.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`Browser: tabbladen opruimen`},help:{"v1-1ctwaad-4y":`Beleid om tabbladen die door sessies van de primaire agent zijn geopend zo goed mogelijk op te ruimen. Laat dit ingeschakeld om te voorkomen dat verouderde tabbladen in sandboxen of beheerde browsers zich ophopen bij langdurig actieve gateways.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`Browser: tabbladen opruimen ingeschakeld`},help:{"v1-4sv97p-3u":`Schakelt het opruimen in van bijgehouden, inactieve browsertabbladen voor sessies van de primaire agent. Schakel dit alleen uit als externe tools de levenscyclus van tabbladen volledig beheren.`}},channels:{label:{"v1-1ju93md-8":`Kanalen`},help:{"v1-12yv6ma-5n":`Configuraties voor kanaalproviders en gedeelde standaardinstellingen die het toegangsbeleid, de zichtbaarheid van heartbeats en het gedrag per interface bepalen. Houd standaardinstellingen centraal en overschrijf ze alleen per provider waar dat nodig is.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`Standaardinstellingen voor kanalen`},help:{"v1-uz6veb-4p":`Standaardgedrag voor kanalen dat voor alle providers geldt wanneer er geen providerspecifieke instellingen zijn ingesteld. Gebruik dit om een consistent basisbeleid af te dwingen voordat u de instellingen per provider verfijnt.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`Standaardbeveiliging tegen botlussen`},help:{"v1-1lpznyk-4w":`Standaardinstellingen voor lusbeveiliging per paar voor kanaalproviders die beveiliging tegen lussen tussen bots ondersteunen. Gebruik providerspecifieke overschrijvingen alleen wanneer een kanaal een andere limiet nodig heeft.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`Standaardwachttijd voor botlussen in seconden`},help:{"v1-1yl5ird-2z":`Wachttijd in seconden die voor een paar geldt nadat het de luslimiet heeft overschreden. De standaardwaarde voor kanalen die dit ondersteunen is 60.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`Standaardbeveiliging tegen botlussen ingeschakeld`},help:{"v1-3ruik-4r":`Schakelt lusbeveiliging per paar standaard in voor kanalen die dit ondersteunen wanneer door bots geschreven berichten kunnen worden doorgestuurd. Providers kunnen de beveiliging nog steeds uitschakelen wanneer bots worden genegeerd.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`Standaardaantal botlusgebeurtenissen per tijdvenster`},help:{"v1-1u0mdjc-41":`Maximaal aantal gebeurtenissen dat een zender-ontvangerpaar binnen het ingestelde tijdvenster mag uitwisselen voordat de onderdrukking begint. De standaardwaarde voor kanalen die dit ondersteunen is 20.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`Standaardtijdvenster voor botlussen in seconden`},help:{"v1-12xpmen-2m":`Lengte van het schuivende tijdvenster in seconden voor luslimieten per paar. De standaardwaarde voor kanalen die dit ondersteunen is 60.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`Standaardzichtbaarheid van context`},help:{"v1-1hze3g1-5o":`Standaardzichtbaarheid van aanvullende context voor opgehaalde citaten, gespreksthreads en geschiedenis: "all" (alle context behouden), "allowlist" (alleen afzenders op de toestemmingslijst) of "allowlist_quote" (toestemmingslijst + expliciete citaten behouden).`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`Standaardgroepsbeleid`},help:{"v1-ntl9m4-4n":`Standaardgroepsbeleid voor alle kanalen: "open", "disabled" of "allowlist". Behoud "allowlist" voor veiligere productieomgevingen, tenzij brede deelname aan groepen de bedoeling is.`}},"channels%2Edefaults%2EheartbeatVisibility":{label:{"v1-knuq96-s":`Standaardzichtbaarheid van heartbeats`},help:{"v1-49bw75-4v":`Standaardinstellingen voor de zichtbaarheid van heartbeat-statusberichten van providers/kanalen. Pas dit globaal aan om overbodige updates over een gezonde status te verminderen en waarschuwingen zichtbaar te houden.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowAlerts":{label:{"v1-8z6943-l":`Heartbeat-waarschuwingen tonen`},help:{"v1-8dk8zx-4g":`Toont heartbeat-waarschuwingen bij verminderde werking of fouten als dit op true staat, zodat problemen snel zichtbaar worden in beheerderskanalen. Laat dit ingeschakeld in productie om storingen in kanalen zichtbaar te houden.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowOk":{label:{"v1-z25yzy-h":`Heartbeat-OK-status tonen`},help:{"v1-17tg3mk-4z":`Toont bij true heartbeatstatusvermeldingen met de status gezond/OK in kanaalstatusoverzichten. Houd dit op false in omgevingen met veel meldingen en schakel het alleen in als beheerders expliciete bevestigingen van een gezonde status nodig hebben.`}},"channels%2Edefaults%2EheartbeatVisibility%2EuseIndicator":{label:{"v1-16d7e6t-n":`Indicator gebruiken voor heartbeat`},help:{"v1-1w12cs2-4m":`Schakelt waar ondersteund een compacte heartbeatweergave met indicatoren in, in plaats van uitgebreide statustekst. Gebruik de indicatormodus voor compacte dashboards met veel actieve kanalen.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`Standaard impliciete vermeldingen`},help:{"v1-4gtdyv-48":`Standaardbeleid dat bepaalt of antwoorden op de bot, citaten van de bot en deelname van de bot aan een thread berichtkanalen die dit ondersteunen activeren zonder expliciete vermelding.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`Standaard impliciete vermeldingen bij botcitaten`},help:{"v1-va1u5v-2v":`Behandel geciteerde botberichten standaard als impliciete vermeldingen. Staat standaard op true voor achterwaartse compatibiliteit.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`Standaard impliciete vermeldingen bij antwoorden op de bot`},help:{"v1-lm44c3-39":`Behandel antwoorden op de eigen berichten van de bot standaard als impliciete vermeldingen. Staat standaard op true voor achterwaartse compatibiliteit.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`Standaard impliciete vermeldingen bij threaddeelname`},help:{"v1-160205h-3o":`Behandel vervolgberichten in threads waaraan de bot heeft deelgenomen standaard als impliciete vermeldingen. Staat standaard op true voor achterwaartse compatibiliteit.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`Modeloverschrijvingen per kanaal`},help:{"v1-1b01spx-2p":`Koppel provider -> kanaal-id / DM-contact-id -> modeloverschrijving (waarden zijn provider/model of aliassen).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`Cloudworkers`},help:{"v1-10carc4-5v":`Optionele cloudworkerprofielen voor tijdelijke externe omgevingen. Als deze sectie ontbreekt of geen profielen bevat, blijft het aanmaken van cloudworkers niet beschikbaar en blijft het bestaande statusgedrag van gateway/nodes ongewijzigd.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`Cloudworkerdesktop (Labs)`},help:{"v1-vllayc-3n":`Schakelt de experimentele interface worker.desktop.observe en het desktoppaneel in de Control UI in voor cloudworkeromgevingen met desktopondersteuning.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`Pool van voorbereide cloudworkers`},help:{"v1-rw51o5-6b":`Limieten voor voorbereide cloudworkers die voor latere sessies worden klaargehouden. Voor gereserveerde workers worden kosten voor draaiende machines in rekening gebracht totdat de provider de opschoning heeft voltooid; hun vaste vervaltijd wordt bepaald door de daadwerkelijke projectvraag en het bestaande inactiviteitsbeleid van de provider.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`Maximumaantal gereedstaande cloudworkers in reserve`},help:{"v1-1mpd1dt-7u":`Maximumaantal niet-toegewezen, voorbereide cloudworkers voor de hele Gateway, over alle projecten en profielen heen (standaard: 4). Workers die worden voorbereid en reserves waarvan de opruiming nog niet is bevestigd, tellen mee voor dit maximum. Stel 0 in om niet-toegewezen reserves af te bouwen en aanvulling uit te schakelen, met behoud van snapshothergebruik en actieve sessies.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`Cloudworkerprofielen`},help:{"v1-eii67l-3j":`Cloudworkerprofielen met een naam. Elk profiel selecteert een workerprovider die door een plug-in is geregistreerd en bevat providerspecifieke instellingen.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`Cloudworkerprofiel`},help:{"v1-1v2w7jl-4u":`Eén cloudworkerprofiel dat bij het aanmaken van een omgeving op naam wordt geselecteerd. Bewaar de inloggegevens voor de provider in ondersteunde verwijzingen in plaats van geheime gegevens in dit blok op te nemen.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`Installatiemethode voor cloudworkers`},help:{"v1-blrtbf-74":`Installatiemethode voor workers: "bundle" (standaard) draagt de geïnstalleerde build van de gateway met inhoudshash over en ondersteunt uitgebrachte versies, ontwikkelversies en niet-uitgebrachte versies; "npm" installeert exact dezelfde gatewayversie en is alleen beschikbaar als die versie is uitgebracht.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`Cloudworkerprovider`},help:{"v1-1p4s4c1-44":`Provider-id voor workers die door een plug-in is geregistreerd. De geconfigureerde plug-in moet deze id beschikbaar stellen voordat de gateway omgevingen op basis van het profiel kan inrichten.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`Streefaantal gereedstaande cloudworkers in reserve`},help:{"v1-1nwve9s-7w":`Streefaantal niet-toegewezen, voorbereide workers per in aanmerking komend project dat dit profiel gebruikt (standaard: 1), begrensd door het maximum voor de pool van voorbereide workers voor de hele Gateway. Stel 0 in om reserves voor dit profiel uit te schakelen, met behoud van snapshothergebruik. Workers die worden voorbereid en reserves waarvan de opruiming nog niet is bevestigd, tellen mee voor het streefaantal.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`Providerinstellingen voor cloudworkers`},help:{"v1-mq7u32-4j":`Providerspecifieke instellingen die door de geselecteerde plug-in worden gevalideerd. Gebruik SecretRef-objecten voor waarden die geheimen bevatten; ondoorzichtige instellingen krijgen geen automatische omzetting van geheimverwijzingen.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`Inactiviteitsduur vóór opschorting van cloudworkers`},help:{"v1-1keuwgh-4w":`Geeft de resources van een inactieve cloudworker na deze duur automatisch vrij, bijvoorbeeld 45m of 2h; bij het volgende bericht wordt een vervanger ingericht. Minimum: 1m. Laat dit oningesteld om workers actief te houden.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`Projectprofielen voor cloudworkers`},help:{"v1-1kkfrif-46":`Standaardprofielnamen voor cloudworkers, met de genormaliseerde repository-identiteit in kleine letters (host/owner/repo) als sleutel. Expliciete profiel-id's voor dispatch hebben voorrang.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`Projectprofiel voor cloudworkers`},help:{"v1-1mux5u0-30":`Profielnaam voor cloudworkers die standaard wordt gebruikt wanneer de origin van de worktree van een sessie overeenkomt met deze repository-identiteit.`}},commands:{label:{"v1-15x4mpf-8":`Opdrachten`},help:{"v1-1gi0dr2-5a":`Bepaalt de beschikbaarheid van chatopdrachten, toegangsbeperkingen voor eigenaren en toegang tot opdrachten met verhoogde rechten bij alle providers. Behoud de standaardinstellingen, tenzij u strengere beheerdersbeperkingen of een bredere beschikbaarheid van opdrachten nodig hebt.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`Regels voor opdrachttoegang met verhoogde rechten`},help:{"v1-7azkw-5g":`Definieert per kanaal en afzender welke opdrachten met verhoogde rechten zijn toegestaan in opdrachtinterfaces op eigenaarsniveau. Gebruik specifiek afgebakende, providerspecifieke identiteiten, zodat opdrachten met verhoogde rechten niet beschikbaar zijn voor een breed chatpubliek.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Bash-chatopdracht toestaan`},help:{"v1-83ah7w-36":"Sta de bash-chatopdracht (`!`; alias `/bash`) toe om shellopdrachten op de host uit te voeren (standaard: false; vereist tools.elevated)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Bash-voorgrondduur (ms)`},help:{"v1-1o0o4dw-2c":`Hoelang bash wacht voordat het naar de achtergrond gaat (standaard: 2000; bij 0 gaat het direct naar de achtergrond).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`/config toestaan`},help:{"v1-151bb7c-21":`Sta de chatopdracht /config toe om configuratie op schijf te lezen en te schrijven (standaard: false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`/debug toestaan`},help:{"v1-y1lc3j-1y":`Sta de chatopdracht /debug toe voor tijdelijke aanpassingen die alleen tijdens de uitvoering gelden (standaard: false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`/mcp toestaan`},help:{"v1-1rtwcgd-2o":`Sta de chatopdracht /mcp toe om de OpenClaw MCP-serverconfiguratie onder mcp.servers te beheren (standaard: false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`Native opdrachten`},help:{"v1-dighr2-5n":`Registreert native slash- en menuopdrachten bij kanalen die opdrachtregistratie ondersteunen (Discord, Slack, Telegram). Laat dit ingeschakeld zodat opdrachten gemakkelijk te vinden zijn, tenzij u bewust uitsluitend tekstgebaseerde opdrachtworkflows gebruikt.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`Native skillopdrachten`},help:{"v1-19gtqci-5h":`Registreert native skillopdrachten zodat gebruikers skills rechtstreeks vanuit de opdrachtmenu's van providers kunnen aanroepen, waar dit wordt ondersteund. Stem dit af op uw skillbeleid, zodat de beschikbare opdrachten overeenkomen met wat beheerders verwachten.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`Opdrachteigenaren`},help:{"v1-1di38gv-3y":`Expliciete lijst met toegestane eigenaren voor opdrachten die alleen eigenaren mogen gebruiken. Gebruik kanaaleigen ID's (eventueel met een voorvoegsel zoals "whatsapp:+15551234567"). '*' wordt genegeerd.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`/plugins toestaan`},help:{"v1-akwy9y-33":`Sta de chatopdracht /plugins toe om gevonden plug-ins weer te geven en plug-ins in de configuratie in of uit te schakelen (standaard: false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`Herstarten toestaan`},help:{"v1-m32fv2-27":`Sta /restart, /update en externe SIGUSR2-herstartverzoeken toe (standaard: true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`Tekstopdrachten`},help:{"v1-1utu76s-5j":`Schakelt de verwerking van tekstopdrachten in chatinvoer in, naast ingebouwde opdrachtinterfaces waar beschikbaar. Houd dit ingeschakeld voor compatibiliteit met kanalen die geen ingebouwde opdrachtregistratie ondersteunen.`}},cron:{label:{"v1-1qlte4b-b":`Automatiseringen`},help:{"v1-4md8ic-5u":`Algemene plannerinstellingen voor opgeslagen automatiseringen, gelijktijdige uitvoeringen, terugvalopties voor aflevering en de bewaartermijn van uitvoeringssessies. Behoud de standaardinstellingen, tenzij u het aantal automatiseringen opschaalt of externe webhookontvangers integreert.`}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`Automatiseringen ingeschakeld`},help:{"v1-y8otx6-5i":`Schakelt de uitvoering van automatiseringen in voor opgeslagen schema's die door de gateway worden beheerd. Houd dit ingeschakeld voor normale herinnerings- en automatiseringsprocessen en schakel het alleen uit om alle automatiseringen te pauzeren zonder taken te verwijderen.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`Bewaartermijn van automatiseringssessies`},help:{"v1-4wagu6-7e":"Bepaalt hoelang sessies van voltooide automatiseringsuitvoeringen worden bewaard voordat ze worden opgeschoond (`24h`, `7d`, `1h30m` of `false` om opschoning uit te schakelen; een duur van nul, zoals `0h`, schakelt opschoning ook uit; standaard: `24h`). Gebruik een kortere bewaartermijn om de groei van de opslag bij frequent uitgevoerde schema's te beperken."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`Gemiste terugkerende automatiseringen overslaan`},help:{"v1-w9wfmo-66":`Slaat gemiste terugkerende cron/every-uitvoermomenten over bij het opstarten van de Gateway en plant het eerstvolgende toekomstige uitvoermoment in plaats van ze in te halen. Standaard: false. Schakel dit in om verouderde herinneringen na uitval te voorkomen; eenmalige at-taken worden nog steeds ingehaald.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`SSRF-beleid voor automatiseringswebhooks`},help:{"v1-1xlfqnu-5h":`SSRF-beleid dat op elke uitgaande automatiseringswebhook wordt toegepast. Privé-, loopback-, link-local- en interne bestemmingen blijven geblokkeerd tenzij dit beleid ze expliciet toestaat. Laat dit oningesteld voor strikte aflevering.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`Toegestane hostnamen voor automatiseringswebhooks`},help:{"v1-1i94hyz-3n":`Exacte hostnamen of letterlijke IP-adressen die zijn toegestaan voor de aflevering van automatiseringswebhooks, inclusief bestemmingen die anders worden geblokkeerd. Houd de lijst zo beperkt mogelijk.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`Uniek lokaal IPv6-bereik toestaan voor automatiseringswebhooks`},help:{"v1-rke0oj-3b":`Staat automatiseringswebhooks naar unieke lokale IPv6-adressen (fc00::/7) toe. Gebruik dit alleen in vertrouwde proxyomgevingen met fake-IP.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`RFC 2544-benchmarkbereik toestaan voor automatiseringswebhooks`},help:{"v1-x1usg4-3h":`Staat automatiseringswebhooks naar IP-adressen in het RFC 2544-benchmarkbereik (198.18.0.0/15) toe. Gebruik dit alleen in vertrouwde proxyomgevingen met fictieve IP-adressen.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`Geblokkeerde hostnamen voor automatiseringswebhooks`},help:{"v1-16cv1ic-6a":`Hostnaampatronen die bij de aflevering van automatiseringswebhooks worden geblokkeerd vóór DNS-resolutie en de toepassing van toestemmingsregels. Ondersteunt exacte hostnamen en "*.example.com" voor uitsluitend subdomeinen; voeg "example.com" afzonderlijk toe om het hoofddomein te blokkeren. Als dit leeg of niet ingesteld is, worden er geen blokkeringen toegevoegd.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`Privénetwerk toestaan voor automatiseringswebhooks (gevaarlijk)`},help:{"v1-1n9710c-3t":`Staat automatiseringswebhooks naar bestemmingen in privé- en interne netwerken toe. Laat dit uitgeschakeld tenzij elke geconfigureerde webhookbestemming vertrouwd is.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`Bearer-token voor automatiseringswebhooks`},help:{"v1-1l90hxg-5l":`Bearer-token dat wordt meegestuurd met POST-verzoeken van automatiseringswebhooks wanneer de webhookmodus wordt gebruikt. Gebruik bij voorkeur substitutie via geheimen of omgevingsvariabelen en vervang dit token regelmatig als gedeelde webhookeindpunten via internet bereikbaar zijn.`}},desktop:{label:{"v1-rs698z-7":`Bureaublad`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`Lokaal bureaublad`},help:{"v1-99weio-30":`Bureaubladobservatie voor gekoppelde nodes of de experimentele Gateway-hostbron, via een lokale VNC-server.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`Bureaublad delen`},help:{"v1-m9lbcj-83":`Schakelt de desktopbron van deze machine in. Gekoppelde macOS-, Windows- en Linux-nodes zijn standaard ingeschakeld; een expliciete voorkeur voor delen in de desktop-app heeft voorrang. De Labs-bron op de Gateway-host is standaard uitgeschakeld en past wijzigingen direct toe. Start een gekoppelde node opnieuw op nadat je de desktopconfiguratie ervan hebt gewijzigd.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`Beheerd bureaublad van de Linux-host`},help:{"v1-1r7n22m-49":`Start en bewaakt een headless TigerVNC/XFCE-desktop op Linux die alleen via loopback bereikbaar is. Een expliciet ingestelde poort of een bestaande VNC-server op de standaardpoort heeft nog steeds voorrang.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`Lokaal VNC-wachtwoordbestand`},help:{"v1-1m5lsox-37":`Absoluut pad naar het VNC-wachtwoordbestand. Laat dit op macOS weg om accountgegevens in te voeren bij het openen van de bureaubladviewer.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`Lokale VNC-poort`},help:{"v1-1ku4w9b-2b":`RFB-loopbackpoort van een al actieve VNC-server op deze machine (standaard: 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`Diagnostiek`},help:{"v1-1d5rnym-5p":`Diagnostische instellingen voor gerichte tracering, telemetrie-export en cache-inspectie tijdens het debuggen. Beperk de basisdiagnostiek in productie tot een minimum en schakel uitgebreidere signalen alleen in bij het onderzoeken van problemen.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`Cachetracering`},help:{"v1-10523zm-5b":`Loginstellingen voor cachetracering om cachebeslissingen en payloadcontext tijdens ingebedde uitvoeringen te observeren. Schakel dit tijdelijk in voor het debuggen en schakel het daarna uit om de hoeveelheid gevoelige gegevens in logs te beperken.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`Cachetracering ingeschakeld`},help:{"v1-2c1umi-1v":`Leg momentopnamen van cachetracering vast voor ingebedde agentuitvoeringen (standaard: false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`Diagnostiek ingeschakeld`},help:{"v1-a46pxt-4h":`Hoofdschakelaar voor de uitvoer van diagnostische instrumentatie in logs en telemetriekoppelingen. Standaard ingeschakeld; stel alleen in sterk beperkte omgevingen in op false.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`Diagnostische vlaggen`},help:{"v1-x4w5ok-33":`Schakel gerichte diagnostische logging in per vlag (bijv. ["telegram.http"]). Ondersteunt jokertekens zoals "telegram.*" of "*".`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`OpenTelemetry-exportinstellingen voor traces, meetwaarden en logs die door Gateway-componenten worden gegenereerd. Gebruik dit voor integratie met gecentraliseerde observability-backends en pijplijnen voor gedistribueerde tracing.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`Inhoud vastleggen met OpenTelemetry`},help:{"v1-19tid4t-2t":`Optioneel vastleggen van inhoud in OTEL-spans. Standaard uitgeschakeld; true legt de inhoud van niet-systeemberichten en tools vast.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry ingeschakeld`},help:{"v1-193bm0-5b":`Schakelt de OpenTelemetry-exportpijplijn in voor traces, meetwaarden en logs op basis van de geconfigureerde eindpunt- en protocolinstellingen. Laat dit uitgeschakeld tenzij het collector-eindpunt en de authenticatie volledig zijn geconfigureerd.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`OpenTelemetry-eindpunt`},help:{"v1-4rrd1x-4y":`URL van het collector-eindpunt voor OpenTelemetry-exporttransport, inclusief schema en poort. Gebruik een bereikbaar, vertrouwd collector-eindpunt en controleer na de uitrol op fouten bij de gegevensinname.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`OpenTelemetry-verzendinterval (ms)`},help:{"v1-1moqogc-53":`Interval in milliseconden voor het periodiek verzenden van telemetrie uit buffers naar de collector. Verhoog dit om het aantal exportverzoeken te verminderen, of verlaag het voor sneller inzicht tijdens actieve incidentafhandeling.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`OpenTelemetry-headers`},help:{"v1-s26t2a-52":`Aanvullende HTTP-aanvraagheaders die met OpenTelemetry-exportaanvragen worden verzonden, vaak gebruikt voor tenantauthenticatie of routering. Bewaar geheimen in waarden die uit omgevingsvariabelen worden opgehaald en vermijd onnodige wildgroei aan headers.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`OpenTelemetry-logs ingeschakeld`},help:{"v1-12wo6rv-4k":`Schakel de export van logsignalen via OpenTelemetry in, naast lokale logbestemmingen. Gebruik dit wanneer centrale logcorrelatie tussen services en agents vereist is.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`OpenTelemetry-logeindpunt`},help:{"v1-1vgzldu-40":`Signaalspecifiek OTLP/HTTP-logeindpunt. Indien ingesteld, heeft dit voorrang op diagnostics.otel.endpoint en OTEL_EXPORTER_OTLP_ENDPOINT, uitsluitend voor logexport.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`OpenTelemetry-logexporter`},help:{"v1-9bzywd-5q":`Logexportbestemming voor diagnostics.otel.logs. Gebruik "otlp" voor het geconfigureerde OTLP-logeindpunt, "stdout" voor één JSON-record per stdout-regel in containerlogpijplijnen en "both" wanneer beide bestemmingen vereist zijn.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`Voorvoegsel voor OpenTelemetry-metrieknamen`},help:{"v1-1epdpi9-b2":`Vervangt het standaardvoorvoegsel "openclaw." in metrieknamen van OpenClaw. Gebruik een lege tekenreeks om het voorvoegsel te verwijderen, of maximaal 128 ASCII-letters, cijfers, underscores, punten, koppeltekens en schuine strepen, beginnend met een letter. Neem het gewenste scheidingsteken op, bijvoorbeeld "acme."; standaardmetrieknamen van gen_ai.* blijven ongewijzigd. Als u deze waarde wijzigt, moet u dashboards en waarschuwingen bijwerken die de oude namen opvragen.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`OpenTelemetry-metrieken ingeschakeld`},help:{"v1-13r4cf4-4x":`Schakel de export van metriekgegevens naar het geconfigureerde OpenTelemetry-collectoreindpunt in. Laat dit ingeschakeld voor dashboards die de runtimestatus bewaken en schakel het alleen uit als het volume aan metriekgegevens moet worden beperkt.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`OpenTelemetry-eindpunt voor metriekgegevens`},help:{"v1-qlfh7x-47":`Signaalspecifiek OTLP/HTTP-eindpunt voor metriekgegevens. Indien ingesteld, overschrijft dit diagnostics.otel.endpoint en OTEL_EXPORTER_OTLP_ENDPOINT uitsluitend voor de export van metriekgegevens.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`OpenTelemetry-protocol`},help:{"v1-17ine8s-5e":`OTel-transportprotocol voor telemetrie-export. Alleen "http/protobuf" wordt geaccepteerd; voer "openclaw doctor --fix" uit om een opgeslagen verouderde waarde "grpc" te herstellen of bronspecifieke instructies voor handmatige bewerking te krijgen.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`OpenTelemetry-steekproeffractie voor traces`},help:{"v1-brcwep-50":`Steekproeffractie voor traces (0-1) die bepaalt hoeveel traceverkeer naar observability-backends wordt geëxporteerd. Lagere waarden verminderen de overhead en kosten, terwijl hogere waarden meer detail bieden bij het debuggen.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`OpenTelemetry-servicenaam`},help:{"v1-1hpiqon-5d":`Servicenaam die in telemetrie-resourceattributen wordt gerapporteerd om deze gateway-instantie in observability-backends te identificeren. Gebruik vaste namen zodat dashboards en waarschuwingen consistent blijven bij nieuwe implementaties.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`OpenTelemetry-traces ingeschakeld`},help:{"v1-j7zrrp-4s":`Schakel de export van tracegegevens naar het geconfigureerde OpenTelemetry-collectoreindpunt in. Laat dit ingeschakeld wanneer tracing voor latentieanalyse of debugging nodig is en schakel het uit als u alleen metriekgegevens en logs wilt.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`OpenTelemetry-trace-eindpunt`},help:{"v1-8yw5p1-43":`Signaalspecifiek OTLP/HTTP-trace-eindpunt. Als dit is ingesteld, overschrijft het diagnostics.otel.endpoint en OTEL_EXPORTER_OTLP_ENDPOINT uitsluitend voor de export van traces.`}},discovery:{label:{"v1-l2sr05-9":`Detectie`},help:{"v1-1sqleij-4w":`Instellingen voor servicedetectie via lokale mDNS-aankondigingen en optionele aanwezigheidssignalering buiten het lokale netwerk. Beperk detectie tot de beoogde netwerken om het lekken van servicemetadata te voorkomen.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`mDNS-detectie`},help:{"v1-vtbyyq-4w":`Configuratiegroep voor mDNS-detectie om aankondigingen op het lokale netwerk en het detectiegedrag af te stemmen. Gebruik de minimale modus voor normale LAN-detectie, tenzij extra metadata vereist zijn.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`mDNS-detectiemodus`},help:{"v1-1p28pd5-2m":`mDNS-uitzendmodus (standaard "minimal", "full" bevat cliPath/sshPort, "off" schakelt mDNS uit).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`Detectie buiten het lokale netwerk`},help:{"v1-1akkqjm-53":`Configuratiegroep voor detectie buiten het lokale netwerk om detectiesignalen buiten het lokale linkbereik beschikbaar te maken. Schakel dit alleen in bij implementaties die bewust de aanwezigheid van gateways op meerdere locaties samenbrengen.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`Domein voor detectie buiten het lokale netwerk`},help:{"v1-rxrygo-4m":`Optioneel unicast-DNS-SD-domein voor detectie buiten het lokale netwerk, zoals openclaw.internal. Gebruik dit als u gatewaydetectie bewust buiten het lokale mDNS-bereik publiceert.`}},env:{label:{"v1-1zc80q-b":`Omgeving`},help:{"v1-1ao5po6-55":`Instellingen voor het importeren en overschrijven van omgevingsvariabelen die tijdens de uitvoering aan het gatewayproces worden doorgegeven. Gebruik deze sectie om het laden van de shellomgeving en het expliciet invoegen van variabelen te beheren.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Shellomgeving importeren`},help:{"v1-1gw487t-4y":`Instellingen voor het importeren van de shellomgeving om tijdens het opstarten variabelen uit je inlogshell te laden. Laat dit ingeschakeld als je afhankelijk bent van geheimen die in je profiel zijn gedefinieerd of van PATH-aanpassingen.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`Import van shellomgeving ingeschakeld`},help:{"v1-5tiuup-5u":`Schakelt het laden van omgevingsvariabelen uit het shellprofiel van de gebruiker tijdens de opstartinitialisatie in. Laat dit ingeschakeld op ontwikkelmachines of schakel het uit in strikt beveiligde serviceomgevingen met expliciet beheer van omgevingsvariabelen.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Time-out voor import van shellomgeving (ms)`},help:{"v1-nsk2yf-5c":`Maximale tijd in milliseconden voor het bepalen van de shellomgeving voordat terugvalgedrag wordt toegepast. Gebruik kortere time-outs voor sneller opstarten of verhoog de waarde als de shellinitialisatie veel tijd kost.`}},"env%2Evars":{label:{"v1-grhbhj-u":`Overschrijvingen van omgevingsvariabelen`},help:{"v1-yxc3z7-5n":`Expliciete overschrijvingen van omgevingsvariabelen als sleutel-waardeparen die tijdens de uitvoering worden samengevoegd met de procesomgeving van OpenClaw. Gebruik dit voor een deterministische omgevingsconfiguratie in plaats van uitsluitend te vertrouwen op neveneffecten van shellprofielen.`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-19p5env-5v":`Runtime-instellingen van de Gateway voor de bindmodus, authenticatie, Control UI, transport op afstand en operationele veiligheidsmaatregelen. Behoud voorzichtige standaardinstellingen, tenzij je de Gateway bewust toegankelijk maakt buiten vertrouwde lokale interfaces.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Terugvallen op x-real-ip toestaan voor Gateway`},help:{"v1-1wr3qmw-4c":`Staat terugvallen op x-real-ip toe wanneer x-forwarded-for ontbreekt bij gebruik van een proxy. Laat dit uitgeschakeld, tenzij je ingress-stack dit compatibiliteitsgedrag vereist.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Gateway-authenticatie`},help:{"v1-70b6ni-50":`Authenticatiebeleid voor HTTP/WebSocket-toegang tot de gateway, inclusief modus, inloggegevens, gedrag van vertrouwde proxy's en frequentiebeperking. Houd authenticatie ingeschakeld voor elke implementatie die niet uitsluitend via loopback toegankelijk is.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Tailscale-identiteit toestaan voor Gateway-authenticatie`},help:{"v1-vqtmgw-53":`Staat toe dat vertrouwde Tailscale-identiteitsroutes voldoen aan de authenticatiecontroles van de gateway, indien geconfigureerd. Gebruik dit alleen als de identiteitsbeveiliging van je tailnet sterk is en de werkprocessen van operators ervan afhankelijk zijn.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Toekenning van operatorrechten aan Gateway-identiteiten`},help:{"v1-1h0zxy7-5n":`Koppelt geverifieerde identiteiten van vertrouwde proxy's of Tailscale aan operatorrechten die alleen voor de verbinding gelden. E-mailsleutels worden hoofdletterongevoelig vergeleken; toegekende rechten vullen de apparaatrechten aan voordat de bovengrens voor verbindingsrechten wordt toegepast.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Gateway-authenticatiemodus`},help:{"v1-j8rodq-9t":`Gateway-authenticatiemodus: "none", "token", "password" of "trusted-proxy", afhankelijk van je edge-architectuur. De token-/wachtwoordmodus selecteert het geconfigureerde geheim (gateway.auth.token of gateway.auth.password); clients mogen dit in elk van beide authenticatievelden bij het verbinden verzenden. Gebruik token-/wachtwoordauthenticatie bij directe blootstelling en trusted-proxy alleen achter geharde proxy's die identiteiten herkennen.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Gateway-wachtwoord`},help:{"v1-1ndt0u2-4g":`Gedeeld geheim dat wordt geselecteerd door gateway.auth.mode=password. Clients mogen dit verzenden in auth.token of auth.password. De wachtwoordmodus is vereist voor Tailscale Funnel.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Frequentielimiet voor Gateway-authenticatie`},help:{"v1-1kstr42-54":`Instellingen voor het beperken van aanmeld- en authenticatiepogingen om het risico op brute-force-aanvallen op inloggegevens aan de gatewaygrens te verkleinen. Houd deze ingeschakeld in extern toegankelijke omgevingen en stem de drempelwaarden af op uw normale verkeersniveau.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Gateway-token`},help:{"v1-16i7cxs-5q":`Gedeeld geheim dat wordt geselecteerd met gateway.auth.mode=token, de standaard voor nieuwe lokale configuraties. Clients kunnen dit verzenden via auth.token of auth.password. Bindingen aan niet-loopbackadressen vereisen een ingeschakelde authenticatiemodus.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Gateway-authenticatie via vertrouwde proxy`},help:{"v1-12fsi5d-58":`Toewijzing van authenticatieheaders via een vertrouwde proxy voor upstream-identiteitsproviders die gebruikersclaims toevoegen. Gebruik dit alleen met bekende proxy-CIDR-bereiken en strikte lijsten met toegestane headers om vervalste identiteitsheaders te voorkomen.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`GitHub-identiteit via Cloudflare Access OIDC`},help:{"v1-1puth4k-6t":`Optionele geverifieerde GitHub-identiteit van een geselecteerde Cloudflare Access OIDC-provider. Vereist de standaard e-mail- en assertion-headers van Access. Bij ontbrekende claims blijven profielen alleen op e-mail gebaseerd; bestaande profielrollen en voorkeuren voor co-auteurschap blijven behouden.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`Claim voor GitHub-account-ID`},help:{"v1-pcaaw7-57":`Exacte doorgestuurde OIDC-claim waarvan de waarde een geverifieerde GitHub-account-ID is, weergegeven als een tekenreeks met een positief decimaal getal. Configureer Access om deze door te sturen in oidc_fields; gebruik nooit een ongeverifieerde claim die door gebruikers kan worden bewerkt.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Uitgever van Cloudflare Access`},help:{"v1-gykv03-56":`Exacte HTTPS-origin van het vertrouwde Cloudflare Access-team, zoals https://example.cloudflareaccess.com, zonder afsluitende slash. Claims van andere uitgevers leveren geen GitHub-identiteit.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`Cloudflare Access OIDC-provider-ID`},help:{"v1-kbyo5w-44":`Exacte ID van de Access-identiteitsprovider voor de vertrouwde OIDC-integratie. Alleen een weergavenaam van een provider of een overeenkomende claimnaam is niet voldoende om vertrouwen vast te stellen.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`Automatische apparaatgoedkeuring via vertrouwde proxy`},help:{"v1-uh32ha-6z":`Optioneel beleid voor het automatisch goedkeuren van nieuwe operatorapparaten met een browser of native UI en scope-uitbreidingen voor dezelfde sleutel na authenticatie via een vertrouwde proxy. Toegekende rechten worden begrensd door deviceAutoApprove.scopes en de header x-openclaw-scopes van de proxy, indien aanwezig.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`Automatische apparaatgoedkeuring via vertrouwde proxy ingeschakeld`},help:{"v1-1nntwls-78":`Keurt automatisch nieuwe operatorapparaten met een browser of native UI en scope-uitbreidingen voor dezelfde sleutel goed nadat de reverse proxy een toegestane gebruiker heeft geauthenticeerd. Standaard: false. Schakel dit alleen in als de identiteitsbeveiliging van de proxy sterk genoeg is om handmatige apparaatkoppeling te vervangen.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`Scopes voor automatische apparaatgoedkeuring via vertrouwde proxy`},help:{"v1-raeila-g3":`Maximale scopes die worden toegekend aan automatisch goedgekeurde operatorapparaten. Standaard zijn dit operator.read, operator.write, operator.approvals en operator.questions. Aangevraagde scopes worden beperkt tot deze lijst; aanvragen zonder scopes krijgen deze lijst. Als dit niet is ingesteld, voegt automatische goedkeuring ook operator.questions toe voor oudere UI-clients; een expliciete lijst wordt nooit uitgebreid. Door operator.admin expliciet op te nemen, kan elke via de proxy geauthenticeerde gebruiker automatisch volledige beheerdersrechten laten goedkeuren en krijgen aanvragen zonder scopes automatisch volledige beheerdersrechten. Dit leidt ook tot een kritieke bevinding in de beveiligingsaudit en een waarschuwing bij het opstarten van de Gateway.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Gateway-bindmodus`},help:{"v1-1unqude-4y":`Netwerkbindprofiel: "auto", "lan", "loopback", "custom" of "tailnet" om te bepalen welke interfaces toegankelijk zijn. Behoud "loopback" voor uitsluitend lokaal gebruik; "auto" kan alle interfaces toegankelijk maken.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`CLI-agents`},help:{"v1-1qqo8m2-5a":`Detectie in de Control UI van externe CLI-sessie-engines die via de sessiecatalogus van de Gateway beschikbaar worden gesteld. Standaard ingeschakeld; schakel dit uit om te voorkomen dat deze engines worden gestart vanuit de modelkiezer voor nieuwe sessies.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`CLI-agents ingeschakeld`},help:{"v1-ufu7fx-8p":`Toont CLI-agents uit de catalogus in de modelkiezer voor nieuwe sessies in de Control UI als dit true is (standaard: true). Stel dit in op false om CLI-agents en het aanmaken van native CLI-sessies uit te schakelen. Alleen catalogi die aangeven dat ze het aanmaken van sessies ondersteunen, worden weergegeven. De kiezer blijft verborgen wanneer de Gateway geen ondersteuning voor sessiecatalogi aangeeft.`}},"gateway%2EcontrolUi":{label:{"v1-1cl7zto-a":`Control UI`},help:{"v1-bkw4g1-5i":`Hostinginstellingen voor de Control UI, waaronder inschakeling, paden en beveiliging van browser-origins en authenticatie. Beperk de blootstelling van de UI tot een minimum en gebruik sterke authenticatiemaatregelen voordat u deze via internet toegankelijk maakt.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-11jcj2v-q":`Toegestane origins voor de Control UI`},help:{"v1-1stgitk-9i":`Toegestane browser-origins voor websocketverbindingen met de Control UI/WebChat (alleen volledige origins, bijv. https://control.example.com). Vereist voor Control UI-implementaties buiten loopback, tenzij de gevaarlijke terugval op de Host-header expliciet is ingeschakeld. De instelling ["*"] staat elke browser-origin toe en moet worden vermeden buiten strikt gecontroleerde lokale tests.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-1flu103-10":`Externe insluit-URL's voor de Control UI toestaan`},help:{"v1-obwpfg-6s":`GEVAARLIJKE schakeloptie waarmee gehoste insluitingen absolute externe http(s)-URL's kunnen laden. Laat deze uitgeschakeld, tenzij uw Control UI bewust vertrouwde pagina's van derden insluit; gehoste documenten onder /__openclaw__/canvas en /__openclaw__/a2ui hebben deze optie niet nodig.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`Favicons van links automatisch ophalen`},help:{"v1-bn9u34-ag":`Favicons van links en socialemediavoorbeelden voor browsertabbladen ophalen via de Gateway (standaard ingeschakeld). Kaarten voor browsertabbladen laden openbare paginametadata en opgegeven afbeeldingen zonder browsercookies of inloggegevens voor websites. Alle verzoeken gebruiken strikte SSRF-controles en begrensde verwerking van HTML en afbeeldingen. Stel in op false om zowel het automatisch ophalen van favicons als van paginavoorbeelden uit te schakelen; live browserschermafbeeldingen blijven ongewijzigd.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-qnzlec-k":`Basispad van de Control UI`},help:{"v1-1dx68ar-1w":`Optioneel URL-voorvoegsel waaronder de Control UI wordt aangeboden (bijv. /openclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-1j7cpqc-v":`Community-uitnodiging in Control UI`},help:{"v1-1rz3zsx-73":`Toon de uitnodiging voor de Discord-community in de Control UI die door deze Gateway wordt aangeboden (standaard ingeschakeld). Stel in op false om deze te verbergen voor elke browser die deze UI-implementatie gebruikt. Wijzigingen worden toegepast nadat de browser is vernieuwd of opnieuw verbinding heeft gemaakt; bij opnieuw inschakelen blijven uitnodigingen die lokaal in de browser zijn weggeklikt verborgen.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Gevaarlijke terugval op Host-header voor origin toestaan`},help:{"v1-1t1qi4c-7v":`GEVAARLIJKE schakelaar die terugval op de Host-header voor de origin inschakelt bij WebSocket-controles voor Control UI/WebChat. Deze modus wordt ondersteund wanneer je implementatie bewust een origin-beleid op basis van de Host-header gebruikt; het expliciet instellen van gateway.controlUi.allowedOrigins blijft de aanbevolen, beter beveiligde standaard.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-1hknvfl-t":`Sandboxmodus voor ingesloten inhoud in Control UI`},help:{"v1-d54l3a-7c":'Sandboxbeleid voor iframes met gehoste ingesloten inhoud in Control UI. "strict" schakelt scripts uit, "scripts" staat interactieve ingesloten inhoud toe met behoud van origin-isolatie (standaard), en "trusted" voegt `allow-same-origin` toe voor documenten van dezelfde site die bewust uitgebreidere rechten nodig hebben.'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-1jokhv9-i":`Control UI ingeschakeld`},help:{"v1-1hhyymc-4w":`Schakelt bij true het aanbieden van de Control UI van de Gateway via het HTTP-proces van de Gateway in. Laat dit ingeschakeld voor lokaal beheer en schakel het uit wanneer een externe beheerinterface deze vervangt.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-tmefut-m":`Control UI-omgeving`},help:{"v1-paarso-4n":`Optionele openbare omgevingsidentiteit die wordt weergegeven in de Control UI-balk, de agentavatar, labelbadges, de browsertitel en het favicon. Laat deze weg om het standaarduiterlijk te behouden.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-vy6f72-s":`Omgevingskleur van de Control UI`},help:{"v1-mp6cta-2i":`Benoemd kleurenpalet voor de omgeving: teal, amber, purple, coral, pink, blue, green, red of gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-1yr90xz-s":`Omgevingslabel van de Control UI`},help:{"v1-1njve3z-3z":`Omgevingslabel dat wordt weergegeven in de Control UI en het browsertabblad; witruimte aan het begin en einde wordt verwijderd en het label moet 1 tot 24 tekens bevatten.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-10uccgr-w":`Experimentele functies van de Control UI`},help:{"v1-1qobi2m-3g":`Experimenten voor de Control UI die u zelf kunt inschakelen. Deze functies kunnen tussen releases veranderen en blijven uitgeschakeld tenzij ze expliciet worden ingeschakeld.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`UI voor aangepaste plug-ins`},help:{"v1-108u6ts-9e":`Sta door gebruikers geïnstalleerde plugins toe om native JavaScript uit te voeren in de Control UI (standaard: false). Meegeleverde pluginweergaven blijven beschikbaar. Aangepaste UI deelt de Gateway-rechten van de aangemelde operator; schakel dit alleen in voor vertrouwde plugins. Wijzigingen worden toegepast zonder de Gateway opnieuw te starten. Herlaad geopende Control UI-pagina's om eerder geladen plugincode te wissen.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1036yk1-10":`GitHub-service-inloggegeven voor de Control UI`},help:{"v1-1p31phh-d6":`Servicereferentie op basis van SecretRef voor projectdetectie in Control UI en GitHub-voorbeelden bij aanwijzen, zonder beheerde identiteit. Voorbeelden bij aanwijzen gebruiken bij voorkeur de geconfigureerde GitHub-identiteit van de geselecteerde agent en nemen de systeemidentiteit over als er geen afwijkende instelling is. Gebruik bij voorkeur een expliciete configuratie voor duidelijk eigenaarschap van de service. Laat deze weg om de terugval op GH_TOKEN/GITHUB_TOKEN uit de gedeelde procesomgeving van Gateway te behouden. Als een expliciet geconfigureerde referentie niet beschikbaar is, wordt de toegang geweigerd.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-t5p3aj-m":`Hoofdmap voor Control UI-bestanden`},help:{"v1-elck04-25":`Optionele hoofdmap in het bestandssysteem voor Control UI-bestanden (standaard dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-tjwi96-r":`Sessiewaarnemer van Control UI`},help:{"v1-1ahs80-8a":`Genereer live samenvattingen van de sessiestatus voor geabonneerde Control UI-clients met het hulpmodel van elke agent (standaard ingeschakeld). Stel dit in op false om modelaanroepen door de waarnemer voor de hele Gateway uit te schakelen; als agents.defaults.utilityModel op een lege tekenreeks wordt ingesteld, wordt waarneming via het hulpmodel uitgeschakeld voor agents die deze instelling niet overschrijven.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Aangepaste bindingshost voor Gateway`},help:{"v1-lwjcyo-4d":`IPv4-adres voor een aangepaste binding. Specifieke IPv4-adressen vereisen ook dezelfde Gateway-poort op 127.0.0.1; vermijd 0.0.0.0 tenzij bereikbaarheid via alle interfaces vereist is.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`HTTP-API van Gateway`},help:{"v1-ebtex7-4j":`Configuratie van de HTTP-API van Gateway waarin instellingen voor het in- en uitschakelen van eindpunten en voor de bereikbaarheid van de API via de transportlaag zijn gegroepeerd. Laat alleen vereiste eindpunten ingeschakeld om het aanvalsoppervlak te verkleinen.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`HTTP-eindpunten van Gateway`},help:{"v1-1a0r104-55":`Schakelaars voor HTTP-eindpunten binnen de gateway-API voor compatibiliteitsroutes en optionele integraties. Schakel eindpunten bewust in en bewaak toegangspatronen na de uitrol.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`OpenAI Chat Completions-eindpunt`},help:{"v1-1271mpb-2b":"Schakel het OpenAI-compatibele eindpunt `POST /v1/chat/completions` in (standaard: false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`Afbeeldingslimieten voor OpenAI Chat Completions`},help:{"v1-xgscw1-20":"Instellingen voor het ophalen en valideren van afbeeldingen voor OpenAI-compatibele `image_url`-onderdelen."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`Toegestane MIME-typen voor afbeeldingen in OpenAI Chat Completions`},help:{"v1-1guijf3-1t":"Toegestane MIME-typen voor `image_url`-onderdelen (hoofdletterongevoelige lijst)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`Afbeeldings-URL's toestaan voor OpenAI Chat Completions`},help:{"v1-55cb3n-47":"Sta het ophalen van URL's aan de serverzijde toe voor `image_url`-onderdelen (standaard: false; data-URI's blijven ondersteund). Stel dit in op `false` om het ophalen van URL's volledig uit te schakelen."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`Maximumaantal bytes per afbeelding voor OpenAI Chat Completions`},help:{"v1-d920yx-1s":"Maximumaantal bytes per opgehaalde of gedecodeerde `image_url`-afbeelding (standaard: 10 MB)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`Maximumaantal omleidingen voor afbeeldingen in OpenAI Chat Completions`},help:{"v1-1enujsk-1z":"Maximumaantal toegestane HTTP-omleidingen bij het ophalen van `image_url`-URL's (standaard: 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`Time-out voor afbeeldingen in OpenAI Chat Completions (ms)`},help:{"v1-89w2b9-1x":"Time-out in milliseconden voor het ophalen van `image_url`-URL's (standaard: 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`Lijst met toegestane afbeeldings-URL's voor OpenAI Chat Completions`},help:{"v1-n4hlt1-4r":"Optionele lijst met toegestane hostnamen voor het ophalen van `image_url`-URL's; ondersteunt exacte hostnamen en jokertekens zoals `*.example.com`. Als de lijst leeg is of ontbreekt, gelden er geen beperkingen op basis van hostnamen."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`HTTP-beveiligingsheaders van de Gateway`},help:{"v1-n8z1hb-44":`Optionele HTTP-beveiligingsheaders voor antwoorden, die door het Gateway-proces zelf worden toegepast. Stel deze bij voorkeur in op je reverse proxy als TLS daar wordt beëindigd.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`Strict-Transport-Security-header`},help:{"v1-1buwhc3-3v":`Waarde voor de Strict-Transport-Security-antwoordheader. Stel deze alleen in voor HTTPS-origins waarover je volledige controle hebt; gebruik false om deze expliciet uit te schakelen.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Gateway-modus`},help:{"v1-nfjirv-5m":`Bedrijfsmodus van de Gateway: "local" voert kanalen en de agentruntime op deze host uit, terwijl "remote" verbinding maakt via extern transport. Gebruik "local", tenzij je bewust een gesplitste topologie met een externe Gateway gebruikt.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Skills van Gateway-knooppunten ingeschakeld`},help:{"v1-1xwu6at-3g":`Accepteer Skills die door gekoppelde knooppunten worden gepubliceerd zolang ze verbonden zijn (standaard: true). Stel in op false om door knooppunten gepubliceerde Skills te negeren.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Browsermodus voor Gateway-knooppunten`},help:{"v1-oeu1nc-69":`Browserroutering via nodes ("auto" = geef de voorkeur aan de browser op de host en gebruik één verbonden browsernode als lokale browserfunctionaliteit niet beschikbaar is; "manual" = vereis een expliciete nodeselectie of een geconfigureerde vaste toewijzing; "off" = schakel routering via nodes uit).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Vast browserknooppunt voor de Gateway`},help:{"v1-1cykty2-1p":`Zet browserroutering vast op een specifieke knooppunt-ID of -naam (optioneel).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Toegestane opdrachten voor Gateway-knooppunten (extra opdrachten)`},help:{"v1-6l4otb-5m":"Extra node.invoke-opdrachten die naast de standaard toegestane opdrachten van de Gateway worden toegestaan (array van opdrachtstrings). Het hier inschakelen van gevaarlijke opdrachten is een beveiligingsgevoelige afwijking die door `openclaw security audit` wordt gemarkeerd."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Geblokkeerde opdrachten voor Gateway-knooppunten`},help:{"v1-u7c8wx-53":"Namen van knooppuntopdrachten die moeten worden geblokkeerd, zelfs als ze voorkomen in knooppuntclaims of de standaardlijst met toegestane opdrachten (alleen exacte overeenkomsten met opdrachtnamen, bijvoorbeeld `system.run`; shelltekst binnen die opdracht wordt niet gecontroleerd)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Gateway-knooppunten koppelen`},help:{"v1-gldsi2-4s":`Beleidsinstellingen voor het koppelen van nodes. Automatische goedkeuring na SSH-verificatie is standaard ingeschakeld; automatische goedkeuring op basis van CIDR blijft uitgeschakeld tenzij expliciete lijsten met toegestane vertrouwde CIDR/IP-adressen zijn geconfigureerd.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`CIDR-bereiken voor automatische goedkeuring van Gateway-nodekoppelingen`},help:{"v1-1m6jsxj-6x":`Optionele lijst met toegestane CIDR/IP-adressen voor het automatisch goedkeuren van de eerste koppeling van apparaten met de noderol, zonder aangevraagde scopes. Uitgeschakeld indien niet ingesteld. Koppelingen voor operators, browsers en Control UI, evenals koppelingen met wijzigingen in rollen, scopes, metadata of openbare sleutels, vereisen nog steeds handmatige goedkeuring.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Automatische goedkeuring van lokale Gateway-nodekoppelingen`},help:{"v1-glzm36-41":`Vertrouwde lokale koppelingen en uitbreidingen van toegangsrechten stilzwijgend goedkeuren (standaard: true); stel in op false om gemak in te ruilen voor expliciete goedkeuring van elk apparaat.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`SSH-verificatie voor Gateway-nodekoppelingen`},help:{"v1-1e4da92-ct":"Automatische goedkeuring na SSH-verificatie voor de eerste koppeling van apparaten met de noderol (standaard: ingeschakeld). De Gateway maakt via SSH een terugverbinding met de host die de koppeling aanvraagt (BatchMode, strikte controle van hostsleutels) en keurt alleen goed wanneer de externe uitvoer van `openclaw node identity` overeenkomt met de apparaatsleutel die op goedkeuring wacht. Stel in op false om SSH-verificatie uit te schakelen (onafhankelijk van autoApproveCidrs, dat actief blijft); verwijder ook de instelling autoApproveCidrs om koppelingen uitsluitend handmatig goed te keuren. Geef een object op om user/identity/timeoutMs/cidrs te overschrijven."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Plugintools voor Gateway-nodes`},help:{"v1-1c24iq3-28":`Bepaalt of gekoppelde nodes beschrijvingen van plugintools mogen publiceren die zichtbaar zijn voor agents.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Plugintools van Gateway-knooppunten ingeschakeld`},help:{"v1-14lgfu6-47":`Accepteer voor agents zichtbare beschrijvingen van plugintools die door gekoppelde knooppunten worden gepubliceerd (standaard: true). Stel in op false om alle door knooppunten gepubliceerde plugintools te negeren en te verwijderen.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Gateway-poort`},help:{"v1-for8t5-54":`TCP-poort die de Gateway-listener gebruikt voor de API, de Control UI en inkomende routes voor kanalen. Gebruik een toegewezen poort en vermijd conflicten met reverse proxy's of lokale ontwikkelservices.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Gateway-portals`},help:{"v1-1v2lkw9-1c":`Instellingen voor portalpublicatie en privé-ingress.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`Privé-ingress voor portals`},help:{"v1-20w4gq-69":`Optionele privé-HTTPS-wildcard-reverse-proxy die door de beheerder wordt beheerd. Stuur de oorspronkelijke Host, paden en WebSocket-upgrades door naar de specifieke loopbacklistener. Bearerauthenticatie voor portals blijft vereist. Vereist een herstart van de Gateway.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`Wildcarddomein voor portals`},help:{"v1-1ipbfad-53":`DNS-domein zonder voorvoegsels voor willekeurige portalsubdomeinen (bijvoorbeeld previews.example.net). Configureer wildcard-DNS en HTTPS voor privégebruik; deel de hostnaamnaamruimte niet met de Gateway of Control UI.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`Loopbackpoort voor portalingress`},help:{"v1-1mb98cv-4g":`Aparte HTTP-poort op het loopbackadres die verkeer van de private wildcard-HTTPS-proxy ontvangt. Moet verschillen van de Gateway-poort. Dit is de backendpoort, niet de openbare HTTPS-poort.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Openbare origin van de Gateway`},help:{"v1-17vekvx-87":`Extern bereikbare HTTPS-origin van de Gateway. HTTP is alleen toegestaan voor localhost, 127.0.0.1 of [::1]. MCP OAuth per aanvrager gebruikt deze om de callback-URL op /oauth/mcp/callback samen te stellen; links naar kanaalsessies en door plugins gegenereerde viewerlinks gebruiken deze om de Control UI en Gateway-routes te bereiken.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Gateway-pushbezorging`},help:{"v1-h23oz7-5s":`Instellingen voor pushbezorging die de Gateway gebruikt om gekoppelde apparaten te activeren of meldingen te sturen. Configureer hier APNs via een relay voor officiële iOS-builds; directe APNs-authenticatie blijft gebaseerd op omgevingsvariabelen voor lokale/handmatige builds.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Gateway-APNs-bezorging`},help:{"v1-4bbafr-4e":`Instellingen voor APNs-bezorging voor iOS-apparaten die aan deze Gateway zijn gekoppeld. Gebruik relayinstellingen voor officiële App Store-builds die zich via de externe pushrelay registreren.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Gateway-APNs-relay`},help:{"v1-7glbel-6x":`Instellingen voor een externe relay voor APNs-verzendingen via een relay. De Gateway gebruikt standaard de gehoste OpenClaw-relay, of deze aangepaste relay voor push.test, activeringssignalen en activeringen om opnieuw verbinding te maken, nadat een gekoppelde officiële iOS-build een registratie via een relay heeft gepubliceerd.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`Basis-URL van de APNs-relay van de Gateway`},help:{"v1-1o8mgnq-69":`Optionele aangepaste HTTPS-basis-URL voor de externe APNs-relayservice die door officiële iOS-builds uit de App Store wordt gebruikt. Zorg dat deze overeenkomt met de relay-URL die in de iOS-build is ingebouwd, zodat registratie- en verzendverkeer bij dezelfde implementatie terechtkomen.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Time-out voor de APNs-relay van de Gateway (ms)`},help:{"v1-a0jkb1-4z":`Time-out in milliseconden voor verzendverzoeken van de Gateway naar de APNs-relay (standaard: 10000). Verhoog deze waarde voor tragere relays of netwerken, of verlaag deze om activeringspogingen sneller te laten mislukken.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`Configuratie opnieuw laden`},help:{"v1-d02mvq-4w":`Beleid voor het live opnieuw laden van de configuratie, dat bepaalt hoe wijzigingen worden toegepast en wanneer volledig opnieuw wordt opgestart. Behoud het hybride gedrag voor zo veilig mogelijke updates tijdens gebruik, tenzij u fouten in de interne herlaadwerking opspoort.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`Modus voor opnieuw laden van de configuratie`},help:{"v1-1q1etcf-3m":`Bepaalt hoe configuratiewijzigingen worden toegepast: "off" negeert live wijzigingen en "hybrid" past wijzigingen toe die veilig tijdens gebruik kunnen worden doorgevoerd en start vervolgens opnieuw op als dat nodig is.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`Externe Gateway`},help:{"v1-6xv7gd-5a":`Verbindingsinstellingen voor een externe Gateway via rechtstreeks transport of SSH-transport wanneer deze instantie als proxy voor een andere runtimehost fungeert. Gebruik de externe modus alleen wanneer het gebruik van afzonderlijke hosts bewust is geconfigureerd.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`Edge-authenticatieheaders voor externe Gateway`},help:{"v1-jg9p7d-5o":`HTTP-headers met waarden uit geheimen die worden aangeboden aan een identiteitsbewuste proxy vóór de geconfigureerde externe Gateway. Headers worden alleen via WSS naar de exacte origin van gateway.remote.url verzonden en volgen nooit omleidingen.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`Wachtwoord voor externe Gateway`},help:{"v1-16jc0yx-7y":`Gedeeld geheim dat in het wachtwoordveld wordt verzonden om deze client bij een externe gateway te authenticeren. De instelling gateway.auth.mode van de server bepaalt welk geconfigureerd geheim wordt gebruikt; zowel het tokenveld als het wachtwoordveld van de client wordt geaccepteerd. Beheer dit geheim extern en vermijd waarden in platte tekst in configuratie die in versiebeheer wordt vastgelegd.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`SSH-hostsleutelbeleid voor externe Gateway`},help:{"v1-7qoxtb-49":`Beleid voor SSH-hostsleutelverificatie op macOS. "strict" vereist een reeds vertrouwde hostsleutel; "openssh" delegeert expliciet naar de effectieve OpenSSH-configuratie.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`SSH-identiteit voor externe Gateway`},help:{"v1-hz2hsm-1f":`Optioneel pad naar een SSH-identiteitsbestand (doorgegeven aan ssh -i).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`SSH-doel voor externe Gateway`},help:{"v1-85w39w-2t":`Externe gateway via SSH (tunnelt de gatewaypoort naar localhost). Indeling: user@host of user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`TLS-vingerafdruk voor externe Gateway`},help:{"v1-1ri16lk-23":`Verwachte sha256-TLS-vingerafdruk voor de externe gateway (vastzetten om MITM te voorkomen).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`Token voor externe Gateway`},help:{"v1-1pb9q8w-7v":`Gedeeld geheim dat in het tokenveld wordt verzonden om deze client bij een externe gateway te authenticeren. De instelling gateway.auth.mode van de server bepaalt welk geconfigureerd geheim wordt gebruikt; zowel het tokenveld als het wachtwoordveld van de client wordt geaccepteerd. Sla dit op via substitutie van geheimen of omgevingsvariabelen en vernieuw het bij wijzigingen in de authenticatie van de externe gateway.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`Transport voor externe Gateway`},help:{"v1-1acfs7m-54":`Transport voor externe verbindingen: "direct" gebruikt de geconfigureerde URL-verbinding, terwijl "ssh" een tunnel via SSH gebruikt. Gebruik SSH wanneer je een versleutelde tunnel nodig hebt zonder externe poorten bloot te stellen.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`URL van externe Gateway`},help:{"v1-va7exe-1b":`WebSocket-URL van de externe Gateway (ws:// of wss://).`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Operatorrollen voor Gateway`},help:{"v1-b59sc5-6w":`Optionele profielgebonden operatorrollen voor Gateways van teams. Elke benoemde rol regelt de toegang tot sessies van anderen, sandboxisolatie, agents voor sessies en uitvoeringen, en toegekende operatorbevoegdheden; als je deze sectie weglaat, blijft het bestaande operatorgedrag behouden.`}},"gateway%2Eroles%2Edefault":{label:{"v1-1ykt1qe-l":`Standaardoperatorrol`},help:{"v1-1v8add8-4u":`Verplichte rol die wordt toegewezen aan geauthenticeerde profielen zonder geldige expliciete toewijzing wanneer operatorrollen zijn geconfigureerd. De naam moet overeenkomen met een geconfigureerde roldefinitie.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`Definities van operatorrollen`},help:{"v1-uv91an-53":`Niet-lege roldefinities met door de beheerder gekozen namen. Ze bundelen de vaste beleidsregels voor het delen van sessies, sandboxisolatie, agenttoegang en operatorbevoegdheden die op geauthenticeerde gebruikersprofielen worden toegepast.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`Definitie van operatorrol`},help:{"v1-p8tfws-6q":`Eén benoemde operatorrol. Elke definitie moet expliciet het beleid voor het delen van sessies, de toegestane agents voor sessies en uitvoeringen en de bovengrens voor operatorrechten opgeven. Daarnaast kan de definitie sandboxisolatie voor nieuw aangemaakte sessies en een toegangsbeleid van een plug-in vereisen.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`Plug-in voor toegangsbeleid van operatorrol`},help:{"v1-1gq4q08-9n":`Optionele exacte plug-in-ID waarvan het Gateway-toegangsbeleid deze rol moet autoriseren. Toegang wordt geweigerd als de plug-in ontbreekt, is uitgeschakeld, niet kan worden geladen of geen actuele autorisatie biedt. Niet-beschikbare plug-in-ID's blijven geldig in de configuratie, zodat onafhankelijke personeelsrollen en de Gateway-eigenaar de toegang kunnen herstellen. Als je dit veld weglaat, wordt er geen afhankelijkheid van een plug-in toegevoegd.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`Toegestane agents voor operatorrol`},help:{"v1-fvun18-4v":`Agents die beschikbaar zijn wanneer deze rol sessies aanmaakt of uitvoeringen start: stel "*" in om elke agent toe te staan, geef agent-ID's op om alleen die agents toe te staan, of gebruik een lege lijst om beide uit te schakelen.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`Sandboxisolatie voor operatorrol`},help:{"v1-sknx21-66":`Uitvoeringsisolatie voor nieuw aangemaakte sessies: "inherit" (standaard) gebruikt het agentbeleid; "required" vereist permanent een sandbox, zelfs wanneer de sandboxmodus van de agent is uitgeschakeld, en blokkeert de uitvoering als de backend niet beschikbaar is.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`Maximale scopes voor operatorrol`},help:{"v1-1selr2i-4s":`Limitatieve lijst met operatorscopes die de maximale verbindingsbevoegdheden van deze rol bepalen. Aangevraagde, gekoppelde, via identiteit verleende en opgewaardeerde scopes worden beperkt tot de scopes in deze lijst.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`Sessietoegang voor operatorrol`},help:{"v1-hsoiop-45":`Machtigingen voor het delen van sessies die aan deze rol worden verleend voor sessies die door andere geauthenticeerde personen zijn aangemaakt; de eigen sessies van een persoon blijven toegankelijk voor die persoon.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`Toegang tot andere sessies voor operatorrol`},help:{"v1-vf8umx-5r":`Toegang tot sessies van anderen: "none" verbergt ze, "view" staat lezen toe, "suggest" staat het suggestieproces toe en "write" staat deelname toe. Expliciet sessielidmaatschap kan extra toegang verlenen.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Gateway Tailscale`},help:{"v1-6ar9o-4x":`Instellingen voor Tailscale-integratie voor beschikbaarstelling via Serve/Funnel en levenscyclusbeheer bij het starten en afsluiten van de Gateway. Laat dit uitgeschakeld, tenzij uw implementatie bewust afhankelijk is van inkomend verkeer via Tailscale.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Gateway Tailscale-modus`},help:{"v1-6l2099-5a":`Publicatiemodus van Tailscale: "off", "serve" of "funnel" voor private of openbare toegang. Gebruik "serve" voor toegang uitsluitend via het tailnet en "funnel" alleen als bereikbaarheid via het openbare internet vereist is.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Migratiebeveiliging voor externe Funnel van Gateway Tailscale`},help:{"v1-1mntkor-7q":`Verouderde migratiebeveiliging voor mode='serve'. Als een externe Funnel nog steeds naar de gewone Gateway-listener verwijst, laat OpenClaw de beschikbaarstelling ongewijzigd en waarschuwt het dat alleen via plug-ins geauthenticeerde webhooks bruikbaar blijven totdat wachtwoordauthenticatie is geconfigureerd en de modus naar 'funnel' is gemigreerd.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`Operatorterminal`},help:{"v1-18f5rgm-8b":`Operatorterminal beschikbaar voor Control UI en mobiele clients: een shell op basis van een PTY op de Gateway-host, beperkt tot operatorsessies met beheerdersrechten. Deze start in de werkruimte van de doelagent en wordt geweigerd voor volledig gesandboxte agents (sandbox.mode 'all'), in plaats van een onbeperkte shell op de host beschikbaar te stellen.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`Time-out voor losgekoppelde sessie van operatorterminal`},help:{"v1-k6qbgr-9e":`Aantal seconden dat een terminalsessie actief blijft nadat de verbinding wegvalt (slaapstand van laptop, opnieuw laden van pagina). De sessie blijft opnieuw koppelbaar via terminal.attach, waarbij de recente uitvoer opnieuw wordt weergegeven. Stel in op 0 om sessies te beëindigen zodra de verbinding wegvalt. Standaard: 300 (5 minuten). Losgekoppelde sessies blijven hun opdrachten uitvoeren, dus verkort deze tijd op gedeelde of extern toegankelijke hosts.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`Operatorterminal ingeschakeld`},help:{"v1-1nez06v-7p":`Schakelt de operatorterminal in voor clients met beheerdersrechten (standaard: true). Dit biedt een shell in de browser of op mobiele apparaten met de procesomgeving van de Gateway; stel false in om dit uit te schakelen bij implementaties waar operators met beheerdersrechten geen shell op de host mogen krijgen. Wijzigingen worden toegepast zonder de Gateway opnieuw op te starten.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`Shell voor operatorterminal`},help:{"v1-19mfe6t-5i":`Uitvoerbaar shellbestand dat de operatorterminal start. Laat dit oningesteld om de inlogshell van de host te gebruiken ($SHELL op Unix, %ComSpec% op Windows), of stel een specifieke interpreter in voor een consistente operatoromgeving.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`Gateway-TLS`},help:{"v1-1dx77dq-4z":`Instellingen voor TLS-certificaten en -sleutels om HTTPS rechtstreeks in het Gateway-proces af te handelen. Gebruik expliciete certificaten in productie en vermijd onversleutelde toegang via niet-vertrouwde netwerken.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Gateway-TLS-certificaat automatisch genereren`},help:{"v1-1ld6uiu-4w":`Genereert automatisch een lokaal TLS-certificaat met bijbehorende sleutel wanneer er geen expliciete bestanden zijn geconfigureerd. Gebruik dit alleen voor lokale of ontwikkelomgevingen en vervang ze door echte certificaten voor productieverkeer.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Pad naar TLS-CA-bundel van Gateway`},help:{"v1-andqlu-52":`Optioneel pad naar een CA-bundel voor clientverificatie of aangepaste vereisten voor vertrouwensketens aan de rand van de gateway. Gebruik dit wanneer een privé-PKI of aangepaste certificaatketens deel uitmaken van de implementatie.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Pad naar TLS-certificaat van Gateway`},help:{"v1-1wznaof-4q":`Bestandssysteempad naar het TLS-certificaatbestand dat de gateway gebruikt wanneer TLS is ingeschakeld. Gebruik beheerde certificaatpaden en stem de automatische vernieuwing af op deze locatie.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`TLS voor Gateway ingeschakeld`},help:{"v1-ykhwp0-4o":`Schakelt TLS-terminatie in op de gatewaylistener, zodat clients rechtstreeks via HTTPS/WSS verbinding maken. Houd dit ingeschakeld bij directe blootstelling aan het internet of bij elke grens met een onvertrouwd netwerk.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Pad naar TLS-sleutel van Gateway`},help:{"v1-15knri0-4i":`Bestandssysteempad naar het bestand met de TLS-privésleutel dat de gateway gebruikt wanneer TLS is ingeschakeld. Beperk de toegangsrechten tot dit sleutelbestand en roteer de sleutel volgens uw beveiligingsbeleid.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Beleid voor beschikbaarstelling van tools via Gateway`},help:{"v1-1ffol26-5a":`Beleid op Gateway-niveau voor het toestaan of blokkeren van tools, waarmee de beschikbaarheid van tools tijdens runtime kan worden beperkt, onafhankelijk van agent- en toolprofielen. Gebruik dit voor algemene noodmaatregelen en extra beveiliging van productieomgevingen.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Lijst met toegestane tools voor Gateway`},help:{"v1-163khb1-4y":`Expliciete lijst met toegestane tools op gatewayniveau wanneer u slechts een beperkte set tools beschikbaar wilt stellen tijdens runtime. Gebruik dit voor streng afgeschermde omgevingen waarin de beschikbare tools strikt moeten worden beheerd.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Lijst met geblokkeerde tools voor Gateway`},help:{"v1-1lhssnf-4o":`Expliciete blokkeerlijst voor tools op gatewayniveau om risicovolle tools te blokkeren, zelfs als beleidsregels op lagere niveaus ze toestaan. Gebruik blokkeerregels voor noodmaatregelen en gelaagde beveiliging.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`CIDR-bereiken van vertrouwde proxy's voor Gateway`},help:{"v1-n5zcvf-4f":`Lijst met toegestane CIDR-bereiken/IP-adressen van upstreamproxy's die doorgestuurde headers met clientidentiteit mogen aanleveren. Houd deze lijst beperkt, zodat niet-vertrouwde tussenstations zich niet als gebruikers kunnen voordoen.`}},hooks:{label:{"v1-j9ywl7-5":`Hooks`},help:{"v1-1mzh0ry-5v":`Automatiseringsinterface voor inkomende webhooks om externe gebeurtenissen te koppelen aan activerings- of agentacties in OpenClaw. Beveilig deze met expliciete controles voor tokens, sessies en agents voordat u de interface buiten vertrouwde netwerken toegankelijk maakt.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`Toegestane agent-ID's voor hooks`},help:{"v1-hree88-7c":`Lijst met toegestane effectieve agent-ID's waarop hookverzoeken en koppelingen zich mogen richten, inclusief routering naar de standaardagent wanneer agentId is weggelaten. Gebruik dit om automatiseringsgebeurtenissen te beperken tot specifieke serviceagents en de impact te beperken als een hooktoken uitlekt.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`Toegestane sessiesleutelvoorvoegsels voor hooks`},help:{"v1-b346oh-4r":`Lijst met toegestane sessiesleutelvoorvoegsels voor inkomende hookverzoeken wanneer door aanroepers aangeleverde sleutels zijn ingeschakeld. Gebruik specifieke voorvoegsels om injectie van willekeurige sessiesleutels te voorkomen.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`Sessiesleutel in hookverzoeken toestaan`},help:{"v1-11n9ps-52":`Staat bij true toe dat aanroepers een sessiesleutel opgeven in hookverzoeken, zodat zij de routering kunnen bepalen. Houd dit op false, tenzij vertrouwde integratiepartners expliciet aangepaste sessiegroepering nodig hebben.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`Standaardsessiesleutel voor hooks`},help:{"v1-bzdgkn-57":`Terugvalsessiesleutel voor hook-aanleveringen wanneer een verzoek er geen via toegestane kanalen opgeeft. Gebruik een stabiele sleutel met een beperkt bereik om te voorkomen dat niet-gerelateerde automatiseringsgesprekken door elkaar raken.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`Hooks ingeschakeld`},help:{"v1-1mixmjf-4n":`Schakelt het hooks-eindpunt en de uitvoeringspijplijn voor toewijzingen in voor inkomende webhookverzoeken. Laat dit uitgeschakeld tenzij u actief externe gebeurtenissen naar de gateway doorstuurt.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Gmail-hook`},help:{"v1-4cibmt-4r":`Instellingen voor de Gmail-pushintegratie voor Pub/Sub-meldingen en optionele lokale afhandeling van callbacks. Beperk dit waar mogelijk tot speciale Gmail-accounts voor automatisering.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Account voor Gmail-hook`},help:{"v1-12l1h96-4v":`Google-account-ID voor bewakings- en abonnementsbewerkingen van Gmail in deze hook-integratie. Gebruik een speciaal mailboxaccount voor automatisering om operationele machtigingen gescheiden te houden.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Onveilige externe inhoud toestaan voor Gmail-hook`},help:{"v1-1w3gdvs-55":`Staat toe dat minder grondig opgeschoonde externe Gmail-inhoud wordt verwerkt wanneer dit is ingeschakeld. Laat dit uitgeschakeld voor veiligere standaardinstellingen en schakel het alleen in voor vertrouwde e-mailstromen met gecontroleerde transformaties.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`Callback-URL voor Gmail-hook`},help:{"v1-19fhn6q-4z":`Openbare callback-URL die Gmail of tussenliggende diensten aanroepen om meldingen aan deze hook-pijplijn te leveren. Bescherm deze URL met tokenvalidatie en beperkte netwerktoegang.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Berichtinhoud opnemen in Gmail-hook`},help:{"v1-14cf1c3-52":`Wanneer ingesteld op true, wordt de berichtinhoud opgehaald en opgenomen voor verdere mapping en verwerking door agents. Houd dit op false tenzij de berichttekst nodig is, omdat dit de payload groter en gevoeliger maakt.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Label voor Gmail-hook`},help:{"v1-9zpdg8-4g":`Optioneel Gmail-labelfilter dat beperkt welke gelabelde berichten hookgebeurtenissen activeren. Houd filters specifiek om te voorkomen dat automatiseringen worden overspoeld met niet-relevante inboxberichten.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Maximale berichtinhoud in bytes voor Gmail-hook`},help:{"v1-2aaxx1-4b":`Maximaal aantal bytes van de Gmail-payload dat per gebeurtenis wordt verwerkt wanneer includeBody is ingeschakeld. Houd de limieten laag om de kosten en risico's van de verwerking van te grote berichten te beperken.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Afwijkend model voor Gmail-hook`},help:{"v1-1var65t-59":`Optioneel afwijkend model voor uitvoeringen die door Gmail worden geactiveerd, wanneer mailboxautomatiseringen specifiek modelgedrag moeten gebruiken. Laat dit oningesteld om de standaardinstellingen van de agent over te nemen, tenzij mailboxtaken specialisatie vereisen.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Pushtoken voor Gmail-hook`},help:{"v1-h1vx01-4o":`Gedeeld geheim token dat vereist is bij callbacks van de Gmail-pushhook voordat meldingen worden verwerkt. Gebruik substitutie via omgevingsvariabelen en roteer het token als callback-eindpunten extern toegankelijk zijn.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Vernieuwingsinterval voor Gmail-hook (min)`},help:{"v1-pr1z9-49":`Vernieuwingsinterval in minuten voor Gmail-watchabonnementen om te voorkomen dat ze verlopen. Stel dit korter in dan de vervaltermijnen van de provider en controleer de logs op mislukte vernieuwingen.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Lokale server voor Gmail-hook`},help:{"v1-hom4wq-54":`Instellingenblok voor de lokale callbackserver om Gmail-meldingen rechtstreeks te ontvangen zonder aparte ingangslaag. Schakel dit alleen in als dit proces zelf het webhookverkeer moet afhandelen.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Bindadres van Gmail-hookserver`},help:{"v1-55bieu-4d":`Bindadres voor de lokale HTTP-callbackserver van Gmail die wordt gebruikt bij het rechtstreeks aanbieden van hooks. Beperk dit tot loopback, tenzij externe toegang bewust vereist is.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Pad van Gmail-hookserver`},help:{"v1-1jqhcw4-4h":`HTTP-pad op de lokale callbackserver van Gmail waar pushmeldingen worden geaccepteerd. Houd dit in overeenstemming met de abonnementsconfiguratie om te voorkomen dat gebeurtenissen verloren gaan.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Poort van Gmail-hookserver`},help:{"v1-1yku7dz-43":`Poort voor de lokale HTTP-callbackserver van Gmail wanneer de serve-modus is ingeschakeld. Gebruik een afzonderlijke poort om conflicten met gateway- en beheerinterfaces te voorkomen.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Gmail-hookabonnement`},help:{"v1-127h8vg-5b":`Pub/Sub-abonnement dat de gateway gebruikt om Gmail-wijzigingsmeldingen van het geconfigureerde topic te ontvangen. Zorg dat duidelijk is wie het abonnement beheert, zodat meerdere afnemers niet onverwacht om dezelfde meldingen concurreren.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Tailscale voor Gmail-hooks`},help:{"v1-7jzidp-4l":`Configuratieblok voor het toegankelijk maken van Gmail-callbacks via Tailscale met Serve/Funnel-routes. Gebruik privémodi binnen het tailnet voordat u een openbare toegangsroute inschakelt.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Tailscale-modus voor Gmail-hooks`},help:{"v1-vhm395-4u":`Tailscale-modus voor het beschikbaar stellen van Gmail-callbacks: "off", "serve" of "funnel". Gebruik "serve" voor aflevering via een privétailnet en "funnel" alleen wanneer toegang vanaf het openbare internet vereist is.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Tailscale-pad voor Gmail-hook`},help:{"v1-fr8qi-4m":`Pad dat door Tailscale Serve/Funnel wordt gepubliceerd om Gmail-callbacks door te sturen wanneer dit is ingeschakeld. Stem dit af op de Gmail-webhookconfiguratie, zodat verzoeken de verwachte handler bereiken.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Tailscale-doel voor Gmail-hook`},help:{"v1-1twwxge-47":`Lokaal servicedoel waarnaar Tailscale Serve/Funnel verkeer doorstuurt (bijvoorbeeld http://127.0.0.1:8787). Gebruik expliciete loopbackdoelen om onduidelijke routering te voorkomen.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Overschrijving van denkinspanning voor Gmail-hook`},help:{"v1-17owk9q-4z":`Overschrijving van de denkinspanning voor door Gmail gestarte agentuitvoeringen: "off", "minimal", "low", "medium" of "high". Houd de standaardinstellingen voor routinematige inboxautomatiseringen bescheiden om kosten en latentie te beperken.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Pub/Sub-topic voor Gmail-hook`},help:{"v1-iled0e-4p":`Naam van het Google Pub/Sub-topic dat Gmail watch gebruikt om wijzigingsmeldingen voor dit account te publiceren. Zorg dat de IAM-instellingen van het topic Gmail publicatierechten verlenen voordat u watches inschakelt.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`Interne hooks`},help:{"v1-piq9k-4v":`Runtime-instellingen voor interne hooks voor meegeleverde of aangepaste gebeurtenishandlers die vanuit modulepaden worden geladen. Gebruik dit voor vertrouwde automatiseringen binnen hetzelfde proces en beperk strikt welke handlers worden geladen.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`Interne hooks ingeschakeld`},help:{"v1-1wv0289-4c":`Schakelt de verwerking van interne hooks en geconfigureerde items in de runtime voor interne hooks in. Laat dit uitgeschakeld, tenzij interne hooks bewust zijn geconfigureerd.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`Interne hook-items`},help:{"v1-1ovi38l-4o":`Geconfigureerde interne hook-items waarmee concrete runtimehandlers en metadata worden geregistreerd. Houd items expliciet en onder versiebeheer, zodat het gedrag in productie controleerbaar is.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`Lader voor interne hooks`},help:{"v1-11re5ph-4p":`Instellingen voor de lader van interne hooks die bepalen waar bij het opstarten naar handlermodules wordt gezocht. Beperk de hoofdmappen voor het laden om onbedoelde moduleconflicten of het overschaduwen van modules te verminderen.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`Extra mappen voor interne hooks`},help:{"v1-1xfdqxg-4c":`Extra mappen waarin naast de standaardlaadpaden naar interne hookmodules wordt gezocht. Houd deze lijst minimaal en onder controle om onbedoeld overschaduwen van modules te verminderen.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`Hooktoewijzingen`},help:{"v1-frhp3v-5i":`Geordende toewijzingsregels die inkomende hookverzoeken herkennen en wake- of agent-acties kiezen, met optionele routering voor aflevering. Plaats specifieke toewijzingen eerst om te voorkomen dat brede patroonregels alles afvangen.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`Actie voor hooktoewijzing`},help:{"v1-1r5zt5f-5f":`Actietype voor de toewijzing: "wake" activeert het wekproces van de agent, terwijl "agent" het verzoek rechtstreeks doorstuurt voor verwerking door de agent. Gebruik "agent" voor onmiddellijke uitvoering en "wake" wanneer verwerking op basis van de heartbeat de voorkeur heeft.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`Agent-ID voor hooktoewijzing`},help:{"v1-l0uioz-4y":`ID van de doelagent voor het uitvoeren van de mapping wanneer actieroutering niet de standaardinstellingen moet gebruiken. Gebruik aparte automatiseringsagents om webhookgedrag te isoleren van interactieve operatorsessies.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`Onveilige externe inhoud toestaan voor hookmapping`},help:{"v1-1np9426-57":`Als dit true is, kan de mappinginhoud minder grondig opgeschoonde externe payloadgegevens bevatten in gegenereerde berichten. Houd dit standaard op false en schakel het alleen in voor vertrouwde bronnen met gecontroleerde transformatielogica.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`Afleverkanaal voor hookmapping`},help:{"v1-oz7pu5-5s":`Overschrijving van het afleverkanaal voor mappinguitvoer (bijvoorbeeld "last", "telegram", "discord", "slack", "signal", "imessage" of "msteams"). Geef kanaaloverschrijvingen expliciet op om onbedoelde verzending naar andere kanalen te voorkomen.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`Antwoord van hookmapping afleveren`},help:{"v1-12tbbam-5o":`Bepaalt of de uitvoeringsresultaten van de mapping worden teruggestuurd naar een kanaalbestemming of stilzwijgend worden verwerkt. Schakel aflevering uit voor achtergrondautomatiseringen die geen voor gebruikers zichtbare uitvoer mogen plaatsen.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`Sleutel voor opsplitsing van hookmapping`},help:{"v1-1d593op-7e":`Sleutel van de array op het hoogste niveau van de payload waarover de mapping wordt opgesplitst: elk element activeert een eigen actie, en sjablonen of transformaties krijgen een payload waarvan de array alleen het huidige element bevat. De Gmail-voorinstelling gebruikt forEach: messages, zodat gebundelde pushmeldingen één uitvoering per e-mail activeren.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`Hookmapping-ID`},help:{"v1-q1t4zw-57":`Optionele stabiele identificatie voor een hooktoewijzing, gebruikt voor audits, probleemoplossing en gerichte updates. Gebruik unieke ID's zodat logboeken en configuratieverschillen ondubbelzinnig naar toewijzingen kunnen verwijzen.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`Overeenkomstcriteria voor hooktoewijzing`},help:{"v1-6u73k2-5a":`Object dat overeenkomstvoorwaarden voor toewijzingen, zoals pad en bron, groepeert voordat actieroutering wordt toegepast. Houd de overeenkomstcriteria specifiek, zodat niet-gerelateerd webhookverkeer geen automatiseringen activeert.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`Padcriterium voor hooktoewijzing`},help:{"v1-1d7dc5j-4k":`Voorwaarde voor padovereenkomst bij een hooktoewijzing, meestal vergeleken met het pad van het inkomende verzoek. Gebruik dit om het automatiseringsgedrag op te splitsen op basis van groepen webhook-eindpuntpaden.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`Broncriterium voor hooktoewijzing`},help:{"v1-177zgy7-52":`Voorwaarde voor bronovereenkomst bij een hooktoewijzing, doorgaans ingesteld door vertrouwde metadata van een bovenliggende bron of door adapterlogica. Gebruik stabiele bronidentificaties zodat de routering bij herhaalde pogingen deterministisch blijft.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`Berichtsjabloon voor hooktoewijzing`},help:{"v1-ggqszl-5c":`Sjabloon om gestructureerde toewijzingsinvoer om te zetten in de uiteindelijke berichtinhoud die naar het doelactiepad wordt verzonden. Houd sjablonen deterministisch zodat de verdere verwerking en het daaropvolgende gedrag stabiel blijven.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`Modeloverschrijving voor hooktoewijzing`},help:{"v1-10qyo4j-5e":`Optionele modeloverschrijving voor uitvoeringen die door een mapping worden gestart, wanneer de automatisering een ander model moet gebruiken dan het standaardmodel van de agent. Gebruik dit spaarzaam, zodat het gedrag bij verschillende uitvoeringen van de mapping voorspelbaar blijft.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`Naam van hookmapping`},help:{"v1-zrd9tn-4v":`Leesbare weergavenaam van de mapping, gebruikt in diagnostiek en configuratie-interfaces voor beheerders. Houd namen beknopt en beschrijvend, zodat het doel van de routering duidelijk is bij het onderzoeken van incidenten.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`Sessiesleutel van hookmapping`},help:{"v1-lfnt1n-58":`Expliciete overschrijving van de sessiesleutel voor berichten die via een mapping worden afgeleverd, om de continuïteit van gespreksthreads te regelen. Gebruik stabiele sleutels met een afgebakend bereik, zodat herhaalde gebeurtenissen aan elkaar worden gekoppeld zonder in niet-gerelateerde gesprekken terecht te komen.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`Sessiemodus van hookmapping`},help:{"v1-1ggtdze-5k":`Regelt de sessiecontinuïteit van de mapping: "isolated" start een nieuwe uitvoeringssessie, terwijl "persistent" de bepaalde sessionKey hergebruikt. Behoud isolated, tenzij de integratie bewust blijvende context nodig heeft.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`Tekstsjabloon van hookmapping`},help:{"v1-1rg732b-4y":`Terugvalsjabloon met alleen tekst, gebruikt wanneer een rijke weergave van de payload niet gewenst is of niet wordt ondersteund. Gebruik dit om een beknopte, consistente samenvatting te bieden voor aflevering in chatinterfaces.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`Overschrijving van denkinstelling voor hookmapping`},help:{"v1-17hq8me-57":`Optionele aanpassing van de denkinspanning voor uitvoeringen die door een mapping worden geactiveerd, om de balans tussen latentie en redeneerdiepte af te stemmen. Houd deze laag of minimaal voor hooks met een hoog volume, tenzij diepgaander redeneren duidelijk vereist is.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`Time-out voor hookmapping (sec)`},help:{"v1-1r44ox2-4i":`Maximale toegestane looptijd voor de uitvoering van een mappingactie voordat de time-outafhandeling van kracht wordt. Gebruik kortere limieten voor webhookbronnen met een hoog volume om opstoppingen in de wachtrij te voorkomen.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`Afleverbestemming voor hookmapping`},help:{"v1-1p7928e-55":`Bestemmings-ID binnen het geselecteerde kanaal wanneer antwoorden van de mapping naar een vaste bestemming moeten worden geleid. Controleer de providerspecifieke bestemmingsindelingen voordat u mappings in productie inschakelt.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`Transformatie voor hookmapping`},help:{"v1-14igxpm-5m":`Transformatieconfiguratieblok dat de voorbewerking via een module/export definieert voordat de mappingactie wordt afgehandeld. Gebruik alleen transformaties uit gecontroleerde codepaden en houd het gedrag deterministisch voor herhaalbare automatisering.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`Export voor hooktransformatie`},help:{"v1-atn8v-4b":`Benoemde export die vanuit de transformatiemodule moet worden aangeroepen; als deze wordt weggelaten, wordt de standaardexport van de module gebruikt. Stel dit in wanneer één bestand meerdere transformatiehandlers bevat.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`Module voor hooktransformatie`},help:{"v1-56futq-4v":`Relatief pad naar een transformatiemodule die vanuit hooks.transformsDir wordt geladen om binnenkomende payloads vóór aflevering te herschrijven. Houd modules lokaal, controleer ze en zorg dat ze geen patronen voor padtraversal bevatten.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`Activeringsmodus voor hooktoewijzing`},help:{"v1-1dzqfnw-59":`Planningsmodus voor activering: "now" activeert onmiddellijk, terwijl "next-heartbeat" de activering uitstelt tot de volgende heartbeatcyclus. Gebruik de uitgestelde modus voor automatiseringen met een lagere prioriteit waarvoor een kleine vertraging acceptabel is.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`Pad van hookendpoint`},help:{"v1-1l9ijzv-4u":"HTTP-pad dat door het hookendpoint wordt gebruikt (bijvoorbeeld `/hooks`) op de beheerserver van de gateway. Gebruik een niet te raden pad en combineer dit met tokenvalidatie voor gelaagde beveiliging."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`Voorinstellingen voor hooks`},help:{"v1-dp8m0l-4v":`Benoemde bundels met hookvoorinstellingen die bij het laden worden toegepast om standaardtoewijzingen en standaardgedrag in te stellen. Gebruik voorinstellingen expliciet, zodat beheerders kunnen controleren welke automatiseringen actief zijn.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`Authenticatietoken voor hooks`},help:{"v1-1ihf6mv-82":`Gedeeld bearertoken dat bij binnenkomende hookverzoeken wordt gecontroleerd voor authenticatie voordat toewijzingen worden uitgevoerd. Behandel tokenhouders als volledig vertrouwde aanroepers van de hookingang, niet als een afzonderlijke rol zonder eigenaarsrechten. Gebruik substitutie via omgevingsvariabelen en roteer het token regelmatig wanneer webhookendpoints via internet toegankelijk zijn.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`Map voor hooktransformaties`},help:{"v1-1ayj9p0-4t":`Basismap voor hooktransformatiemodules waarnaar de transform.module-paden in toewijzingen verwijzen. Gebruik een beheerde repositorymap, zodat dynamische imports controleerbaar en voorspelbaar blijven.`}},logging:{label:{"v1-rq08xq-7":`Logregistratie`},help:{"v1-11an9pb-5e":`Instellingen voor logregistratie: ernstniveau, uitvoerbestemmingen, opmaak en het maskeren van gevoelige gegevens. Houd niveaus en maskering strikt genoeg voor productie, maar behoud nuttige diagnostische informatie.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`Auditlogboek`},help:{"v1-1lauvy2-6w":`Begrensde auditgeschiedenis met uitsluitend metagegevens, ter controle door beheerders. Registraties van uitvoeringen en tools zijn standaard ingeschakeld; metagegevens over de levenscyclus van berichten zijn privacygevoelig en vereisen afzonderlijke toestemming. Het schrijfproces op de achtergrond werkt naar beste vermogen en is geen verliesvrij archief voor nalevingsdoeleinden.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`Auditlogboek ingeschakeld`},help:{"v1-snknxb-4v":`Registreert nieuwe auditgebeurtenissen voor uitvoeringen en tools, en voor berichten als die zijn ingeschakeld. Standaard: true. Wijzigingen worden onmiddellijk van kracht; geaccepteerde schrijfbewerkingen worden voltooid en bewaarde rijen blijven opvraagbaar totdat ze verlopen.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`Audit van uitvoeringsidentiteit`},help:{"v1-1ucirwv-5b":`Bewaart toewijzingsgegevens van de uitvoeringsidentiteit binnen vastgestelde grenzen voor inspectie van een specifieke uitvoering. Standaard: false. Vereist logging.audit.enabled en geldt voor nieuw toegelaten uitvoeringen; bestaande contexten blijven ongewijzigd.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`Bereik van berichtaudit`},help:{"v1-1yg4lc3-76":`Bepaalt welke levenscyclusgegevens van berichten zonder berichtinhoud worden geregistreerd: "off" (standaard), "direct" voor uitsluitend bekende directe gesprekken, of "all" voor directe gesprekken, groepsgesprekken, kanaalgesprekken en onbekende gesprekstypen. Vereist logging.audit.enabled. Wijzigingen gelden voor daaropvolgende levenscyclusgebeurtenissen.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`Logniveau voor console`},help:{"v1-16badbd-5u":`Consolespecifieke logdrempel: "silent", "fatal", "error", "warn", "info", "debug" of "trace" om de terminaluitvoer te regelen. Gebruik dit om de lokale console rustiger te houden en zo nodig uitgebreidere logregistratie in bestanden te behouden.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`Stijl van consolelog`},help:{"v1-d7u0iq-3q":`Indeling van de consoleuitvoer: "pretty" of "json". Gebruik json voor automatische verwerking in pipelines en pretty voor terminalworkflows die op menselijke leesbaarheid zijn gericht.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`Pad naar logbestand`},help:{"v1-16gaitv-4w":`Optioneel bestandspad voor opgeslagen loguitvoer, naast of in plaats van consolelogregistratie. Gebruik een beheerd, beschrijfbaar pad en stem de bewaartermijn en rotatie af op je operationele beleid.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`Logniveau`},help:{"v1-1r5yku0-5o":`Primaire logniveaudrempel voor loguitvoer tijdens de uitvoering: "silent", "fatal", "error", "warn", "info", "debug" of "trace". Houd "info" of "warn" aan voor productie en gebruik debug/trace alleen tijdens onderzoek.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`Aangepaste maskeringspatronen`},help:{"v1-1esa6eg-7k":`Aangepaste regex-strings vervangen de standaardlijst met strings voor logboek- en transcriptuitvoer en vormen een aanvulling op de regels voor veiligheidsgrenzen in de UI, tools en diagnostiek. Ingebouwde beveiligingen voor formulierinhoud, gestructureerde authenticatie en losse AWS-sleutels zijn altijd van toepassing. Gebruik dit om implementatiespecifieke tokens en identificatoren te maskeren.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`Globale MCP-serverdefinities die door OpenClaw worden beheerd. Ingebedde OpenClaw-instanties en andere runtime-adapters kunnen deze servers gebruiken zonder ze op te slaan in projectspecifieke instellingen van de runtime.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`MCP-apps`},help:{"v1-amyd91-38":`Ondersteuning voor de MCP Apps-interface. Indien ingeschakeld, kunnen geconfigureerde MCP-servers interactieve HTML-weergaven voor hun toolresultaten aanbieden.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps ingeschakeld`},help:{"v1-ghqy98-3w":`Optionele weergave van MCP Apps en verbinding tussen app en server. Laat dit uitgeschakeld tenzij u de geconfigureerde MCP-servers vertrouwt die bronnen voor de app-interface aanbieden.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`Sandbox-origin voor MCP Apps`},help:{"v1-1sxv3mf-6v":`Optionele, afzonderlijke openbare HTTP(S)-origin voor MCP Apps. Gebruik deze achter een reverse proxy of TLS-terminator en stuur het verkeer uitsluitend door naar de geconfigureerde sandboxpoort voor MCP Apps. Deze moet verschillen van de origin van de Control UI en mag geen inhoud aanbieden waarvoor authenticatie vereist is.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`Sandboxpoort voor MCP Apps`},help:{"v1-1b8n71l-4p":`Afzonderlijke luisterpoort voor de MCP Apps-sandbox. Standaard de Gateway-poort plus één. Stel een ongebruikte poort in wanneer een andere lokale service of een ander Gateway-profiel die poort al gebruikt.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`MCP-servers`},help:{"v1-157ozoz-42":`Benoemde MCP-serverdefinities. OpenClaw slaat deze op in zijn eigen configuratie en runtime-adapters bepalen welke transporten tijdens de uitvoering worden ondersteund.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`MCP-serverauthenticatie`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`MCP-clientcertificaat`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`MCP-clientsleutel`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`MCP-clientcertificaat`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`MCP-clientsleutel`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Codex MCP-projectie`},help:{"v1-slcmq1-6x":`OpenClaw-projectiemetadata uitsluitend voor Codex app-server-threads. Dit heeft geen invloed op ACP-sessies of de algemene Codex-harnasconfiguratie. Laat dit blok weg om de server beschikbaar te houden voor elke Codex app-server-agent met het standaard MCP-goedkeuringsgedrag van Codex.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Codex MCP-agenten`},help:{"v1-8q98n8-67":`Optionele, niet-lege OpenClaw-agent-id's die deze MCP-server moeten ontvangen in de Codex app-server-threadconfiguratie. Lege lijsten, lijsten met uitsluitend witruimte of ongeldige lijsten blokkeren de toegang; als deze instelling wordt weggelaten, wordt de server voor alle Codex app-server-agenten geprojecteerd.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Codex MCP-toolgoedkeuring`},help:{"v1-1xql0qr-3d":`Codex-eigen schrijfwijze voor dezelfde goedkeuringsmodus voor MCP-tools per server. Gebruik bij voorkeur defaultToolsApprovalMode in de OpenClaw-configuratie.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Codex MCP-toolgoedkeuring`},help:{"v1-y5vsqq-3s":`Optionele goedkeuringsmodus voor Codex MCP-tools voor deze server: "auto", "prompt" of "approve". Gebruik dit alleen voor MCP-servers die je bewust vertrouwt.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`MCP-verbindingstime-out (ms)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`MCP-server ingeschakeld`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`MCP OAuth`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`MCP OAuth-authenticatieprofiel`},help:{"v1-fcrb4u-5z":`ID van een authenticatieprofiel met ondersteuning voor vernieuwing, waarmee het huidige bearer-token aan deze externe MCP-server wordt doorgegeven. Als dit is ingesteld, zoekt OpenClaw het profiel tijdens runtime op en vernieuwt het, zonder vernieuwingsgegevens door te geven aan achterliggende systemen.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`URL voor MCP OAuth-clientmetadata`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`MCP OAuth-identiteit`},help:{"v1-1ie6ys7-59":`Eigenaarschap van OAuth-inloggegevens voor deze server. Laat dit veld weg of gebruik "shared" voor inloggegevens die door de beheerder worden beheerd; gebruik "per-requester" om elke geauthenticeerde afzender een eigen account te laten koppelen.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`MCP OAuth-omleidings-URL`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`MCP OAuth-bereik`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`Time-out voor MCP-verzoeken (ms)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`MCP TLS-verificatie`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`MCP TLS-verificatie`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`Parallelle MCP-toolaanroepen`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`Parallelle MCP-toolaanroepen`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`MCP-toolselectie`},help:{"v1-10poyzb-4v":`Selectie van MCP-tools per server. Gebruik include om alleen geselecteerde MCP-toolnamen beschikbaar te stellen, of exclude om geselecteerde MCP-toolnamen te verbergen. Vermeldingen accepteren exacte namen en eenvoudige globpatronen met '*'.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`Uitgesloten MCP-tools`},help:{"v1-ijrc5y-1u":`Exacte MCP-toolnamen of eenvoudige '*'-globpatronen om tools van deze server te verbergen.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`Opgenomen MCP-tools`},help:{"v1-89fdfq-3o":`Exacte MCP-toolnamen of eenvoudige '*'-globpatronen om tools van deze server beschikbaar te stellen. Indien weggelaten, blijven alle servertools beschikbaar, tenzij ze zijn uitgesloten.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`TTL voor inactieve MCP-sessies (ms)`},help:{"v1-j9si74-87":`Optionele termijn in milliseconden voor het opruimen van inactieve MCP-runtimes van OpenClaw-sessies. Als deze niet is ingesteld of 0 is, blijven runtimes actief totdat de sessie wordt opgeruimd of de Gateway wordt afgesloten. Positieve waarden worden naar beneden afgerond; actieve leases en aanvragen in behandeling voorkomen het opruimen. Runtimes die bij een uitvoering horen, worden nog steeds beëindigd zodra hun eenmalige uitvoering eindigt.`}},memory:{label:{"v1-oopaku-6":`Geheugen`},help:{"v1-1wlx40m-13":`Configuratie van het ingebouwde geheugen (globaal).`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`Modus voor bronvermeldingen uit het geheugen`},help:{"v1-1q6dxr5-4u":`Bepaalt de zichtbaarheid van bronvermeldingen in antwoorden: "auto" toont bronvermeldingen wanneer ze nuttig zijn, "on" toont ze altijd en "off" verbergt ze. Houd "auto" aan als standaard voor een evenwichtige signaal-ruisverhouding.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`Geheugen doorzoeken`},help:{"v1-1ukbud1-25":`Vectorzoeken in MEMORY.md en memory/*.md (afwijkende instellingen per agent worden ondersteund).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`Embeddingcache voor zoeken in het geheugen`},help:{"v1-d8h2e4-5b":`Slaat berekende embeddings van tekstfragmenten op in SQLite, zodat herindexering en incrementele updates sneller verlopen (standaard: true). Laat dit ingeschakeld, tenzij u de juistheid van de cache onderzoekt of het schijfgebruik wilt minimaliseren.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`Documentinvoertype voor zoeken in het geheugen`},help:{"v1-1ui33sv-5f":"Optionele providerspecifieke `input_type`-waarde voor geheugenembeddings van documenten en voor indexering. Gebruik dit met OpenAI-compatibele asymmetrische embedding-eindpunten die een passage- of documentlabel vereisen."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`Zoeken in geheugen inschakelen`},help:{"v1-14f11b9-4t":`Hoofdschakelaar voor het indexeren en ophalen van gegevens bij zoeken in het geheugen voor dit agentprofiel. Laat dit ingeschakeld om informatie semantisch terug te vinden en schakel het uit voor volledig toestandloze antwoorden.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`Sessie-index voor zoeken in geheugen (experimenteel)`},help:{"v1-qvhv8z-3i":`Indexeert sessietranscripten voor zoeken in het geheugen. Behoud deze geavanceerde overschrijving wanneer de overerving van instellingen voor het terugvinden van informatie op hoofdniveau en per agent verschilt.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`Extra geheugenpaden`},help:{"v1-ojqokq-7i":`Voegt naast de standaardgeheugenbestanden extra mappen of .md-bestanden toe aan de geheugenindex. Items kunnen padtekenreeksen zijn of objecten met een glob-patroon relatief aan de hoofdmap. Wanneer multimodaal geheugen is ingeschakeld, komen overeenkomende afbeeldings- en audiobestanden onder deze paden ook in aanmerking voor indexering.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`Extra geheugenpad`},help:{"v1-b9mbq8-3m":`Stelt de extra geheugenmap of het extra geheugenbestand in. Relatieve paden worden bepaald vanuit de werkruimte van de agent; rechtstreeks opgegeven bestanden worden exact zoals opgegeven geïndexeerd.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`Patroon voor extra geheugenpad`},help:{"v1-j8br1v-4e":`Beperkt een mapitem tot ondersteunde bestanden die overeenkomen met dit glob-patroon relatief aan de hoofdmap, bijvoorbeeld "runbooks/**/*.md". Laat dit weg om alle ondersteunde bestanden recursief te scannen.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`Terugvaloptie voor zoeken in geheugen`},help:{"v1-1r6368w-6p":`Reserveprovider die wordt gebruikt wanneer de primaire embeddings mislukken: "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local" of "none". Stel een daadwerkelijke terugvaloptie in voor betrouwbaarheid in productie; gebruik "none" alleen als je de voorkeur geeft aan expliciete fouten.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`Invoertype voor zoeken in geheugen`},help:{"v1-26vbwe-5u":"Gebruik deze optionele providerspecifieke waarde voor `input_type` alleen wanneer hetzelfde label moet gelden voor embeddingverzoeken voor zowel zoekopdrachten als documenten. Gebruik bij asymmetrische providers bij voorkeur queryInputType en documentInputType."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`Pad naar lokaal embeddingmodel`},help:{"v1-13ymbnt-5q":"Geeft de bron van het lokale embeddingmodel op voor lokaal zoeken in geheugen, zoals een pad naar een GGUF-bestand of een `hf:`-URI. Gebruik dit alleen wanneer provider is ingesteld op `local` en controleer de modelcompatibiliteit voordat je grote indexen opnieuw opbouwt."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`Model voor zoeken in geheugen`},help:{"v1-11pohrl-59":`Alternatief embeddingmodel dat de geselecteerde geheugenprovider gebruikt wanneer een niet-standaardmodel nodig is. Stel dit alleen in als je de kwaliteit of kosten van het ophalen van informatie expliciet wilt afstemmen buiten de standaardinstellingen van de provider.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`Multimodaal zoeken in geheugen`},help:{"v1-1jn02s-9e":'Optionele multimodale geheugeninstellingen voor het indexeren van afbeeldings- en audiobestanden uit geconfigureerde extra paden. Laat dit uitgeschakeld tenzij je embeddingmodel expliciet crossmodale embeddings ondersteunt en stel `memory.search.fallback` in op "none" zolang dit is ingeschakeld. Bestanden die aan de criteria voldoen, worden tijdens het indexeren geüpload naar de geconfigureerde externe embeddingprovider.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`Multimodaal zoeken in het geheugen inschakelen`},help:{"v1-1dk5d7o-7e":`Schakelt het indexeren van afbeeldingen en audio uit extraPaths in het geheugen in. Dit vereist momenteel Gemini embedding-2, houdt de standaardgeheugenmappen beperkt tot Markdown, schakelt terugvalproviders voor zoeken in het geheugen uit en uploadt overeenkomende binaire inhoud naar de geconfigureerde externe embeddingprovider.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`Maximale bestandsgrootte in bytes voor multimodaal zoeken in het geheugen`},help:{"v1-1mmdrvk-5d":`Stelt het maximale aantal bytes per multimodaal bestand in. Grotere bestanden worden bij het indexeren van het geheugen overgeslagen. Gebruik dit om uploadkosten en indexeringsvertraging te beperken, of verhoog de waarde voor korte audioclips van hoge kwaliteit.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`Modaliteiten voor multimodaal zoeken in het geheugen`},help:{"v1-alp4vh-4l":`Selecteert welke multimodale bestandstypen uit extraPaths worden geïndexeerd: "image", "audio" of "all". Houd deze selectie beperkt om te voorkomen dat grote binaire gegevensverzamelingen onbedoeld worden geïndexeerd.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`Aantal uitvoerdimensies voor zoeken in het geheugen`},help:{"v1-1f7zu53-93":`Providerspecifieke overschrijving van de uitvoervectorgrootte voor geheugenembeddings. Gemini-modellen ondersteunen 128-3072 dimensies en bevelen 768, 1536 of 3072 aan; Bedrock-modelfamilies zoals Titan V2, Cohere V4 en Nova bieden hun eigen toegestane groottes. Houd bij wijziging rekening met een volledige herindexering, omdat de dimensies van opgeslagen vectoren consistent moeten blijven.`}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`Provider voor zoeken in het geheugen`},help:{"v1-5evseb-71":`Selecteert de embedding-backend voor het opbouwen en doorzoeken van geheugenvectoren. De standaardwaarde is "openai"; stel "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama" of "local" in als je een andere backend wilt gebruiken.`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`Maximaal aantal resultaten bij zoeken in het geheugen`},help:{"v1-13ekath-4x":`Het maximale aantal geheugenresultaten dat een zoekopdracht retourneert voordat ze opnieuw worden gerangschikt en aan de prompt worden toegevoegd. Verhoog dit voor een bredere selectie, of verlaag het voor compactere prompts en snellere antwoorden.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`Minimumscore bij zoeken in het geheugen`},help:{"v1-1ww231l-4v":`De minimale relevantiescore voor het opnemen van geheugenresultaten in de uiteindelijke opgehaalde context. Verhoog deze om zwakke of onbruikbare overeenkomsten te beperken, of verlaag deze als je ruimere zoekcriteria nodig hebt.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`Invoertype voor zoekopdrachten in het geheugen`},help:{"v1-831yrv-4q":"Optionele providerspecifieke waarde voor `input_type` voor geheugenembeddings tijdens zoekopdrachten. Gebruik dit met OpenAI-compatibele asymmetrische embedding-eindpunten die een zoekopdrachtlabel vereisen."}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`Onthouden tussen gesprekken`},help:{"v1-k1itm8-7y":`Gebruik relevante context uit andere privégesprekken van deze agent door gespreksverslagen beveiligd op te halen. Standaard alleen ingeschakeld als de globale session.dmScope niet is ingesteld of "main" is en geen enkele binding het DM-bereik overschrijft; bij elke geconfigureerde DM-isolatie is dit standaard uitgeschakeld. Een expliciete waarde true of false heeft altijd voorrang.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`API-sleutel voor externe embeddings`},help:{"v1-nfuuu-62":`Stelt een aparte API-sleutel in voor externe embedding-aanroepen die worden gebruikt voor geheugenindexering en embeddings tijdens zoekopdrachten. Gebruik dit als geheugenembeddings andere inloggegevens moeten gebruiken dan de algemene standaardwaarden of omgevingsvariabelen.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`Basis-URL voor externe embeddings`},help:{"v1-1ugvqgt-5p":`Overschrijft het API-eindpunt voor embeddings, bijvoorbeeld met een OpenAI-compatibele proxy of een aangepaste Gemini-basis-URL. Gebruik dit alleen bij routering via uw eigen gateway of een leveranciers-eindpunt; behoud anders de standaardwaarden van de provider.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`Externe batch-embeddings ingeschakeld`},help:{"v1-1fehqi-5x":`Schakelt batch-API's van providers in voor embedding-taken waar ondersteund (OpenAI/Gemini), wat de verwerkingssnelheid bij grotere indexeringsrondes verbetert. Laat dit ingeschakeld, tenzij u batchfouten bij de provider onderzoekt of zeer kleine werklasten uitvoert.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`Headers voor externe embeddings`},help:{"v1-1uic0kd-5i":`Voegt aangepaste HTTP-headers toe aan externe embedding-verzoeken, samengevoegd met de standaardheaders van de provider. Gebruik dit voor proxyauthenticatie en headers voor tenantroutering, en beperk de waarden tot het minimum om te voorkomen dat gevoelige metadata uitlekken.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`Bronnen voor zoeken in het geheugen`},help:{"v1-btxtzg-57":`Bepaalt welke bronnen worden geïndexeerd: "memory" leest MEMORY.md + geheugenbestanden, en "sessions" neemt de transcriptgeschiedenis mee. Behoud ["memory"], tenzij u informatie uit eerdere chattranscripten wilt kunnen ophalen.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`Vectorindex voor zoeken in het geheugen`},help:{"v1-fbybkj-37":`Bepaalt de semantische index van sqlite-vec. Behoud deze geavanceerde overschrijving wanneer het vectorbeleid op hoofdniveau verschilt van dat per agent.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`Pad naar vectorextensie voor geheugenzoekfunctie`},help:{"v1-1hysv5q-58":"Overschrijft het automatisch gevonden pad naar de sqlite-vec-extensiebibliotheek (`.dylib`, `.so` of `.dll`). Gebruik dit wanneer je runtime sqlite-vec niet automatisch kan vinden of wanneer je een bewezen werkende build vastzet."}},messages:{label:{"v1-1wwzqad-8":`Berichten`},help:{"v1-i5k0iw-5k":`Berichteninfrastructuur en standaardinstellingen voor alle agents. Onderdelen op hoofdniveau beheren de infrastructuur en standaardinstellingen voor alle agents; agents.defaults beheert het gedrag van de agentlus; afzonderlijke agentconfiguraties kunnen beide overschrijven waar dit wordt ondersteund.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`Emoji voor bevestigingsreactie`},help:{"v1-1iip0zs-1x":`Emoji-reactie om inkomende berichten te bevestigen (leeg schakelt dit uit).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`Bereik van bevestigingsreacties`},help:{"v1-1jvdg5n-7s":`Wanneer bevestigingsreacties worden verzonden ("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions" bevestigt groepsberichten waarin de agent wordt vermeld, ongeacht of de groep vermeldingen vereist; "group-all" bevestigt elk groepsbericht. "off"/"none" schakelt bevestigingsreacties volledig uit.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`Regels voor groepschats`},help:{"v1-chqsvh-4l":`Instellingen voor de verwerking van groepsberichten, waaronder activering door vermeldingen en de grootte van het geschiedenisvenster. Houd vermeldingspatronen specifiek, zodat groepskanalen niet op elk bericht reageren.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`Limiet voor groepsgeschiedenis`},help:{"v1-1mkbpw-9k":`Het maximale aantal eerdere groepsberichten dat per beurt als context wordt geladen voor groepssessies. Gebruik hogere waarden voor meer samenhang, of lagere waarden voor snellere en goedkopere antwoorden. De automatische promptgeschiedenis is beperkt tot 200 berichten. De maximale waarde voor een JSON-geheel getal selecteert het standaardvenster van het kanaal (50 voor gedeelde groepsgeschiedenis), niet een onbeperkt venster.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`Patronen voor groepsvermeldingen`},help:{"v1-i7h7qc-6f":`Veilige, hoofdletterongevoelige regex-patronen om expliciete vermeldingen of activeringszinnen in groepschats te detecteren. Gebruik nauwkeurige patronen om onterechte detecties in drukke kanalen te beperken; ongeldige of onveilige patronen met geneste herhalingen worden genegeerd.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`Inkomende groepsberichten zonder vermelding`},help:{"v1-17wef8h-5f":`Bepaalt hoe groepsberichten zonder vermelding worden ingediend wanneer de verwerking altijd actief is. "user_request" behandelt ze als een gebruikersverzoek; "room_event" dient ze in als stille context waarbij zichtbare uitvoer de berichtentool vereist.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`Zichtbare groepsantwoorden`},help:{"v1-qa4z1s-aa":`Overschrijft de door het model opgestelde oorspronkelijke antwoorden voor groeps- en kanaalgesprekken. Standaard ingesteld op "automatic" als er geen algemeen beleid voor zichtbare antwoorden is ingesteld. "message_tool" vereist message(action=send) voor normale assistentuitvoer en algemene toolmedia; runtime-uitvoer die expliciet onder de verantwoordelijkheid van de host valt, kan nog steeds worden afgeleverd, behalve bij achtergrondgebeurtenissen in de chatruimte. "automatic" plaatst normale antwoorden zoals voorheen.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`Debounce voor inkomende berichten`},help:{"v1-ebyu5x-4a":`Debounce-instellingen die direct op inkomende berichten worden toegepast voordat de wachtrij- of beurtverwerking begint. Configureer dit voor providerspecifieke reeksen snel opeenvolgende berichten van dezelfde afzender.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`Debounce voor inkomende berichten per kanaal (ms)`},help:{"v1-wbz54j-4g":`Kanaalspecifieke overrides voor de debounce van inkomende berichten, in milliseconden, met provider-id als sleutel. Gebruik dit wanneer sommige providers sneller achter elkaar berichtfragmenten verzenden dan andere.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`Debounce voor inkomende berichten (ms)`},help:{"v1-1616yo2-7w":`Wachttijd zonder nieuwe berichten (ms) voor het bundelen van snel opeenvolgende inkomende berichten van dezelfde afzender. Telegram gebruikt standaard 300 ms wanneer er geen globale of kanaalspecifieke instelling is opgegeven; andere kanalen gebruiken standaard 0. Nul schakelt het bundelen van snel opeenvolgende berichten uit, maar Telegram voegt delen van lange berichten die de limiet benaderen nog steeds samen.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`Wachtrij voor inkomende berichten`},help:{"v1-hm2o31-48":`Wachtrijstrategie voor inkomende berichten die binnenkomen terwijl een sessie wordt uitgevoerd. Gebruik dit om bijsturing, uitgestelde vervolgberichten, bundeling of onderbreking af te stemmen.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`Wachtrijmodus per kanaal`},help:{"v1-4rf8z8-54":`Kanaalspecifieke overrides voor de wachtrijmodus met provider-id als sleutel (bijvoorbeeld telegram, discord, slack). Gebruik dit wanneer het verkeerspatroon van een kanaal ander gedrag vereist dan de algemene standaardinstellingen.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`Wachtrijcapaciteit`},help:{"v1-16ql8c7-4j":`Maximumaantal inkomende items dat in de wachtrij wordt bewaard voordat het verwijderingsbeleid wordt toegepast. De standaardwaarde is 20; houd de capaciteit beperkt in drukke kanalen zodat het geheugengebruik voorspelbaar blijft.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`Terugvalwaarde voor wachtrijdebounce per kanaal (ms)`},help:{"v1-4tpyt7-4e":`Kanaalspecifieke debounce-overrides voor het wachtrijgedrag met provider-id als sleutel. Gebruik dit om de verwerking van berichtpieken afzonderlijk af te stemmen voor chatomgevingen met verschillende berichttempo's.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`Verwijderingsstrategie voor de wachtrij`},help:{"v1-ydb2rw-6m":`Strategie voor het verwijderen van items wanneer de wachtrijlimiet wordt overschreden. "summarize" verwijdert de oudste items, maar bewaart beknopte samenvattingen; "old" verwijdert de oudste items zonder samenvattingen; "new" weigert het nieuwste item. Gebruik "summarize" voor langdurige chats waarin context belangrijk is.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`Wachtrijmodus`},help:{"v1-19k7gy1-67":`Wachtrijmodus voor actieve uitvoeringen. Gebruik "steer" om prompts aan de actieve uitvoering toe te voegen, "followup" om ze later uit te voeren, "collect" om compatibele berichten later te bundelen, of "interrupt" om de actieve uitvoering af te breken voordat de nieuwste prompt wordt gestart.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`Voorvoegsel voor uitgaande antwoorden`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`Standaardmodus voor de verbruiksvoettekst`},help:{"v1-l3shsx-dv":`Standaardmodus voor de verbruiksvoettekst per antwoord ("off"|"tokens"|"full"), die wordt ingesteld voor sessies waarin nog geen modus via /usage is gekozen. Accepteert ook "on" als verouderde alias voor "tokens". Accepteert een losse modus of een toewijzing per kanaal met "default" als terugvalwaarde. Prioriteit: sessiewaarde -> kanaalinstelling -> default -> off; een expliciete keuze via /usage (inclusief off) wordt opgeslagen en overschrijft de standaardwaarde. Gebruik /usage reset (aliassen: inherit, clear, default) om een sessieoverschrijving te wissen en deze ingestelde standaardwaarde opnieuw over te nemen.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`Statusreacties`},help:{"v1-193764l-3s":`Statusreacties die de emoji op het activerende bericht bijwerken naarmate de agent vordert (in wachtrij → nadenken → tool → voltooid/fout).`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`Statusreacties inschakelen`},help:{"v1-1qnmmnc-7x":`Schakel statusreacties voor de levenscyclus in op ondersteunde kanalen. Discord beschouwt een niet-ingestelde waarde als ingeschakeld wanneer bevestigingsreacties actief zijn; Slack, Signal, Telegram en WhatsApp vereisen dat dit op true staat voordat levenscyclusreacties worden gebruikt. Slack gebruikt standaard de ingebouwde assistentstatus in threads om de voortgang weer te geven.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`Sjabloon voor gebruiksvoettekst`},help:{"v1-1xibc23-47":`Aangepast sjabloon voor de volledige /usage-voettekst, als inline-object of als pad naar een JSON-bestand. Bij ongeldige of niet-beschikbare sjablonen wordt de ingebouwde gebruiksregel gebruikt.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`Zichtbare antwoorden`},help:{"v1-7yfwc2-8t":`Bepaalt hoe door het model geschreven bronantwoorden worden weergegeven in directe gesprekken, groepsgesprekken en kanaalgesprekken. "message_tool" vereist message(action=send) voor normale assistentuitvoer en generieke toolmedia; runtime-uitvoer die expliciet onder het beheer van de host valt, blijft afleverbaar, behalve bij achtergrondgebeurtenissen in de gespreksruimte. "automatic" plaatst normale antwoorden zoals voorheen.`}},meta:{label:{"v1-1xpfxac-m":`Compatibiliteitsmetadata`},help:{"v1-1owqhgn-2w":`Compatibiliteitsmetadata die leesbaar blijven voor oudere versies, zodat oudere binaire bestanden onveilige configuratiedowngrades kunnen weigeren.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`Versie die de configuratie het laatst heeft gewijzigd`},help:{"v1-qykpv1-1i":`OpenClaw-versie die deze configuratie het laatst heeft opgeslagen.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`Markeringen voor configuratiemigraties`},help:{"v1-burt8q-1q":`Begrensde compatibiliteitsmarkeringen voor voltooide configuratiemigraties.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`Migratie van de toestemmingslijst voor modelbeleid`},help:{"v1-5psop1-1z":`Legt vast dat beperkingen uit de verouderde modeltoewijzing zijn behouden of geëvalueerd.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`Migratie voor de scheiding van hulpmodellen`},help:{"v1-vzdfqx-2t":`Legt vast dat oudere impliciete primaire modellen zijn behouden voordat de selectie van hulpmodellen werd gescheiden.`}},models:{label:{"v1-hzmwb-6":`Modellen`},help:{"v1-1h1niol-5q":`Hoofdsectie van de modelcatalogus voor providerdefinities, samenvoegings- en vervangingsgedrag en optionele integratie met Bedrock-detectie. Houd providerdefinities expliciet en valideer ze voordat u vertrouwt op failoverpaden in productie.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`Modelcatalogus vernieuwen`},help:{"v1-1hess4t-40":`Regelt achtergrondupdates van de meegeleverde modelcatalogus. Externe vermeldingen kunnen modelmetadata bijwerken, maar geen providerendpoints of headers wijzigen.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`Vernieuwing van modelcatalogus ingeschakeld`},help:{"v1-1fogpjj-3j":`Haal updates van de gehoste modelcatalogus op de achtergrond op (standaard: true). Stel in op false om al het externe verkeer voor de modelcatalogus uit te schakelen.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`URL voor vernieuwing van modelcatalogus`},help:{"v1-e02ai2-44":`Overschrijf de URL van de gehoste modelcatalogus met die van een zelfgehoste HTTPS-mirror (HTTP op localhost is toegestaan voor tests). Wijzigingen worden van kracht nadat de Gateway opnieuw is gestart.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`Modelcatalogusmodus`},help:{"v1-1ofrnsp-es":`Regelt het gedrag van de providercatalogus: "merge" behoudt de ingebouwde providers en past uw aangepaste providers daaroverheen toe, terwijl "replace" uitsluitend uw geconfigureerde providers gebruikt. Bij "merge" blijven voor overeenkomende provider-ID's niet-lege baseUrl-waarden in models.json van de agent behouden, terwijl apiKey-waarden alleen behouden blijven als de provider niet door SecretRef wordt beheerd binnen de huidige configuratie-/authenticatieprofielcontext; door SecretRef beheerde providers vernieuwen apiKey op basis van de huidige bronmarkeringen, en voor contextWindow/maxTokens van overeenkomende modellen wordt de hoogste waarde van de expliciete en impliciete vermeldingen gebruikt.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`Modelproviders`},help:{"v1-1y5jg0v-8p":`Overzicht van providers met provider-ID's als sleutels, met verbindings- en authenticatie-instellingen en concrete modeldefinities. Ingebouwde providers kunnen worden aangepast met overlays op providerniveau; aangepaste providers moeten baseUrl en models bevatten. Gebruik stabiele providersleutels zodat verwijzingen vanuit agents en tools overdraagbaar blijven tussen omgevingen.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`Runtime van modelprovider`},help:{"v1-1luy4fb-5o":`Optioneel runtimebeleid op laag niveau voor agents van deze provider. Gebruik runtimebeleid per provider/model in plaats van een vast ingestelde runtime voor de hele agent; bij weglating of de standaardwaarde kiest OpenClaw de runtime voor de geselecteerde provider.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`Runtime-ID van modelprovider`},help:{"v1-1gusd9s-69":`ID van de agentruntime voor de provider: "openclaw", "auto", een geregistreerde plug-in-harness-ID zoals "codex", of een ondersteunde CLI-backendalias zoals "claude-cli". Bij weglating gebruikt OpenAI op het officiële eindpunt standaard de Codex-harness.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`API-adapter van modelprovider`},help:{"v1-16c28rb-57":`Selectie van de API-adapter voor de provider die de compatibiliteitsafhandeling van verzoeken en antwoorden bij modelaanroepen bepaalt. Gebruik de adapter die overeenkomt met het protocol van uw upstreamprovider om incompatibele functies te voorkomen.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`API-sleutel van modelprovider`},help:{"v1-1p84k96-54":`Inloggegeven voor de provider, gebruikt voor authenticatie met een API-sleutel wanneer de provider directe sleutelauthenticatie vereist. Gebruik vervanging via geheimen of omgevingsvariabelen en sla geen echte sleutels op in configuratiebestanden die in versiebeheer worden vastgelegd.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`Authenticatiemodus van modelprovider`},help:{"v1-1l1lwxr-5p":`Selecteert de authenticatiemethode van de provider: "api-key" voor authenticatie met een API-sleutel, "token" voor authenticatie met een bearer-token, "oauth" voor OAuth-inloggegevens en "aws-sdk" voor het bepalen van AWS-inloggegevens. Stem dit af op de vereisten van je provider.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`Authorization-header van modelprovider`},help:{"v1-1gn3lt3-59":`Bij true worden inloggegevens via de HTTP-header Authorization verzonden, ook als alternatieve authenticatie mogelijk is. Gebruik dit alleen wanneer je provider of proxy expliciet vereist dat Authorization wordt doorgestuurd.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`Basis-URL van modelprovider`},help:{"v1-1ku88v8-53":`Basis-URL voor het providereindpunt dat modelverzoeken voor deze providerconfiguratie afhandelt. Gebruik HTTPS-eindpunten en houd URL's waar nodig omgevingsspecifiek met configuratiesjablonen.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`Headers van modelprovider`},help:{"v1-chg59u-4x":`Statische HTTP-headers die aan providerverzoeken worden toegevoegd voor tenantroutering, proxyauthenticatie of aangepaste gatewayvereisten. Gebruik dit spaarzaam en bewaar gevoelige headerwaarden in secrets.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`num_ctx invoegen voor modelprovider (OpenAI-compatibel)`},help:{"v1-53rmcr-6n":"Bepaalt of OpenClaw `options.num_ctx` invoegt voor Ollama-providers die zijn geconfigureerd met de OpenAI-compatibele adapter (`openai-completions`). De standaardwaarde is true. Stel dit alleen in op false als je proxy of upstream onbekende `options`-velden in de payload weigert."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`Lokale service van modelprovider`},help:{"v1-19zkcow-4y":`Optioneel lokaal modelserverproces dat op aanvraag wordt gestart voor deze provider. OpenClaw controleert healthUrl, start de opdracht wanneer nodig, wacht tot de server gereed is en verstuurt vervolgens het modelverzoek.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`Argumenten voor de lokale service van de modelprovider`},help:{"v1-t12wib-27":`Argumentenlijst die zonder shellexpansie aan de opdracht voor de lokale modelserver wordt doorgegeven.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`Opdracht voor de lokale service van de modelprovider`},help:{"v1-1x6hz64-4j":`Absoluut pad naar het uitvoerbare bestand voor het lokale modelserverproces. Geef dit pad expliciet op, zodat het opstarten van de provider deterministisch is en niet afhankelijk is van zoeken via PATH in de shell.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`Werkmap voor de lokale service van de modelprovider`},help:{"v1-fi3xlx-1h":`Werkmap voor het lokale modelserverproces.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`Omgeving voor de lokale service van de modelprovider`},help:{"v1-1lwb9k1-3k":`Aanvullende omgevingsvariabelen voor het lokale modelserverproces. Waarden die geheim lijken, worden afgeschermd in configuratiemomentopnamen.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`URL voor statuscontrole van de lokale service van de modelprovider`},help:{"v1-jv7aw-35":`URL waarmee vóór modelverzoeken wordt gecontroleerd of de server gereed is. Indien weggelaten, gebruikt OpenClaw de baseUrl van de provider met /models eraan toegevoegd.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`Stoppen bij inactiviteit van de lokale service van de modelprovider`},help:{"v1-1efg054-3z":`Aantal milliseconden dat een door OpenClaw gestarte lokale modelserver actief blijft nadat het laatste verzoek is voltooid. Stel in op 0 om de server actief te houden totdat OpenClaw wordt afgesloten.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`Time-out voor gereedheid van lokale service van modelprovider`},help:{"v1-4gp0f0-2r":`Maximale wachttijd in milliseconden voor de gereedheidscontrole van de lokale modelserver na het starten van het proces.`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`Maximumaantal tokens van modelprovider`},help:{"v1-fnj50y-38":`Standaard maximumbudget voor uitvoertokens dat wordt toegepast op modellen van deze provider wanneer maxTokens niet is ingesteld voor een model.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`Modellijst van modelprovider`},help:{"v1-1vbm0gt-63":`Opgegeven modellijst voor een provider, inclusief identificatoren, metadata, providerspecifieke parameters en optionele aanwijzingen voor compatibiliteit en kosten. Zorg dat de ID's exact overeenkomen met de waarden in de catalogus van de provider, zodat selectie en terugval correct werken.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`Modelruntime`},help:{"v1-1k70g2n-3g":`Optioneel beleid op laag niveau voor de agentruntime van dit specifieke model. Het runtimebeleid van het model heeft voorrang op het runtimebeleid van de provider.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`Modelruntime-ID`},help:{"v1-1llzv33-42":`ID van de agentruntime van het model: "openclaw", "auto", een geregistreerde plug-inharnas-ID zoals "codex", of een ondersteunde CLI-backendalias zoals "claude-cli".`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`Media-invoer voor model`},help:{"v1-wxtj8e-2x":`Optionele metadata over de mediamogelijkheden van het model die tools gebruiken om behoudende standaardinstellingen voor beeldcompressie te kiezen.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`Afbeeldingsinvoer voor model`},help:{"v1-1nviirq-3c":`Optionele limieten voor afbeeldingsinvoer voor dit model, zoals de maximale zijlengte, het maximale aantal pixels en de gewenste zijlengte voor compressie.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`Maximaal aantal bytes per afbeelding voor model`},help:{"v1-c2469j-23":`Maximale grootte van gecodeerde afbeeldingsgegevens die de provider voor dit model accepteert.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`Maximaal aantal pixels per afbeelding voor model`},help:{"v1-9d6yqp-1u":`Maximaal aantal pixels per afbeelding dat de provider voor dit model accepteert.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`Maximale zijlengte van afbeelding voor model`},help:{"v1-1gbci08-1y":`Maximale breedte of hoogte van een afbeelding die de provider voor dit model accepteert.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`Gewenste zijlengte van afbeelding voor model`},help:{"v1-1u1mpcg-2x":`Gewenste zijlengte bij het schalen van afbeeldingen voor evenwichtige compressie. Laat deze optie oningesteld om de behoudende standaardinstelling van OpenClaw te gebruiken.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`Modus voor afbeeldingstokens van het model`},help:{"v1-1oy6z7v-1z":`Berekeningswijze voor afbeeldingstokens van de provider: "tile", "detail" of "provider".`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`Runtimeparameters van de modelprovider`},help:{"v1-464sgu-4t":`Providerspecifieke runtimeparameters die door providerplug-ins worden geïnterpreteerd. Gebruik alleen sleutels die door de provider zijn gedocumenteerd en geef de voorkeur aan expliciete providerdocumentatie boven ad-hocaannames die voor meerdere providers worden gebruikt.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`Regio van de modelprovider`},help:{"v1-yq7rxk-5h":`Optionele implementatie-/API-regio van de provider, geïnterpreteerd door providers die regionale eindpunten aanbieden. Raadpleeg de providerdocumentatie voor ondersteunde waarden; overschrijvingen via baseUrl hebben doorgaans voorrang wanneer beide zijn ingesteld.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`Aanvraagoverschrijvingen voor de modelprovider`},help:{"v1-1lkxryk-87":`Optionele overschrijvingen voor aanvragen aan modelproviders, waaronder extra headers, authenticatieoverschrijvingen, proxyroutering, TLS-clientinstellingen en optioneel allowPrivateNetwork voor vertrouwde, zelfgehoste eindpunten. Gebruik deze alleen als uw upstreamverbinding of bedrijfsnetwerkroute aanpassingen aan het transport vereist.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`Privénetwerk toestaan voor aanvragen aan de modelprovider`},help:{"v1-1nbtcjk-fo":`Sta bij true HTTP-verzoeken van modelproviders naar privé-, CGNAT- of vergelijkbare adresbereiken toe via de HTTP-fetchbeveiliging van de provider (fetchWithSsrFGuard). Aangepaste/lokale basis-URL's van providers vertrouwen de exact geconfigureerde oorsprong al, behalve oorsprongen voor metadata, link-local en NAT64 voor lokaal gebruik (64:ff9b:1::/48); stel dit in op false om dat vertrouwen uit te schakelen. OpenAI Responses WebSocket hergebruikt request voor headers/TLS, maar gebruikt dat SSRF-fetchpad niet. Gebruik true alleen voor zelfgehoste eindpunten onder beheer van de operator die privé-oorsprongen buiten de geconfigureerde baseUrl-oorsprong moeten bereiken.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`Authenticatie voor modelproviderverzoeken overschrijven`},help:{"v1-ucdgnf-1w":`Overschrijf het authenticatiegedrag voor verzoeken aan deze provider.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`Naam van authenticatieheader voor modelproviderverzoeken`},help:{"v1-1881nqr-1i":`Aangepaste naam van de authenticatieheader die wordt gebruikt wanneer de authenticatiemodus header is.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`Authenticatiemodus voor modelproviderverzoeken`},help:{"v1-1lhv8hs-24":`Modus voor het overschrijven van authenticatie: "provider-default", "authorization-bearer" of "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`Voorvoegsel van authenticatieheader voor modelproviderverzoeken`},help:{"v1-1rbm9lz-21":`Optioneel voorvoegsel dat vóór request.auth.value wordt geplaatst wanneer de authenticatiemodus header is.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`Bearer-token voor modelproviderverzoeken`},help:{"v1-6rcasw-1l":`Bearer-token dat wordt gebruikt wanneer de authenticatiemodus authorization-bearer is.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`Waarde van de authenticatieheader voor modelproviderverzoeken`},help:{"v1-1v69ej-1j":`Aangepaste authenticatieheaderwaarde die wordt gebruikt wanneer de authenticatiemodus header is.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`Headers voor modelproviderverzoeken`},help:{"v1-zj3orj-2i":`Extra headers die aan providerverzoeken worden toegevoegd nadat de standaardattributie en authenticatie zijn bepaald.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`Proxy voor modelproviderverzoeken`},help:{"v1-md5uj8-4j":`Optionele afwijkende proxyinstelling voor modelproviderverzoeken. Gebruik "env-proxy" om de proxyinstellingen van de omgeving te volgen of "explicit-proxy" om verzoeken via een specifieke proxy-URL te routeren.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`Proxymodus voor modelproviderverzoeken`},help:{"v1-1dx0ozg-29":`Modus voor afwijkende proxyinstellingen voor modelproviderverzoeken: "env-proxy" of "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`TLS voor de proxy voor modelproviderverzoeken`},help:{"v1-rdx62w-1v":`Optionele TLS-instellingen die worden gebruikt bij het verbinden met de geconfigureerde proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`TLS-CA voor de proxy voor modelproviderverzoeken`},help:{"v1-11pg2fd-1s":`Aangepaste CA-bundel die wordt gebruikt om de TLS-certificaatketen van de proxy te verifiëren.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`TLS-certificaat voor de proxy voor modelproviderverzoeken`},help:{"v1-x8nk2q-22":`TLS-clientcertificaat dat aan de proxy wordt aangeboden wanneer wederzijdse TLS vereist is.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`TLS-verificatie overslaan voor de proxy voor modelproviderverzoeken`},help:{"v1-12vjdm9-2j":`Slaat de verificatie van het TLS-certificaat van de proxy over. Gebruik dit alleen in gecontroleerde ontwikkelomgevingen.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`TLS-sleutel voor de proxy voor modelproviderverzoeken`},help:{"v1-1skyr56-1w":`Privésleutel die bij request.proxy.tls.cert hoort voor wederzijdse TLS met de proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`TLS-wachtwoordzin voor de proxy voor modelproviderverzoeken`},help:{"v1-wjvoxd-1m":`Optionele wachtwoordzin om request.proxy.tls.key te ontsleutelen.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`TLS-servernaam voor de proxy voor modelproviderverzoeken`},help:{"v1-b4oabu-22":`Optionele vervangende SNI/servernaam die wordt gebruikt bij het opzetten van een TLS-verbinding met de proxy.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`Proxy-URL voor modelproviderverzoeken`},help:{"v1-kvbgou-48":`Expliciete proxy-URL die wordt gebruikt wanneer request.proxy.mode is ingesteld op explicit-proxy. Inloggegevens in de URL worden als gevoelig behandeld en in momentopnamen onleesbaar gemaakt.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`TLS voor modelproviderverzoeken`},help:{"v1-16u7v7h-2b":`Optionele TLS-instellingen voor rechtstreekse verbindingen met het upstream-modeleindpunt.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`TLS-CA voor aanvragen aan modelprovider`},help:{"v1-ny8y3e-1v":`Aangepaste CA-bundel voor het verifiëren van de upstream-TLS-certificaatketen.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`TLS-certificaat voor aanvragen aan modelprovider`},help:{"v1-1lltmhw-2e":`TLS-clientcertificaat dat aan het upstream-eindpunt wordt aangeboden wanneer wederzijdse TLS vereist is.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`TLS-verificatie overslaan voor aanvragen aan modelprovider`},help:{"v1-1006cuy-2m":`Slaat de verificatie van het upstream-TLS-certificaat over. Gebruik dit alleen in gecontroleerde ontwikkelomgevingen.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`TLS-sleutel voor aanvragen aan modelprovider`},help:{"v1-w2agir-1t":`Privésleutel die bij request.tls.cert hoort voor wederzijdse TLS met de upstream.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`TLS-wachtwoordzin voor aanvragen aan modelprovider`},help:{"v1-10ds42f-1g":`Optionele wachtwoordzin voor het ontsleutelen van request.tls.key.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`TLS-servernaam voor aanvragen aan modelprovider`},help:{"v1-18yt7x9-1y":`Optionele vervanging van de SNI/servernaam bij het opzetten van een upstream-TLS-verbinding.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`Time-out voor aanvragen aan modelprovider`},help:{"v1-t3yn8l-ih":`Optionele time-out in seconden voor modelverzoeken per provider. Verzoekinstellingen op providerniveau hebben invloed op expliciete modelvermeldingen van de provider; ze maken geen impliciete modellen aan. Stel deze waarde voor aangepaste providers in naast baseUrl en models van de provider. Dit geldt voor HTTP-verzoeken van de provider, inclusief het verbinden, headers, de body en het afbreken van het volledige verzoek. Ook wordt de bovengrens van de LLM-watchdog voor inactiviteit en streaming voor deze provider verhoogd tot boven de impliciete standaardwaarde van circa 120 seconden. Gebruik dit voor trage lokale of zelfgehoste modelservers, of voor cloudproviders die redeneringstokens bufferen zonder tussentijds gegevens te verzenden (Gemini preview, Claude/Opus met grote toolpayloads), in plaats van de algemene time-outs voor agents te wijzigen.`}},nodeHost:{label:{"v1-nb8lk1-9":`Nodehost`},help:{"v1-8recuz-4z":`Instellingen van de nodehost voor functies die vanuit deze gatewaynode beschikbaar worden gesteld aan andere nodes of clients. Behoud de standaardinstellingen, tenzij u bewust lokale mogelijkheden via een proxy binnen uw nodenetwerk beschikbaar wilt stellen.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`Agentuitvoeringen op de node`},help:{"v1-4uz5ur-2k":`Schakel native agentbeurten die goedkeuring vereisen in op deze nodehost zonder grafische interface. Standaard uitgeschakeld.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`Claude-agentuitvoeringen op de node`},help:{"v1-g8az5y-2l":`Bepaalt of deze nodehost zonder grafische interface Claude CLI-agentbeurten als beschikbaar mag aanmelden bij de gateway.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`Claude-agentuitvoeringen op de node ingeschakeld`},help:{"v1-1ke804l-44":`Meld de mogelijkheid om Claude-sessies op gekoppelde nodes voort te zetten als beschikbaar aan wanneer het lokale uitvoerbare bestand claude beschikbaar is (standaard: false). Uitvoeringen vereisen nog steeds goedkeuring voor het uitvoeren van opdrachten op de node.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`Automatische node-updates`},help:{"v1-16xjk4e-5n":`Bepaalt of de afzonderlijke runtime voor verpakte headless node-hosts automatisch wordt bijgewerkt. Controleert elk uur en wacht tot al het node-werk is voltooid voordat opnieuw wordt opgestart; automatische herstarts vinden met tussenpozen van minimaal 12 uur plaats.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`Automatische node-updates ingeschakeld`},help:{"v1-1sa0yeg-7w":`Schakel automatische stable- of beta-updates in voor langdurig actieve, verpakte headless nodes (standaard: true). Stel in op false om dit uit te schakelen. Wordt ook uitgeschakeld door update.checkOnStart=false of OPENCLAW_NO_AUTO_UPDATE=1; bij broncode-checkouts, native apps, private workers, dev en extended-stable worden updates niet automatisch toegepast.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`Browserproxy van de node`},help:{"v1-2xrew7-4f":`Groepeert browserproxy-instellingen om lokale browserbesturing via noderoutering beschikbaar te maken. Schakel dit alleen in als workflows op externe nodes je lokale browserprofielen nodig hebben.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`Toegestane profielen voor de nodebrowserproxy`},help:{"v1-1ew5dkm-8b":`Optionele lijst met toegestane browserprofielnamen die via nodeproxyroutering beschikbaar worden gemaakt. Laat deze leeg om de standaardtoegang tot alle profielfuncties te behouden, inclusief routes voor het aanmaken en verwijderen van profielen. Als deze lijst is ingesteld, beperkt OpenClaw de profieltoegang tot de minimaal benodigde rechten en blokkeert het het aanmaken en verwijderen van persistente profielen via de proxy.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`Nodebrowserproxy ingeschakeld`},help:{"v1-pa04pd-5b":`Maak de lokale browserbesturingsserver beschikbaar via nodeproxyroutering, zodat externe clients de browserfuncties van deze host kunnen gebruiken. Laat dit uitgeschakeld, tenzij externe automatisering er expliciet van afhankelijk is.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`MCP voor de nodehost`},help:{"v1-1mdhrwl-48":`Gebruik MCP-servers die door de headless nodehost zijn gestart en aan de gekoppelde gateway beschikbaar zijn gesteld als agenttools. Start de nodehost opnieuw nadat je deze sectie hebt gewijzigd.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`MCP-servers van de nodehost`},help:{"v1-19m002f-3x":`Benoemde MCP-serverdefinities die lokaal op deze node staan. Gebruikt dezelfde serverstructuur als mcp.servers; OAuth-servers worden niet ondersteund door de nodehost.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`Skills van de nodehost`},help:{"v1-v8txza-41":`Gebruik deze sectie om skills die in ~/.openclaw/skills zijn geïnstalleerd vanuit de headless nodehost beschikbaar te stellen. Start de nodehost opnieuw nadat je skillbestanden hebt gewijzigd.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`Skills van de nodehost ingeschakeld`},help:{"v1-1ggpkqb-36":`Scan en publiceer skills die op het knooppunt worden gehost na het verbinden (standaard: true). Stel in op false om het publiceren van skills door het knooppunt uit te schakelen.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`Worker-uitvoeringen op het knooppunt`},help:{"v1-1w83rox-2p":`Schakel volledige hosting van OpenClaw-workersessies in vanuit bundels die door de Gateway worden beheerd. Standaard uitgeschakeld.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`Capaciteit voor worker-uitvoeringen op het knooppunt`},help:{"v1-10nvk8f-3w":`Maximumaantal gelijktijdige workersessies dat door dit knooppunt wordt gehost (standaard: het aantal beschikbare CPU-kernen). Moet een geheel getal van 1 tot en met 1024 zijn.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`Containerimage voor worker-uitvoeringen op het knooppunt`},help:{"v1-1oqx50o-5t":`Optionele Node 24.16+- of 26.1+-image voor workers die in containers zijn geïsoleerd (standaard: "node:24.19.0-slim"). Gebruik zo nodig een image die op een digest is vastgezet, uit een privéregister komt of vooraf is geladen; ontbrekende images worden bij het eerste gebruik opgehaald.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`Worker-uitvoeringen op het knooppunt ingeschakeld`},help:{"v1-b3t0xp-2t":`Sta dit gekoppelde knooppunt toe sessies te hosten vanuit exact de bundels die door zijn Gateway zijn geïnstalleerd (standaard: false).`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`Isolatie van worker-uitvoeringen op het knooppunt`},help:{"v1-19i6swo-58":`Selecteer de procesgrens voor workersessies: "none" voert ze rechtstreeks op de knooppunthost uit (standaard); "container" vereist een werkende Docker-compatibele engine en valt nooit terug op uitvoering op de host.`}},plugins:{label:{"v1-10renyj-7":`Plug-ins`},help:{"v1-1qbev2k-5c":`Instellingen voor het pluginsysteem om extensies in te schakelen, het laadbereik te beperken, vermeldingen te configureren en installaties bij te houden. Houd het pluginbeleid in productieomgevingen expliciet en beperk de rechten tot het strikt noodzakelijke.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`Lijst met toegestane plug-ins`},help:{"v1-pupwbe-7z":`Optionele lijst met toegestane plug-in-ID's; als deze is ingesteld, kunnen alleen vermelde plug-ins worden geladen. Geconfigureerde meegeleverde chatkanalen kunnen hun meegeleverde plug-in nog steeds activeren wanneer het kanaal expliciet is ingeschakeld in de configuratie. Gebruik dit om in gecontroleerde omgevingen af te dwingen dat alleen goedgekeurde extensies worden gebruikt.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`Lijst met geblokkeerde plug-ins`},help:{"v1-4gyt4z-4i":`Optionele lijst met plug-in-ID's die worden geblokkeerd, ook als ze in lijsten met toegestane plug-ins of paden zijn opgenomen. Gebruik blokkeerregels om wijzigingen in noodgevallen terug te draaien en risicovolle plug-ins onvoorwaardelijk te blokkeren.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`Plug-ins inschakelen`},help:{"v1-pnygd7-50":`Schakel het laden van plug-ins/extensies globaal in of uit tijdens het opstarten en het opnieuw laden van de configuratie (standaard: true). Laat dit alleen ingeschakeld als uw implementatie extensiefuncties nodig heeft.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`Plug-invermeldingen`},help:{"v1-cn74rf-54":`Instellingen per plug-in, met de plug-in-ID als sleutel, waaronder de inschakelstatus en plug-inspecifieke runtimeconfiguratiegegevens. Gebruik dit om afzonderlijke plug-ins af te stemmen zonder het globale laadbeleid te wijzigen.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`API-sleutel voor plug-in`},help:{"v1-ctytg2-53":`Optioneel API-sleutelveld dat wordt gebruikt door plug-ins die directe sleutelconfiguratie in hun vermeldingsinstellingen accepteren. Gebruik substitutie via geheimen of omgevingsvariabelen en sla geen echte inloggegevens op in configuratiebestanden in versiebeheer.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`Plug-inconfiguratie`},help:{"v1-1he672p-51":`Door de plug-in gedefinieerde configuratiegegevens die worden geïnterpreteerd volgens het eigen schema en de validatieregels van die plug-in. Gebruik alleen gedocumenteerde velden van de plug-in om genegeerde of ongeldige instellingen te voorkomen.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`Plugin ingeschakeld`},help:{"v1-12soc0h-9a":`Overschrijft voor een specifieke plugin de inschakelinstelling uit het algemene pluginbeleid. In de standaard hybride herlaadmodus worden wijzigingen direct in de pluginruntime geladen voor nieuwe agentbeurten, zonder de Gateway opnieuw te starten, tenzij de plugin voor dit pad een herstart vereist. Gebruik dit om plugins geleidelijk uit te rollen in verschillende omgevingen.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`Omgevingsvariabelen voor plugin`},help:{"v1-p39pu4-52":`Toewijzing van omgevingsvariabelen per plugin die alleen in de runtimecontext van die plugin worden geïnjecteerd. Gebruik dit om inloggegevens voor een provider tot één plugin te beperken, in plaats van de algemene procesomgeving te delen.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`Hookbeleid voor plugin`},help:{"v1-1oslnrf-4c":`Beleidsinstellingen per plugin voor getypeerde hooks, met veiligheidscontroles die door de kern worden afgedwongen. Gebruik dit om hookcategorieën met grote impact te beperken zonder de hele plugin uit te schakelen.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`Hooks voor gesprekstoegang toestaan`},help:{"v1-xqz31z-7e":"Bepaalt of deze plugin onbewerkte gespreksinhoud mag lezen via getypeerde hooks zoals `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize` en `agent_end`. Voor niet-meegeleverde plugins moet dit expliciet worden ingeschakeld."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptInjection":{label:{"v1-1p7f9k9-s":`Hooks voor promptinjectie toestaan`},help:{"v1-7y6cny-32":"Bepaalt of deze plugin prompts mag wijzigen via getypeerde hooks. Stel in op false om `before_prompt_build` te blokkeren."}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`Time-out voor pluginhooks (ms)`},help:{"v1-4ra6b7-74":`Standaardtime-out in milliseconden voor de getypeerde hooks van deze plugin, met een maximum van 600000. Als deze niet is ingesteld, gebruikt elke hook de door de plugin opgegeven time-out of het beleid per hook van de Gateway; er is geen vaste standaardwaarde. Waarden per hook in hooks.timeouts hebben voorrang.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`Afwijkende time-outs voor pluginhooks`},help:{"v1-yphl9b-5s":`Afwijkende time-outs per hook in milliseconden, met de naam van de getypeerde hook als sleutel en een maximum van 600000. Gebruik gerichte afwijkingen voor bekende trage hooks zoals before_prompt_build of agent_end in plaats van de time-out voor elke hook te verhogen.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`LLM-beleid voor plugins`},help:{"v1-dlca6c-4j":`Instellingen per plugin voor api.runtime.llm.complete die bepalen of de plugin het model en de agent mag wijzigen. Laat dit oningesteld, tenzij een plugin expliciet door de host beheerde aanvullingsaanroepen moet aansturen.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`LLM-agentwijziging door plugin toestaan`},help:{"v1-k8c08b-4n":`Staat deze plugin expliciet toe om api.runtime.llm.complete aan te roepen met een andere agent-id dan de standaardwaarde. Laat dit op false staan, tenzij de plugin wordt vertrouwd voor modeltoegang via andere agents.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`Wijziging van LLM-authenticatieprofiel door plugin toestaan`},help:{"v1-9ityw9-4x":`Staat deze plugin toe om een ander authenticatieprofiel dan het standaardprofiel te selecteren voor aanvullingen in een geïsoleerde agentruntime. Laat dit op false staan, tenzij de plugin wordt vertrouwd voor expliciete, geïsoleerde routering van inloggegevens.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`Toegestane LLM-aanvullingsmodellen voor plugin`},help:{"v1-1ul08he-54":`Toegestane doelen voor elke LLM-aanvulling van een plugin als canonieke "provider/model"-verwijzingen, inclusief door de host bepaalde standaardwaarden en overschrijvingen. Gebruik "*" alleen als u bewust elk model wilt toestaan.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`Toegestane LLM-modellen voor plugins`},help:{"v1-154sk45-47":`Toegestane alternatieve modellen voor LLM-aanroepen van vertrouwde plugins als canonieke "provider/model"-verwijzingen. Gebruik "*" alleen als u bewust elke modeloverschrijving wilt toestaan.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`LLM-modeloverschrijving door plugin toestaan`},help:{"v1-uw4jmc-47":`Staat deze plugin expliciet toe om modeloverschrijvingen aan te vragen in api.runtime.llm.complete. Laat dit op false staan, tenzij de plugin vertrouwd wordt om de modelselectie te sturen.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`Subagentbeleid voor plugins`},help:{"v1-wbf4m1-4d":`Runtime-instellingen voor subagents per plugin, voor het vertrouwen in modeloverschrijvingen en lijsten met toegestane modellen. Laat dit oningesteld, tenzij een plugin de modelselectie voor subagents expliciet moet sturen.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`Toegestane subagentmodellen voor plugins`},help:{"v1-2pvkow-42":`Toegestane alternatieve modellen voor subagentuitvoeringen van vertrouwde plugins als canonieke "provider/model"-verwijzingen. Gebruik "*" alleen als u bewust elk model wilt toestaan.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`Subagentmodeloverschrijving door plugin toestaan`},help:{"v1-1r5tzm1-4g":`Staat deze plugin expliciet toe om afwijkende providers of modellen aan te vragen bij subagent-uitvoeringen op de achtergrond. Laat dit op false staan, tenzij de plugin vertrouwd wordt om de modelselectie te sturen.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`Pluginlader`},help:{"v1-1myjwbi-52":`Configuratiegroep voor de pluginlader om bestandssysteempaden op te geven waar plugins worden gezocht. Houd laadpaden expliciet en gecontroleerd om te voorkomen dat onbedoeld niet-vertrouwde extensies worden geladen.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`Laadpaden voor plugins`},help:{"v1-o689p1-4z":`Aanvullende pluginbestanden of -mappen die de lader naast de ingebouwde standaardlocaties scant. Gebruik speciale extensiemappen en vermijd brede paden met niet-gerelateerde uitvoerbare inhoud.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`Pluginslots`},help:{"v1-zx6crl-5f":`Selecteert welke plugins exclusieve runtimeslots, zoals geheugen, beheren, zodat slechts één plugin die functionaliteit biedt. Wijs het beheer van slots expliciet toe om overlappende providers met conflicterend gedrag te voorkomen.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-1371nb9-l":`Contextengine-plugin`},help:{"v1-4v13iw-2t":`Selecteert de actieve contextengine-plugin op basis van de id, zodat één plugin de contextorkestratie verzorgt.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`Geheugenplugin`},help:{"v1-80ngcl-23":`Selecteer de actieve geheugenplugin op basis van de id, of "none" om geheugenplugins uit te schakelen.`}},presence:{label:{"v1-10fdwo4-8":`Aanwezigheid`}},proxy:{label:{"v1-ji57pa-d":`Beheerde proxy`},help:{"v1-vui6bx-58":`Door de beheerder beheerde routering via een forwardproxy voor HTTP, HTTPS, WebSocket en ondersteunde paden voor onbewerkt uitgaand verkeer tijdens de uitvoering van OpenClaw. Gebruik dit wanneer centrale controle over uitgaand verkeer deel uitmaakt van de grenzen van de implementatie.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`Beheerde proxy ingeschakeld`},help:{"v1-1456xdw-49":`Expliciete instelling voor de beheerde proxy. De aanwezigheid van een URL schakelt routering standaard in; stel in op false om proxy-URL's uit de configuratie of omgeving te negeren zonder ze te verwijderen.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`Loopbackmodus voor beheerde proxy`},help:{"v1-1kaiuh0-3c":`Bepaalt de routering van het besturingsverkeer via loopback voor de Gateway terwijl de beheerde-proxymodus actief is: "gateway-only", "proxy" of "block".`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`URL van beheerde proxy`},help:{"v1-p36b5l-3v":`URL van de beheerde forwardproxy. Gebruik http:// voor een gewone CONNECT-proxy of https:// wanneer de verbinding met het proxy-eindpunt zelf TLS moet gebruiken.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`TLS voor beheerde proxy`},help:{"v1-6i0vu-3q":`TLS-instellingen die worden gebruikt bij het verbinden met het beheerde proxy-eindpunt. Deze instellingen gelden voor TLS van de proxy, niet voor TLS van de bestemming na CONNECT.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`TLS-CA-bestand voor beheerde proxy`},help:{"v1-1ntzjia-2p":`Pad in het bestandssysteem naar een aangepaste CA-bundel die wordt gebruikt om het certificaat van een beheerd HTTPS-proxy-eindpunt te verifiëren.`}},secrets:{label:{"v1-1sihgpy-7":`Geheimen`},help:{"v1-jgn0o9-2l":`Providers voor verwijzingen naar geheimen, gedrag van de gedeelde opslag en optionele bescherming voor uitgaand verkeer van subprocessen.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`Uitgaande proxy voor geheimen`},help:{"v1-1qfgid-4n":`Loopbackproxy in beheer van de Gateway die markeringen voor geheimen in de gedeelde opslag pas vervangt wanneer een uitgaand verzoek wordt verstuurd. Start de Gateway opnieuw nadat u deze sectie hebt gewijzigd; deze wordt alleen bij het opstarten ingelezen.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`Toegestane hosts voor uitgaande proxy voor geheimen`},help:{"v1-9ypodl-6t":`Optionele toelatingslijst voor verkeer van verzoeken en CONNECT-tunnels. Indien aanwezig moeten bestemmingen in deze lijst, in een hostbinding per geheim of in bypassHosts staan. Een lege lijst staat alleen gebonden hosts of hosts in bypassHosts toe. Start de Gateway opnieuw nadat u deze instelling hebt gewijzigd.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`Hosts die de uitgaande proxy voor geheimen omzeilen`},help:{"v1-1oiiomv-57":`Exacte hostnamen die geauthenticeerde blinde CONNECT-tunnels gebruiken voor clients met certificaatpinning. Sentinelwaarden blijven versleuteld en zullen de authenticatie bij de leverancier niet doorstaan, in plaats van onversleutelde tekst bloot te geven.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`Uitgaande proxy voor geheimen ingeschakeld`},help:{"v1-u99b1i-2h":`Schakelt vervanging van geheimen in uitgaand verkeer in voor agentsubprocessen die door de Gateway worden gehost. Standaard: false.`}},session:{label:{"v1-8yh9jr-7":`Sessie`},help:{"v1-j86s32-5d":`Algemene instellingen voor sessieroutering, opnieuw instellen, afleverbeleid en onderhoud van de gespreksgeschiedenis. Behoud de standaardinstellingen, tenzij u strengere eisen voor isolatie, bewaring of aflevering nodig hebt.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`Bereik van DM-sessies`},help:{"v1-ql362c-5l":`Bereik van DM-sessies: "main" behoudt de continuïteit, terwijl "per-peer", "per-channel-peer" en "per-account-channel-peer" de isolatie vergroten. Gebruik geïsoleerde modi voor gedeelde inboxen of implementaties met meerdere accounts.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`Bereik van groepssessies`},help:{"v1-1fdezx2-6i":`Bereik van groeps-/kanaalsessies: "per-group" houdt chatruimten gescheiden terwijl de hoofdsessie van de agent ze op de achtergrond volgt, onafhankelijk van dmScope; "main" voegt de context van chatruimten samen in main en vereist geen monitoring. Gebruik "main" alleen voor vertrouwde chatruimten.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`Identiteitskoppelingen voor sessies`},help:{"v1-1y5jnsm-5n":`Koppelt canonieke identiteiten aan peer-ID's met een providerprefix, zodat dezelfde gebruikers in één DM-gesprek terechtkomen (voorbeeld: telegram:123456). Gebruik dit wanneer dezelfde persoon via meerdere kanalen of accounts verschijnt.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`Hoofdsleutel voor sessies`},help:{"v1-18p638h-3q":`Geaccepteerd maar genegeerd: het achtervoegsel van de hoofdsessie per agent is altijd "main". Laat dit veld weg; het globale sessiebereik gebruikt in plaats daarvan "global".`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`Sessieonderhoud`},help:{"v1-imr441-66":`Instellingen voor automatisch onderhoud van de sessieopslag: dashboardarchivering, ouderdomsgrens voor verwijdering, maximumaantal items, bewaartermijn van resetarchieven en opschonen op basis van het schijfquotum. Begin in de modus warn om de impact te bekijken en schakel vervolgens over op enforce zodra de drempelwaarden zijn afgestemd.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`Inactieve dashboardsessies archiveren na`},help:{"v1-1frdtub-5n":"Archiveert inactieve dashboardsessies na deze tijdsduur (bijvoorbeeld `7d`), zodat ze beschikbaar blijven zonder de lijst met actieve sessies te vullen. Stel `false` of `0` in om automatische dashboardarchivering uit te schakelen."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-353bpe-n":`Archiefopslag voor transcripten`},help:{"v1-1kp9s9h-5s":`Verplaatst inactieve transcripten naar gecomprimeerde JSONL-archieven met behoud van sessiemetadata. Archiefbestanden worden een vereist onderdeel van de geschiedenis en moeten in back-ups worden opgenomen. Wijzigingen worden toegepast zonder de Gateway opnieuw te starten.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`Archiveren na aantal inactieve dagen`},help:{"v1-zay1q3-5b":`Archiveer transcripten na dit aantal inactieve dagen (positief geheel getal, standaard 30). Actief werk wordt beschermd; een gewijzigde drempel wordt van kracht bij de volgende verwerkingsronde, zonder de Gateway opnieuw te starten.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-85gcoy-11":`Oude transcripten automatisch archiveren`},help:{"v1-6p6vmb-5a":`Schakelt archivering van transcripten op de achtergrond in (standaard false). Een achtergrondproces controleert elke minuut of er transcripten zijn die in aanmerking komen. Dit expliciete archiveringsbeleid staat los van verwijdering en opschoning op basis van het schijfruimtebudget.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`Streefwaarde voor schijfgebruik door sessies`},help:{"v1-143vh09-7z":`Doelgrootte na opschoning op basis van het schijfquotum (bovengrens). Standaard 80% van maxDiskBytes; stel dit expliciet in om op schijven met beperkte ruimte meer ruimte vrij te maken. Een waarde die op nul uitkomt, valt terug op de standaardwaarde; negatieve waarden zijn ongeldig. Schakel het quotum in plaats daarvan uit met maxDiskBytes.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`Maximaal schijfquotum voor sessies`},help:{"v1-147lxk3-cj":'Budget voor fysieke schijfruimte per agent, inclusief SQLite-hoofd- en WAL-bestanden en meegetelde bestanden in de sessiemap (bijvoorbeeld `500mb`). Standaard `10gb`; door beschermde gegevens kan het gebruik boven de streefwaarde blijven. Bij overschrijding meldt de modus warn de schijfruimtedruk en verwijdert de modus enforce eerst oude bestanden van reset- en verwijderacties, vervolgens geschiedenis zonder verwijzingen en daarna archieven die door limietoverschrijding zijn aangemaakt. Handmatige archieven, archieven op basis van bewaartermijn, dashboardarchieven, herstelarchieven en oudere archieven blijven beschermd. Stel `false`, `0` of `"0"` in om dit uit te schakelen.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`Maximumaantal sessie-items`},help:{"v1-1w2egrh-7u":`Beperkt het aantal niet-gearchiveerde sessie-items (standaard 5000). In aanmerking komende blijvende gesprekken boven de limiet worden samen met hun geschiedenis gearchiveerd; tijdelijke automatiseringsitems worden verwijderd. Bestaande archieven tellen niet mee voor de limiet. Beschermde actieve items tellen wel mee en kunnen ervoor zorgen dat de opslag boven de limiet blijft.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`Modus voor sessieonderhoud`},help:{"v1-bq39hk-6v":`Bepaalt of het beleid voor opschoning en schijfruimtebudgetten alleen wordt gerapporteerd ("warn") of actief wordt toegepast ("enforce"). Behoud "warn" tijdens de uitrol en schakel over naar "enforce" nadat veilige drempelwaarden zijn gevalideerd. Koude opslag heeft een eigen expliciete enabled-instelling.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`Recente sessies behouden`},help:{"v1-138q5wx-89":"Beschermt interactieve sessies die binnen deze periode actief waren (bijvoorbeeld `7d`) tegen automatische verwijdering van geschiedenis op basis van ouderdom, aantal en schijfruimtebudget. Als dit niet is ingesteld of op `false` staat, blijft het normale beleid gelden waarbij de oudste items eerst worden verwijderd. Synthetische rijen voor modeluitvoeringen, cron, hooks, heartbeats, ACP en subagenten blijven in aanmerking komen voor begrensde opschoning."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`Sessies opschonen na`},help:{"v1-1xn50w7-76":"Archiveert blijvende gesprekken die hiervoor in aanmerking komen en verwijdert tijdelijke automatiseringsitems die ouder zijn dan deze duur (standaard `30d`; bijvoorbeeld `12h`). Gearchiveerde gesprekken behouden hun geschiedenis en kunnen worden hersteld; beschermde of routeerbare gesprekken blijven actief."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`Bewaartermijn voor archieven na sessiereset`},help:{"v1-16amrs1-7r":"Leeftijdsafhankelijke bewaartermijn voor gearchiveerde transcripten (`*.reset.<timestamp>` en `*.deleted.<timestamp>`). Standaard blijven archieven bewaard totdat de limiet voor schijfruimte wordt bereikt en de oudste als eerste worden verwijderd; stel een duur in (bijvoorbeeld `30d`) om verwijdering op basis van verstreken tijd in te schakelen, of `false` om dit expliciet uit te schakelen."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`Home informeren bij het aanmaken van een sessie`},help:{"v1-c4prn5-8b":`Plaats bij het aanmaken van een sessie een systeemmelding in de wachtrij van de Home-sessie van de agent die de sessie beheert (standaard: true). Meldingen bevatten de beschikbare titel en metagegevens van de maker en worden gelezen tijdens de volgende Home-beurt of heartbeat. Stel in op false om dit uit te schakelen; concepten, incognitosessies, interne sessies en geplande cron-uitvoeringen zijn uitgesloten.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`Beleid voor sessieresets`},help:{"v1-1hmt7n3-6r":`Definieert het standaardobject voor resetbeleid dat wordt gebruikt wanneer er geen type- of kanaalspecifieke overschrijving van toepassing is. Standaard worden sessies niet automatisch gereset; gebruik dagelijkse of inactiviteitsschema's om dit in te schakelen. /new en /reset blijven op elk moment beschikbaar.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`Uur voor dagelijkse sessiereset`},help:{"v1-wry8cv-59":`Stelt het lokale uur (0-23) in voor de dagelijkse resetmodus, zodat sessies op voorspelbare tijdstippen opnieuw beginnen. Gebruik dit met mode=daily en stem het af op de verwachte tijdzone van de beheerder voor begrijpelijk gedrag.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`Minuten inactiviteit vóór sessiereset`},help:{"v1-1kzj0id-5e":`Stelt de inactiviteitsperiode vóór een reset in voor de inactiviteitsmodus en kan ook dienen als aanvullende beveiliging in de dagelijkse modus. Gebruik hogere waarden om de continuïteit te behouden of lagere waarden voor versere, kortdurende gespreksthreads.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`Modus voor sessieresets`},help:{"v1-e5ie4w-5b":`Selecteert de resetstrategie: "none" schakelt automatisch resetten uit (de standaardinstelling), "daily" reset op een ingesteld tijdstip en "idle" reset na inactiviteit. /new en /reset blijven in elke modus beschikbaar.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`Sessiereset per kanaal`},help:{"v1-1uxsulx-5h":`Biedt kanaalspecifieke resetinstellingen met de provider-/kanaal-id als sleutel voor nauwkeurige controle over het gedrag. Gebruik dit alleen wanneer één kanaal afwijkend resetgedrag nodig heeft dat niet door beleid op typeniveau wordt gedekt.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`Sessiereset per chattype`},help:{"v1-ypdr7u-52":`Overschrijft het resetgedrag per chattype (direct, group, thread) wanneer de standaardinstellingen niet volstaan. Gebruik dit wanneer groeps- of threadverkeer een andere resetfrequentie nodig heeft dan directe berichten.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`Sessiereset (direct)`},help:{"v1-fjnlp5-56":`Definieert het resetbeleid voor directe chats en overschrijft de basisconfiguratie session.reset voor dat type. Gebruik dit als de standaardmanier om instellingen voor directe berichten te overschrijven in plaats van de verouderde alias dm.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`Sessiereset (groep)`},help:{"v1-hl1200-4u":`Definieert het resetbeleid voor groepschatsessies waarin continuïteit en ruispatronen anders zijn dan bij directe berichten. Gebruik kortere inactiviteitsperioden voor drukke groepen als contextverschuiving een probleem wordt.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`Sessiereset (thread)`},help:{"v1-1hgpeke-4w":`Definieert het resetbeleid voor sessies die beperkt zijn tot een thread, inclusief gerichte workflows binnen kanaalthreads. Gebruik dit wanneer threadsessies sneller of langzamer moeten verlopen dan andere chattypen.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`Triggers voor het resetten van sessies`},help:{"v1-rcabsw-5a":`Definieert berichttriggers die een sessie geforceerd resetten wanneer ze in binnenkomende inhoud worden aangetroffen. Gebruik deze spaarzaam voor expliciete resetzinnen, zodat de context niet onverwacht verloren gaat tijdens een normaal gesprek.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`Sessiebereik`},help:{"v1-axt4ds-5z":`Stelt de basisstrategie voor sessiegroepering in: "per-sender" houdt sessies per afzender gescheiden en "global" deelt één sessie per kanaalcontext. Behoud "per-sender" voor veiliger gebruik met meerdere gebruikers, tenzij gedeelde context bewust vereist is.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`Verzendbeleid voor sessies`},help:{"v1-17qpipb-5l":`Beheert verzendrechten tussen sessies met allow/deny-regels die worden getoetst aan channel, chatType en sleutelprefixen. Gebruik dit om in complexe omgevingen te beperken waar sessietools berichten kunnen afleveren.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`Standaardactie voor het verzendbeleid voor sessies`},help:{"v1-15plhut-53":`Stelt de terugvalactie in wanneer geen sendPolicy-regel overeenkomt: "allow" of "deny". Behoud "allow" voor eenvoudigere configuraties of kies "deny" als u voor elke bestemming expliciete allow-regels vereist.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`Regels voor het verzendbeleid voor sessies`},help:{"v1-o217za-5h":'Geordende allow/deny-regels die vóór de standaardactie worden geëvalueerd, bijvoorbeeld `{ action: "deny", match: { channel: "discord" } }`. Zet de meest specifieke regels bovenaan, zodat brede regels uitzonderingen niet overschaduwen.'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`Actie voor de verzendregel voor sessies`},help:{"v1-178vm80-54":`Bepaalt de regelbeslissing als "allow" of "deny" wanneer aan de bijbehorende voorwaarden wordt voldaan. Plaats weigeringsregels eerst wanneer u strikte grenzen afdwingt met expliciete uitzonderingen die toegang toestaan.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`Voorwaarden voor sessieverzendregel`},help:{"v1-18qh5qg-5d":`Definieert optionele voorwaarden voor de regel die beperkingen op channel, chatType en sleutelprefixen kunnen combineren. Houd de voorwaarden specifiek, zodat de bedoeling van het beleid leesbaar blijft en foutopsporing eenvoudig blijft.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`Kanaal voor sessieverzendregel`},help:{"v1-u5erwx-50":`Past de regel toe op een specifieke kanaal- of provider-ID (bijvoorbeeld discord, telegram, slack). Gebruik dit wanneer één kanaal bezorging onafhankelijk van andere kanalen moet toestaan of weigeren.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`Chattype voor sessieverzendregel`},help:{"v1-7cv4f9-4z":`Past de regel toe op basis van het chattype (direct, group, thread), zodat het gedrag per gespreksvorm verschilt. Gebruik dit wanneer privéberichten en groepsbestemmingen verschillende veiligheidsgrenzen vereisen.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`Sleutelprefix voor sessieverzendregel`},help:{"v1-ac4dee-5n":`Controleert op een genormaliseerd sessiesleutelprefix nadat componenten die het beleid gebruiken de sleutel intern hebben genormaliseerd. Gebruik dit voor algemene prefixcontroles en geef de voorkeur aan rawKeyPrefix wanneer exacte matching op de volledige sleutel vereist is.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`Onbewerkt sleutelprefix voor sessieverzendregel`},help:{"v1-1g9w044-5e":`Komt overeen met het ruwe, niet-genormaliseerde prefix van de sessiesleutel om beleid exact op volledige sleutels te richten. Gebruik dit wanneer de genormaliseerde keyPrefix te breed is en u precisie op basis van een agentprefix of specifiek transport nodig hebt.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`Modi voor het delen van sessies`},help:{"v1-xbh52d-5a":`Bepaalt welke samenwerkingsmodi sessie-eigenaren en beheerders mogen selecteren. Weggelaten booleaanse waarden zijn standaard ingeschakeld; stel een modus in op false om deze uit de keuzelijst te verwijderen en nieuwe selecties te weigeren.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`Conceptsessies toestaan`},help:{"v1-1lzap27-2p":`Staat zichtbaarheid als concept toe, waarbij sessies verborgen blijven voor operators die geen eigenaar of beheerder zijn. Standaard: true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`Alleen-lezen-sessies toestaan`},help:{"v1-upl3nu-21":`Staat toe dat sessies voor niet-deelnemers alleen-lezen worden gemaakt. Standaard: true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`Sessies met suggestiemodus toestaan`},help:{"v1-4i8owu-4g":`Staat zichtbaarheid in suggestiemodus toe. In deze fase wordt hetzelfde toelatingsbeleid afgedwongen als bij alleen-lezen; wachtrijen voor suggesties worden via een latere functie geconfigureerd. Standaard: true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`Pad voor sessieopslag`},help:{"v1-hreznz-56":`Stelt het pad in naar het opslagbestand waarin sessiegegevens bij herstarts bewaard blijven. Gebruik alleen een expliciet pad als u een aangepaste schijfindeling, back-uproutering of opslag op een gekoppeld volume nodig hebt.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`Threadkoppelingen voor sessies`},help:{"v1-zbzihu-4s":`Gedeelde standaardinstellingen voor het aanmaken en routeren van threadgebonden sessies in ondersteunde kanalen. Configureer hier de algemene standaardinstellingen en overschrijf ze alleen per kanaal als het gedrag afwijkt.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`Context voor het aanmaken van threads`},help:{"v1-1set6nw-4c":`Standaardcontext van de native subagent voor het aanmaken van threadgebonden sessies. Gebruik "fork" om te beginnen met de gespreksgeschiedenis van de aanvrager of "isolated" voor een nieuwe onderliggende sessie zonder voorgeschiedenis. Standaard: "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`Threadbinding ingeschakeld`},help:{"v1-foomtc-3f":`Algemene hoofdschakelaar voor het aanmaken en routeren van threadgebonden sessies en het afleveren van berichten daarin. Schakel deze uit om threadbinding overal uit te schakelen.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`Time-out voor inactiviteit bij threadbinding (uren)`},help:{"v1-gffnx3-3h":`Standaardperiode van inactiviteit in uren voor threadgebonden sessies bij alle providers/kanalen (0 schakelt verlopen door inactiviteit uit). Standaard: 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`Maximale levensduur van threadbinding (uren)`},help:{"v1-1xfcyhw-39":`Optionele harde maximale levensduur in uren voor threadgebonden sessies bij alle providers/kanalen (0 schakelt de harde limiet uit). Standaard: 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`Threadgebonden sessies aanmaken`},help:{"v1-1lqwbdl-46":`Algemene standaardinstelling die bepaalt of threadgebonden werksessies mogen worden aangemaakt via sessions_spawn en het aanmaken van ACP-threads. Standaard: true wanneer threadbindingen zijn ingeschakeld.`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`Toegestane doelen voor symbolische links van vaardigheden`},help:{"v1-xzybiq-4t":`Vertrouwde fysieke hoofdmappen waarnaar symbolische koppelingen voor skills mogen verwijzen wanneer hun doelen buiten de geconfigureerde bronhoofdmap liggen. Houd dit beperkt, bijvoorbeeld tot een map met skills in een naastgelegen repository.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`Extra mappen voor skills`},help:{"v1-11o7opu-53":`Aanvullende gedeelde hoofdmappen voor skills om met de laagste prioriteit te scannen. Gebruik dit voor naastgelegen repositories of gedeelde skillpakketten die beschikbaar moeten zijn zonder ze naar de OpenClaw-werkruimte te kopiëren.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Skills bewaken`},help:{"v1-1ckr2l5-5d":`Schakel bewaking van het bestandssysteem in voor wijzigingen in skilldefinities, zodat updates kunnen worden toegepast zonder het proces volledig opnieuw te starten. Houd dit ingeschakeld in ontwikkelworkflows en schakel het uit in onveranderlijke productie-images.`}},"skills%2Eworkshop%2Eautonomous%2Emode":{label:{"v1-1hrc7h4-u":`Autonome modus van Skill Workshop`},help:{"v1-1s3kgit-6j":`Regelt leren op de achtergrond: "off" behoudt alleen de suggestiemelding, "propose" maakt voorstellen die op goedkeuring wachten en "auto" past vastgelegde voorstellen toe en voert een wekelijkse beoordeling uit van skills die door Workshop worden beheerd, via gewone bestandsbewerkingen. Standaard: "auto".`}},surfaces:{label:{"v1-exl2ye-g":`Beleidsregels per afleveromgeving`},help:{"v1-vgtjbs-50":`Overschrijvingen van het berichtenbeleid per afleveromgeving, met de vastgestelde id van de afleveromgeving als sleutel. Gebruik dit alleen wanneer één geïmplementeerde afleveromgeving strengere afhandeling van stille antwoorden vereist dan de standaardinstelling van de agent.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`Beleid voor stille antwoorden per afleveromgeving`},help:{"v1-12zgc3n-60":`Overschrijft het beleid voor stille antwoorden voor één vastgestelde afleveromgeving. Niet-ingestelde velden nemen agents.defaults.silentReply over; gebruik specifieke ids voor afleveromgevingen zodat intern of groepsspecifiek gedrag geen invloed heeft op andere bestemmingen.`}},talk:{label:{"v1-15ukbjj-4":`Praten`},help:{"v1-1gx10xa-5g":`Instellingen voor spraaksynthese in de Talk-modus voor stemidentiteit, modelkeuze, uitvoerformaat en onderbrekingsgedrag. Gebruik deze sectie om de spraakervaring voor gebruikers af te stemmen en tegelijkertijd latentie en kosten te beheersen.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Talk-agent`},help:{"v1-iee5l9-2b":`Agent die eigenaar is van Talk-sessies die zonder een expliciete, agentspecifieke sessiesleutel zijn aangemaakt.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Snelle modus voor Talk-consultaties`},help:{"v1-syf3xk-2o":`Gebruik dit om de snelle modus voor de reguliere agentuitvoering achter realtime Talk-consultaties op true of false te zetten.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Denkniveau voor Talk-consultaties`},help:{"v1-1ft5njw-2o":`Gebruik dit om het denkniveau voor de reguliere agentuitvoering achter realtime Talk-consultaties te overschrijven.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Talk onderbreken bij spraak`},help:{"v1-8n9q4o-3l":`Als dit true is (standaard), stopt de assistent met spreken wanneer de gebruiker begint te spreken in de Talk-modus. Laat dit ingeschakeld voor natuurlijke beurtwisseling in gesprekken.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Actieve Talk-provider`},help:{"v1-wgnxhg-1g":`ID van de actieve Talk-provider (bijvoorbeeld "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Instellingen voor Talk-providers`},help:{"v1-oh0yuv-30":`Providerspecifieke Talk-instellingen met de provider-ID als sleutel. Geef hier tijdens de migratie de voorkeur aan boven verouderde talk.*-sleutels.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Configuratie van Talk-provider`},help:{"v1-36pblg-1r":`Talk-configuratievelden die door de provider met de bijbehorende provider-ID worden beheerd.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`API-sleutel van Talk-provider`},help:{"v1-1a1p9wp-v":`API-sleutel van de provider voor de Talk-modus.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Realtime Talk`},help:{"v1-c2re7j-3z":`Provider, model, stem, modus, transport en redeneerstrategie voor realtime Talk. Bewaar de configuratie van de spraak-/TTS-provider in talk.provider en talk.providers.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Redeneerstrategie voor realtime Talk`},help:{"v1-opsatw-37":`Redeneerstrategie voor Talk: agent-consult voor agentondersteuning via de Gateway, direct-tools voor lokale toolaanroepen, of none.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Routering van consultaties voor realtime Talk`},help:{"v1-10qjcvk-5f":`Terugval op doorsturen via de Gateway voor definitieve gebruikerstranscripties wanneer de realtimeprovider openclaw_agent_consult overslaat. provider-direct behoudt antwoorden van de provider; force-agent-consult routeert via OpenClaw.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Instructies voor realtime Talk`},help:{"v1-1jaaj84-5p":`Aanvullende systeeminstructies die worden toegevoegd aan de ingebouwde prompt voor realtime Talk van OpenClaw. Gebruik dit voor stemstijl, toon en ander realtimegedrag aan de providerzijde, zonder de richtlijnen voor agent-consult te wijzigen.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Modus voor realtime Talk`},help:{"v1-1u2xui1-1l":`Uitvoeringsmodus voor Talk: realtime, stt-tts of transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Model voor realtime Talk`},help:{"v1-amou5a-27":`Overschrijving van de model-ID van de realtimeprovider voor Talk-sessies in de browser of onder beheer van de Gateway.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Audiovoorloop voor realtime Talk (ms)`},help:{"v1-1cwg07n-22":`Aantal milliseconden audio dat wordt bewaard vóór de detectie van realtime spraakactiviteit.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Provider voor realtime Talk`},help:{"v1-wwsmpt-1o":`ID van de actieve realtime spraakprovider, zoals openai of google.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Instellingen voor realtime providers van Talk`},help:{"v1-ruagcu-1r":`Providerspecifieke instellingen voor realtime spraak, ingedeeld op provider-ID.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Configuratie van realtime provider voor Talk`},help:{"v1-edfpxm-1u":`Door de provider beheerde configuratie voor realtime spraak voor de bijbehorende provider-ID.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`API-sleutel van realtime provider voor Talk`},help:{"v1-1fbmgpx-z":`API-sleutel van de provider voor realtime Talk.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Redeneerinspanning voor realtime Talk`},help:{"v1-157xd3e-2t":`Providerspecifieke redeneerinspanning voor realtime Talk-sessies, zoals minimal, low, medium of high.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Stilteduur voor realtime Talk (ms)`},help:{"v1-1grnu06-1y":`Aantal milliseconden stilte voordat een gebruikersbeurt in realtime Talk wordt vastgelegd.`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Sprekersstem voor realtime Talk`},help:{"v1-1kgb166-2h":`Overschrijving van de naam van de sprekersstem van de realtime provider voor Talk-sessies in de browser of onder beheer van de Gateway.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`Sprekersstem-ID voor realtime Talk`},help:{"v1-1k8w6vk-2f":`Overschrijving van de ID van de sprekersstem van de realtime provider voor Talk-sessies in de browser of onder beheer van de Gateway.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Transport voor realtime Talk`},help:{"v1-2otjgn-2g":`Byte- en sessietransport voor Talk: webrtc, provider-websocket, gateway-relay of managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`Drempelwaarde voor realtime spraakdetectie in Talk`},help:{"v1-nf5l2t-2j":`Drempelwaarde voor realtime spraakdetectie van 0 (meest gevoelig) tot 1 (minst gevoelig).`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Stiltetime-out voor Talk (ms)`},help:{"v1-1kim32f-59":`Aantal milliseconden dat de gebruiker stil is voordat de Talk-modus het huidige transcript afrondt en verzendt. Laat dit oningesteld om de standaardpauzeduur van het platform te gebruiken (700 ms op macOS en Android, 900 ms op iOS).`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Taalinstelling voor spraak in Talk`},help:{"v1-1un3x4l-4c":`BCP 47-taalcode voor Talk-spraakherkenning op apparaatnodes en de systeemstem op iOS die als terugvaloptie wordt gebruikt, bijvoorbeeld "ru-RU". Laat dit oningesteld om de standaardinstelling van elk apparaat te gebruiken.`}},telemetry:{label:{"v1-sqprmo-9":`Telemetrie`},help:{"v1-1o5tru3-55":`Expliciete toestemming voor anonieme statistieken over functiegebruik die met de dagelijkse updatecontrole worden meegestuurd. Statistieken over functiegebruik zijn standaard uitgeschakeld en bevatten nooit berichten, inloggegevens of identificatiegegevens.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`Tijdstempel van toestemming voor statistieken over functiegebruik`},help:{"v1-1t051az-3t":`ISO-tijdstempel dat vastlegt wanneer de beheerder anonieme statistieken over functiegebruik heeft geaccepteerd of geweigerd. Voorkomt dat de installatiewizard hier opnieuw naar vraagt.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`Anonieme statistieken over functiegebruik`},help:{"v1-1ptrwuq-4r":`Deelt namen van ingeschakelde kanalen en providers, het aantal plug-ins en het aantal recente sessies bij de dagelijkse updatecontrole. Standaard uitgeschakeld en altijd uitgeschakeld wanneer DO_NOT_TRACK=1.`}},tools:{label:{"v1-15cdqf0-5":`Hulpmiddelen`},help:{"v1-1el54kl-5h":`Toolinfrastructuur en standaardinstellingen voor interacties tussen agents. Elementen op hoofdniveau beheren de infrastructuur en standaardinstellingen voor interacties tussen agents; agents.defaults beheert het gedrag van de agentlus; agentvermeldingen kunnen beide waar ondersteund overschrijven.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`Tooltoegang tussen agents`},help:{"v1-1ynpa5f-cf":`Beleid voor sessietoolaanroepen tussen agents: verzenden, weergeven van lijsten, geschiedenis, zoeken en uitlezen van status (standaard: ingeschakeld). Gebruik allow om agentparen te beperken; enabled=false blokkeert gewone toegang tussen agents. Native subagentsessies en ACP-onderliggende sessies die eigendom zijn van de aanvrager, blijven bereikbaar met zichtbaarheid tree of all. Stel voor strikte scheiding tools.sessions.visibility in op agent of self (tree laat nog steeds native/ACP-onderliggende sessies van de aanvrager toe), of gebruik afzonderlijke gateways.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`Lijst met toegestane doelagents voor toegang tussen agents`},help:{"v1-1jt2ari-76":`Agent-id's of *-patronen die mogen deelnemen aan aanroepen tussen agents; zowel de aanvragende agent als de doelagent moet overeenkomen. Toegang tussen agents is standaard ingeschakeld, en als allow ontbreekt of leeg is, is elk paar toegestaan. Stel een expliciete lijst in om de toegang te beperken; lege vermeldingen weigeren toegang.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`Tool voor toegang tussen agents inschakelen`},help:{"v1-w950oq-ba":`Schakelt toegang tot sessietools tussen agents in (standaard: true); als allow ontbreekt of leeg is, is elk agentpaar toegestaan. Stel in op false om gewone toegang tussen agents te blokkeren; native subagentsessies en ACP-onderliggende sessies die eigendom zijn van de aanvrager, blijven bereikbaar met zichtbaarheid tree of all. Stel voor strikte scheiding tools.sessions.visibility in op agent of self (tree laat nog steeds native/ACP-onderliggende sessies van de aanvrager toe), of gebruik afzonderlijke gateways.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`Lijst met toegestane tools`},help:{"v1-1is3eaq-4v":`Absolute lijst met toegestane tools die de van het profiel afgeleide standaardwaarden vervangt voor strikt beheerde omgevingen. Gebruik dit alleen als je bewust een zorgvuldig geselecteerde subset van toolmogelijkheden inzet.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`Aanvullingen op de lijst met toegestane tools`},help:{"v1-1xw9zp8-57":`Extra vermeldingen in de lijst met toegestane tools, die worden toegevoegd aan het geselecteerde toolprofiel en het standaardbeleid. Houd deze lijst klein en expliciet, zodat bij audits snel duidelijk is welke beleidsuitzonderingen bewust zijn ingesteld.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`Toolbeleid per provider`},help:{"v1-1ecljob-4y":`Providerspecifieke uitzonderingen voor het toestaan of weigeren van tools, gekoppeld aan de kanaal-/provider-ID om mogelijkheden per interface af te stemmen. Gebruik dit als één provider strengere controles nodig heeft dan het algemene toolbeleid.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`Codemodus`},help:{"v1-1ecc39k-6k":'Algemene OpenClaw Code Mode. Als deze globaal niet is ingesteld, is de standaardwaarde `"auto"`; een expliciet opgegeven object zonder `enabled` blijft uitgeschakeld. Agentruns waarin deze modus actief is, stellen alleen `exec` en `wait` beschikbaar aan het model en benaderen de gebruikelijke tools via de catalogusbrug.'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`Codemodus inschakelen`},help:{"v1-rgstxz-aj":'Globale activering van OpenClaw Code Mode. Als de globale instelling volledig ontbreekt, is de standaardwaarde `"auto"`; een expliciet opgegeven object zonder `enabled` blijft uitgeschakeld. `"auto"` activeert de modus voor modellen met een voorkeur voor de catalogus, terwijl `true` de modus activeert voor runs die tools kunnen gebruiken. Activeringsinstellingen op agent- en modelniveau hebben voorrang. Een run waarin de modus actief is, wordt uit veiligheid geblokkeerd als de runtime niet beschikbaar is, in plaats van de volledige toollijst beschikbaar te stellen.'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Executor voor Code Mode`},help:{"v1-l8nlk2-6x":`JavaScript-executor: "node" (standaard) gebruikt Node vm voor vertrouwde code en is geen beveiligingssandbox; "quickjs" gebruikt de meegeleverde QuickJS WASM-plugin voor extra beveiligde gastuitvoering. Toolmachtigingen gelden voor beide. Als de geselecteerde executor ontbreekt, wordt de uitvoering uit veiligheid geblokkeerd.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`Uitvoerlimiet voor codemodus`},help:{"v1-1hmij9q-1n":`Maximumaantal geserialiseerde bytes dat via de uitvoer van de codemodus wordt teruggegeven.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`Limiet voor openstaande toolaanroepen in codemodus`},help:{"v1-3b5tyd-2i":`Maximaal aantal gelijktijdige geneste toolaanroepen dat een VM in codemodus kan starten voordat deze later moet worden hervat.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`Maximaal aantal zoekresultaten in codemodus`},help:{"v1-1gpue5r-28":`Maximaal aantal zoekresultaten uit de verborgen catalogus dat een programma in codemodus kan opvragen.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`Snapshotlimiet voor codemodus`},help:{"v1-1mmgkqy-1x":`Maximaal aantal geserialiseerde bytes dat voor één onderbroken QuickJS-snapshot wordt bewaard.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`Geheugenlimiet voor codemodus`},help:{"v1-xetora-6n":`Heaplimiet voor QuickJS-gasten of een naar beste vermogen gehandhaafd V8-heapbudget voor Node-workers, in bytes. De runtime-overhead van Node en minimale geheugentoewijzingen van de engine beïnvloeden het effectieve budget; externe buffers en de RSS van het proces zijn uitgesloten. Dit biedt geen beveiligingsgarantie.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`Interface voor codemodus`},help:{"v1-dsp2b9-2x":'Interface voor het model. Alleen "only" wordt ondersteund: maak `exec` en `wait` van codemodus beschikbaar en verberg de normale tools.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`Standaardaantal zoekresultaten in codemodus`},help:{"v1-1io42lu-2m":"Standaardaantal zoekresultaten uit de verborgen catalogus dat `catalog.search` in codemodus retourneert."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`TTL voor snapshots in codemodus`},help:{"v1-1nxfczz-28":"Hoelang onderbroken Code Mode-uitvoeringen met `wait` kunnen worden hervat voordat ze verlopen."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`Time-out voor codemodus`},help:{"v1-8csycm-1p":"Maximaal aantal milliseconden voor één `exec`- of `wait`-aanroep in codemodus."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`Blokkeerlijst voor tools`},help:{"v1-wilr1b-4p":`Algemene blokkeerlijst voor tools die de vermelde tools blokkeert, ook als profiel- of providerregels ze zouden toestaan. Gebruik blokkeerregels voor noodblokkades en langdurige, gelaagde beveiliging.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`Tooltoegang met verhoogde rechten`},help:{"v1-ehcm0r-5a":`Instellingen voor tooltoegang met verhoogde rechten tot opdrachtinterfaces die alleen toegankelijk mogen zijn voor vertrouwde afzenders. Laat dit uitgeschakeld tenzij de werkprocessen van de beheerder expliciet acties met verhoogde rechten vereisen.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`Toestemmingsregels voor tools met verhoogde rechten`},help:{"v1-1u9bhih-54":`Toestemmingsregels voor afzenders voor tools met verhoogde rechten, meestal met identiteitsnotaties van kanalen of providers als sleutel. Gebruik nauw afgebakende, expliciete identiteiten zodat opdrachten met verhoogde rechten niet door onbedoelde gebruikers kunnen worden gestart.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`Tooltoegang met verhoogde rechten inschakelen`},help:{"v1-1n8oyal-4l":`Schakelt het uitvoeringspad voor tools met verhoogde rechten in wanneer de afzender- en beleidscontroles slagen. Laat dit uitgeschakeld in openbare of gedeelde kanalen en schakel het alleen in voor vertrouwde omgevingen die door de eigenaar worden beheerd.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Exec-tool`},help:{"v1-p5piic-56":`Groep beleidsinstellingen voor de Exec-tool voor de host voor shelluitvoering, beveiligingsmodus, goedkeuringsgedrag en runtimekoppelingen. Behoud conservatieve standaardinstellingen in productie en beperk uitvoeringspaden met verhoogde rechten verder.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`Lijst met toegestane modellen voor apply_patch`},help:{"v1-4q5ovf-1x":`Optionele lijst met toegestane model-ID's (bijv. "gpt-5.4" of "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`apply_patch inschakelen`},help:{"v1-1erkir4-31":`Schakel apply_patch in of uit voor OpenAI- en OpenAI Codex-modellen wanneer het toolbeleid dit toestaat (standaard: true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`apply_patch alleen binnen de werkruimte`},help:{"v1-x2z207-3o":`Beperk apply_patch-paden tot de werkruimtemap (standaard: true). Stel in op false om schrijven buiten de werkruimte toe te staan (gevaarlijk).`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`Melding van lopende uitvoering na exec-goedkeuring (ms)`},help:{"v1-1gwwann-4z":`Vertraging in milliseconden voordat een melding van lopende uitvoering wordt getoond nadat exec-goedkeuring is verleend. Verhoog deze waarde om flikkeren bij snelle opdrachten te verminderen, of verlaag deze voor snellere feedback aan de operator.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`Goedkeuring vragen voor exec`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`Opdrachtmarkering voor exec`},help:{"v1-kyxd4o-4n":`Toon op de parser gebaseerde opdrachtmarkeringen in exec-goedkeuringsverzoeken (standaard: false). Schakel dit in om gemarkeerde opdrachttekst weer te geven zonder het exec-goedkeuringsbeleid te wijzigen.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`Geldigheidsduur van doorlopende machtigingen (dagen)`},help:{"v1-5uxe2j-6r":`Standaardgeldigheidsduur in dagen (1-3650) voor doorlopende machtigingen die via allow-always worden aangemaakt bij automatiseringsgoedkeuringen. Als dit niet is ingesteld, blijven machtigingen geldig totdat ze worden ingetrokken of de bijbehorende automatisering verandert. De voorwaarden worden bij aanmaak vastgelegd, dus wijzigingen hierin gelden alleen voor toekomstige machtigingen.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`Exec-doel`},help:{"v1-rno1mf-5q":`Selecteert de strategie voor het uitvoeringsdoel van shellopdrachten. Gebruik "auto" voor gedrag dat rekening houdt met de runtime (sandbox indien beschikbaar, anders gateway), of stel sandbox/gateway/node expliciet in als je een vaste uitvoeringsomgeving nodig hebt.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`Uitvoeringsmodus`},help:{"v1-1wi6t4l-5q":`Genormaliseerde keuzeschakelaar voor het uitvoeringsbeleid. Gebruik "auto" om ontbrekende goedkeuringen door een classificatiemodel te laten beoordelen, "ask" om ze door een mens te laten beoordelen, "allowlist" om alleen deterministisch veilige opdrachten toe te staan, of "full" voor vertrouwd lokaal gebruik.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`Nodekoppeling voor uitvoering`},help:{"v1-rfnz54-4s":`Configuratie van de nodekoppeling voor uitvoeringstools wanneer de uitvoering van opdrachten wordt gedelegeerd aan verbonden nodes. Gebruik alleen een expliciete nodekoppeling als routering via meerdere nodes vereist is.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`Melden bij beëindiging van uitvoering`},help:{"v1-1ounlvx-3q":`Als dit true is (standaard), plaatsen uitvoeringssessies op de achtergrond bij beëindiging en levenscyclusgebeurtenissen van node-uitvoeringen een systeemgebeurtenis in de wachtrij en vragen ze een heartbeat aan.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`Melden bij geslaagde uitvoering zonder uitvoer`},help:{"v1-1wx4xxd-3d":`Als dit true is, plaatsen geslaagde uitvoeringen op de achtergrond zonder uitvoer toch een systeemgebeurtenis voor voltooiing in de wachtrij (standaard: false).`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`Vooraan toevoegen aan PATH voor uitvoering`},help:{"v1-s1aimc-1r":`Mappen die vooraan aan PATH worden toegevoegd voor uitvoeringen (gateway/sandbox).`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`Beoordelaar voor uitvoering`},help:{"v1-12y548k-4x":`Modelgestuurde exec-beoordelaar die in de automatische modus wordt gebruikt voordat wordt teruggevallen op menselijke goedkeuring. Configureer hier een gerichte modeloverschrijving als je de exec-beoordeling wilt scheiden van het hoofdmodel van de agent.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`Snelle modus voor de uitvoeringsbeoordelaar`},help:{"v1-175bx14-8u":`Optionele snelle modus voor goedkeuringsbeoordelingen in OpenClaw: true vraagt om verwerking met prioriteit via ondersteunde OpenAI Responses- en ChatGPT/OAuth-routes; false vraagt om standaardverwerking. Laat dit weg om de standaardinstellingen van de provider te behouden. De snelle modus kan meer kosten en is afhankelijk van de beschikbaarheid bij de provider. Hiermee wordt de native Codex Guardian niet geconfigureerd.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`Model voor exec-beoordelaar`},help:{"v1-1lltiy5-3i":`Optionele provider-/modeloverschrijving voor de exec-beoordelingsagent. Laat dit weg om het geconfigureerde primaire model van de doelagent te hergebruiken.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`Denkinspanning van de uitvoeringsbeoordelaar`},help:{"v1-yg2gby-6u":`Optionele redeneerinspanning voor modelgestuurde goedkeuringsbeoordelingen in OpenClaw: minimal, low, medium, high, xhigh of max. Laat dit weg om de standaardinstellingen van de provider te behouden. Ondersteunde niveaus worden genormaliseerd voor het geselecteerde model. Hiermee wordt de native Codex Guardian niet geconfigureerd.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`Time-out voor exec-beoordelaar (ms)`},help:{"v1-1o30chi-3w":`Time-out per fase voor de exec-beoordelaar in milliseconden voor modelvoorbereiding en voltooiing, voordat wordt teruggevallen op menselijke goedkeuring (standaard: 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`Profielen voor veilige uitvoerbare bestanden voor exec`},help:{"v1-4cdcwe-29":`Optionele veiligheidsprofielen per uitvoerbaar bestand (beperkingen voor positionele argumenten + toegestane/geweigerde opties).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`Veilige uitvoerbare bestanden voor exec`},help:{"v1-1of1m2s-21":`Sta toe dat veilige uitvoerbare bestanden die alleen stdin gebruiken worden uitgevoerd zonder expliciete vermeldingen in de toestemmingslijst.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`Vertrouwde mappen voor veilige uitvoerbare bestanden voor exec`},help:{"v1-zljbcn-2v":`Aanvullende expliciete mappen die worden vertrouwd bij padcontroles voor veilige uitvoerbare bestanden (vermeldingen in PATH worden nooit automatisch vertrouwd).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`Exec-beveiliging`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`Goedkeuring voor inline-evaluatie vereisen`},help:{"v1-jkmgo7-5z":"Vereis expliciete goedkeuring voor inline-evaluatievormen van interpreters, zoals `python -c`, `node -e`, `ruby -e` of `osascript -e`. Voorkomt stilzwijgend hergebruik van de toestemmingslijst en wijzigt voor deze vormen altijd toestaan in elke keer vragen."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`Time-out voor uitvoering (seconden)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`Bestandssysteemtools beperken tot de werkruimte`},help:{"v1-1mhuvka-2s":`Beperk bestandssysteemtools (read/write/edit/apply_patch) tot de werkruimtemap (standaard: false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`GitHub CLI-identiteit en Git-auteur`},help:{"v1-1fl77im-5s":`Beheerd lokaal GitHub CLI-profiel en optionele Git-auteur voor agenttools. Laat dit object weg om het oorspronkelijke account en de oorspronkelijke auteur van de gebruiker waaronder de Gateway draait te behouden; inloggegevens voor externe repository's worden nooit overschreven.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`E-mailadres van Git-auteur`},help:{"v1-kol5g6-1i":`Optioneel e-mailadres voor de Git-auteur en committer, alleen voor dit proces.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Naam van Git-auteur`},help:{"v1-z5bl1f-1h":`Optionele naam voor de Git-auteur en committer, alleen voor dit proces.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`Type GitHub-inloggegevens`},help:{"v1-qi3qun-3q":`Markeert een beheerd OAuth-profiel waarvan de roterende vernieuwingsreferentie eigendom is van de Gateway. Profielen waarbij dit is weggelaten, gebruiken een persoonlijk toegangstoken.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`GitHub-profielversie`},help:{"v1-4lzl0-27":`Gegenereerde profielversie zonder inhoudelijke betekenis, gebruikt om beheerde inloggegevens atomair te wisselen.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`Linkanalyse inschakelen`},help:{"v1-23t2io-59":`Schakel automatische voorverwerking voor linkanalyse in, zodat URL's kunnen worden samengevat voordat de agent gaat redeneren. Laat dit ingeschakeld voor rijkere context en schakel het uit wanneer strikt minimale verwerking vereist is.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`Maximumaantal links voor linkanalyse`},help:{"v1-ksxmcv-52":`Maximumaantal links dat per beurt wordt uitgewerkt tijdens linkanalyse. Gebruik lagere waarden om de latentie en kosten in drukke gesprekken te beperken en hogere waarden wanneer context uit meerdere links essentieel is.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`Modellen voor linkanalyse`},help:{"v1-6j3mnw-5a":`Lijst met voorkeursmodellen voor linkanalyse, die waar ondersteund op volgorde als terugvalopties worden geprobeerd. Gebruik eerst lichte modellen voor routinematige samenvattingen en zwaardere modellen alleen wanneer dat nodig is.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`Bereik van linkanalyse`},help:{"v1-183cwpa-55":`Bepaalt wanneer linkanalyse wordt uitgevoerd op basis van de gesprekscontext en het berichttype. Houd het bereik beperkt om onnodig ophalen te voorkomen bij berichten waarin links niet relevant zijn voor verdere acties.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`Time-out voor linkanalyse (sec)`},help:{"v1-61v30o-4p":`Maximale analysetijd per link in seconden voordat links die nog niet zijn verwerkt worden overgeslagen. Houd deze tijd beperkt om lange wachttijden te voorkomen wanneer externe sites traag of onbereikbaar zijn.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-c9sqnr-j":`Detectie van toollussen`},help:{"v1-1e3rls8-5g":`Regelt de detectie van herhaalde toolaanroepen op basis van recente geschiedenis en de beveiliging na compactie. Laat deze instelling weg om de detectie op basis van recente geschiedenis uitgeschakeld en de beveiliging na compactie ingeschakeld te houden. Stel true in om beide in te schakelen, of false om beide uit te schakelen.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`Bijlagenbeleid voor audioanalyse`},help:{"v1-1s3t9s5-3o":`Kies welke overeenkomende audiobijlagen worden verwerkt. Verwerk alleen de eerste bijlage, tenzij transcriptie van meerdere bijlagen de bedoeling is.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`Opmaak voor het terugsturen van transcripties`},help:{"v1-glpdzh-3i":`Maak het teruggestuurde transcript op met een {transcript}-placeholder. Laat de placeholder intact zodat het transcript wordt meegestuurd.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`Transcript terugsturen naar chat`},help:{"v1-1dedp8c-3r":`Stuur het audiotranscript terug naar de oorspronkelijke chat voordat de agent het verwerkt. Schakel dit in wanneer gebruikers moeten kunnen controleren wat het systeem heeft gehoord.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`Audioherkenning inschakelen`},help:{"v1-1v0x7te-2m":`Schakel audioherkenning in zodat spraakberichten of audiofragmenten kunnen worden getranscribeerd als context voor de agent.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`Taal voor audioherkenning`},help:{"v1-1ruqt97-3z":`Standaardtaalindicatie voor aanbieders van audiotranscriptie. Stel deze in wanneer de voornamelijk gesproken taal bekend is en de taaldetectie van de aanbieder onbetrouwbaar is.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`Maximumaantal bytes voor audioherkenning`},help:{"v1-1mcckc8-43":`Standaardlimiet voor de grootte van audio-invoer voor geconfigureerde en automatisch gedetecteerde modellen. Stel deze in op de grootste opname die je aanbieders en netwerk moeten accepteren.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`Maximumaantal tekens voor audioherkenning`},help:{"v1-eo1dp-43":`Standaard maximale transcriptlengte voor geconfigureerde en automatisch gedetecteerde modellen. Gebruik een lagere waarde om te voorkomen dat lange spraakberichten de context van de agent vergroten.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`Voorkeursmodel voor audioherkenning`},help:{"v1-1n5zya1-3c":`Geef voor audiotranscriptie de voorkeur aan één item in tools.media.models met een capaciteitstag boven de overige compatibele terugvalopties.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`Prompt voor audioanalyse`},help:{"v1-1v5jtay-4b":`Standaardprompt voor audiotranscriptie wanneer een modelitem deze niet overschrijft. Houd de instructie ongewijzigd wanneer vervolgworkflows afhankelijk zijn van de transcriptiestijl.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`Bereik van audioanalyse`},help:{"v1-1pptfg0-3w":`Beperk audioanalyse op basis van kanaal, chattype of bronsleutel. Houd dit bereik beperkt wanneer automatische transcriptie gevoelig of duur is.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`Time-out voor audioanalyse (sec)`},help:{"v1-n8wc6c-3b":`Standaardtime-out voor audioanalyseverzoeken. Verhoog deze voor lange opnamen of tragere lokale transcriptiemodellen.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`Gelijktijdigheid van mediaanalyse`},help:{"v1-13kr9np-58":`Maximumaantal gelijktijdige mediaanalyses per beurt, verdeeld over afbeeldings-, audio- en videotaken. Verlaag dit in implementaties met beperkte middelen om overbelasting van de CPU of het netwerk te voorkomen.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`Bijlagenbeleid voor afbeeldingsanalyse`},help:{"v1-11hofbw-3e":`Kies welke overeenkomende afbeeldingsbijlagen worden verwerkt. Verwerk alleen de eerste, tenzij analyse van meerdere afbeeldingen de bedoeling is.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`Afbeeldingsanalyse inschakelen`},help:{"v1-1b2zw34-50":`Schakel beeldinterpretatie in zodat bijgevoegde afbeeldingen of afbeeldingen waarnaar wordt verwezen, kunnen worden omgezet in tekstuele context. Schakel dit uit als u uitsluitend met tekst wilt werken of kosten voor beeldverwerking wilt vermijden.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`Maximumaantal bytes voor beeldinterpretatie`},help:{"v1-jwwpd1-3v":`Standaardlimiet voor de grootte van invoerafbeeldingen voor geconfigureerde en automatisch gedetecteerde modellen. Stem deze af op de payloadlimieten van de provider en de bandbreedte van de implementatieomgeving.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`Maximumaantal tekens voor beeldinterpretatie`},help:{"v1-ebnxhk-3q":`Standaard maximale lengte van afbeeldingsbeschrijvingen. Gebruik een lagere waarde voor compacte context of een hogere waarde voor gedetailleerde OCR en scèneanalyse.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`Voorkeursmodel voor beeldinterpretatie`},help:{"v1-1o2uwo6-3c":`Geef voor beeldinterpretatie de voorkeur aan één item in tools.media.models dat met de bijbehorende functionaliteit is getagd, vóór de overige compatibele terugvalopties.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`Prompt voor beeldinterpretatie`},help:{"v1-1jdcu8b-3u":`Standaardprompt voor beeldinterpretatie wanneer een item deze niet overschrijft. Houd deze deterministisch wanneer afnemers afhankelijk zijn van consistente beschrijvingen.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`Bereik van beeldinterpretatie`},help:{"v1-tievo1-3s":`Beperk beeldinterpretatie op basis van kanaal, chattype of bronsleutel. Houd dit bereik klein in drukke of niet-vertrouwde kanalen om de verwerking te beheersen.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`Time-out voor beeldinterpretatie (sec)`},help:{"v1-1wcm84x-31":`Standaardtime-out voor aanvragen voor beeldanalyse. Verhoog deze voor grote afbeeldingen of tragere lokale visuele modellen.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`Gedeelde modellen voor media-analyse`},help:{"v1-f34u65-47":`Canonieke modellenlijst voor media-analyse. Geef bij elk item met capaciteitstags aan of het afbeeldingen, audio of video ondersteunt, zodat elke pipeline alleen compatibele terugvalopties selecteert.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`Bijlagenbeleid voor videoanalyse`},help:{"v1-1qm1qrc-3e":`Kies welke overeenkomende videobijlagen worden verwerkt. Verwerk alleen de eerste, tenzij u bewust meerdere video's wilt analyseren.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`Videoanalyse inschakelen`},help:{"v1-1ltx5gl-58":`Schakel videoanalyse in zodat clips kunnen worden samengevat in tekst voor verdere redenering en antwoorden. Schakel dit uit als videoverwerking niet is toegestaan volgens het beleid of te duur is voor uw implementatie.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`Maximumaantal bytes voor videoanalyse`},help:{"v1-2mp77v-3v":`Standaardlimiet voor de grootte van video-invoer voor geconfigureerde en automatisch gedetecteerde modellen. Stem deze af op de limieten voor aanvraaggrootte van de provider en de bandbreedte van uw implementatie.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`Maximumaantal tekens voor videoanalyse`},help:{"v1-1j0x40b-3j":`Standaard maximale lengte van videobeschrijvingen. Gebruik een lagere waarde voor compacte context of een hogere waarde voor gedetailleerde scènesamenvattingen.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`Voorkeursmodel voor videoanalyse`},help:{"v1-1cygq5k-3c":`Geef voor videoanalyse de voorkeur aan één tools.media.models-item met een capaciteitstag, vóór de overige compatibele terugvalopties.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`Prompt voor videoanalyse`},help:{"v1-ul2jx4-3r":`Standaardprompt voor videoanalyse wanneer een item deze niet overschrijft. Houd deze deterministisch wanneer afnemers afhankelijk zijn van consistente samenvattingen.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`Bereik van videoanalyse`},help:{"v1-7gfrx3-3s":`Beperk videoanalyse op basis van kanaal, chattype of bronsleutel. Houd dit bereik klein in drukke of niet-vertrouwde kanalen om de verwerking te beheersen.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`Time-out voor videoanalyse (sec)`},help:{"v1-e8rzsy-33":`Standaardtime-out voor videoanalyseverzoeken. Verhoog deze voor langere clips of tragere lokale analysemodellen.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`Lijst met toegestane berichtacties`},help:{"v1-1iceqwa-5c":`Globale lijst met toegestane berichtacties voor de berichttool. Gebruik deze alleen wanneer de volledige runtime een beperkte set acties beschikbaar moet stellen en accepteren; geef voor openbare agents of agents in een sandbox de voorkeur aan lijsten per agent.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`Berichtuitzending inschakelen`},help:{"v1-1ms74z7-14":`Schakel de uitzendactie in (standaard: true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`Contextoverschrijdend verzenden toestaan (tussen providers)`},help:{"v1-276qxo-2s":`Verzenden tussen verschillende providers toestaan (standaard: true). Stel in op false om berichtenverkeer tussen providers te blokkeren.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`Contextoverschrijdend verzenden toestaan (dezelfde provider)`},help:{"v1-1sg4x49-1z":`Verzenden naar andere kanalen binnen dezelfde provider toestaan (standaard: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`Markering voor contextoverschrijdende berichten`},help:{"v1-1fg6jrp-1z":`Een zichtbare herkomstmarkering toevoegen bij contextoverschrijdend verzenden (standaard: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`Voorvoegsel voor contextoverschrijdende markeringen`},help:{"v1-eblsru-1p":`Tekstvoorvoegsel voor contextoverschrijdende markeringen (ondersteunt "{channel}").`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`Achtervoegsel voor contextoverschrijdende markeringen`},help:{"v1-1nk0jub-1p":`Tekstachtervoegsel voor contextoverschrijdende markeringen (ondersteunt "{channel}").`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`Toolprofiel`},help:{"v1-h6k98q-5k":`Globale toolprofielnaam waarmee een vooraf gedefinieerde basis voor het toolbeleid wordt geselecteerd voordat uitzonderingen voor toestaan en weigeren worden toegepast. Gebruik dit voor consistente omgevingsinstellingen voor alle agents en houd profielnamen stabiel.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`Toolbeleid voor de sandbox`},help:{"v1-ea7awo-4k":`Overkoepelend toolbeleid voor agentuitvoeringen in een sandbox, zodat daarvoor afzonderlijke bevoegdheidsgrenzen kunnen gelden. Gebruik dit om strengere beveiliging af te dwingen in sandboxomgevingen.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`Beleid voor toestaan en weigeren van tools in de sandbox`},help:{"v1-ub701o-4t":`Toolbeleid voor toestaan en weigeren dat wordt toegepast wanneer agents in sandboxomgevingen worden uitgevoerd. Houd de toegestane bevoegdheden minimaal, zodat sandboxtaken niet kunnen uitgroeien tot onnodige externe acties.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`Zichtbaarheid van sessietools`},help:{"v1-1vtq2rh-c5":`Bepaalt welke sessies toegankelijk zijn via sessions_list/sessions_history/sessions_search/sessions_send/session_status. ("all" is de standaardwaarde = elke sessie op de Gateway, inclusief die van andere agents en gebruikers; "agent" = elke sessie binnen de huidige agent-id; "self" = alleen de huidige sessie; "tree" = de huidige sessie + gestarte subagentsessies). Toegang tussen agents is standaard ingeschakeld en wordt begrensd door tools.agentToAgent; gebruik een beperktere zichtbaarheid om de toegang te beperken.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`Toolbeleid voor subagents`},help:{"v1-1xoug01-4z":`Overkoepelend toolbeleid voor gestarte subagents om de beschikbaarheid van tools te beperken of uit te breiden ten opzichte van de standaardinstellingen van de bovenliggende agent. Gebruik dit om de mogelijkheden van gedelegeerde agents af te stemmen op het doel van de taak.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`Beleid voor het toestaan/weigeren van tools voor subagents`},help:{"v1-7vxsbf-5d":`Beleid voor het toestaan/weigeren van tools, toegepast op de uitvoeromgevingen van gestarte subagents. Houd dit beperkter dan het bereik van de bovenliggende agent. Tools die bij de bovenliggende agent horen, zoals progress_card, worden altijd geweigerd, ook via allow/alsoAllow.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`Zwerm`},help:{"v1-1q96vvs-45":`Orkestratie van subagents in verzamelmodus. Standaard ingeschakeld; stel false in om dit uit te schakelen. Toolmachtigingen blijven van toepassing op agents_wait en opties voor het starten van een zwerm.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`Standaardagent voor zwermen`},help:{"v1-p4alpg-2m":`Standaarddoelagent voor het starten van zwermen waarbij agentId ontbreekt. De lijst met toegestane subagents blijft van toepassing.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`Zwermen inschakelen`},help:{"v1-1nnnrq9-2e":`Schakelt subagents in verzamelmodus en agents_wait in. Standaard ingeschakeld; stel false in om dit uit te schakelen.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`Actieve subagenten per zwermgroep`},help:{"v1-kfx6qp-1c":`Maximaal aantal actieve verzamel-subagenten per zwermgroep.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1dmgf1f-p":`Gelijktijdige subagenten in zwerm`},help:{"v1-1d46jtm-1s":`Maximaal aantal gelijktijdig draaiende verzamel-subagenten per zwermgroep.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`Totaal aantal subagenten per zwermgroep`},help:{"v1-1gc9vl1-1e":`Maximaal aantal verzamel-subagenten dat gedurende de levensduur van een zwermgroep kan worden gestart.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`Maximale wachttijd voor zwerm`},help:{"v1-bog18y-1g":`Maximale time-out die agents_wait accepteert, in seconden.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`Tools zoeken`},help:{"v1-s0kx04-7y":`Maak grote toolcatalogi van OpenClaw, MCP en clients compacter. OpenClaw-runtimes gebruiken automatisch gestructureerde Tool Search als er niets is ingesteld; ingeschakelde Code Mode heeft voorrang en Codex gebruikt zijn eigen zoekfunctie. Stel false in om dit uit te schakelen, true voor de codebrug, of gebruik de objectvorm om een modus te kiezen.`}},"tools%2EtoolSearch%2EcodeTimeoutMs":{label:{"v1-yyul8h-o":`Time-out voor code bij tools zoeken`},help:{"v1-105r499-34":"Maximaal aantal milliseconden voor één uitvoering van `tool_search_code`. De runtime begrenst waarden tot het ondersteunde bereik van 1 tot 60 seconden."}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`Tools zoeken inschakelen`},help:{"v1-1vm3hfr-4h":"Schakelt het zoeken naar tools in. Wanneer dit is ingeschakeld, verbergt OpenClaw grote toolcatalogi achter `tool_search_code` of gestructureerde tools voor zoeken, beschrijven en aanroepen tijdens uitvoeringen van de ingebedde runtime."}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`Maximaal aantal resultaten bij tools zoeken`},help:{"v1-7du4kh-32":`Maximaal aantal zoekresultaten voor tools dat een model kan opvragen. Tijdens de uitvoering worden waarden begrensd tot het ondersteunde bereik 1..50.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`Interface voor het zoeken naar tools`},help:{"v1-jybcbe-7x":'Kies de interface die het model ziet: "code" stelt `tool_search_code` beschikbaar; "tools" stelt gestructureerde terugvaltools voor zoeken, beschrijven en aanroepen beschikbaar; "directory" houdt een begrensde toolcatalogus zichtbaar, stelt een begrensde set waarschijnlijk benodigde of verplichte schema\'s beschikbaar en maakt de rest toegankelijk via zoeken, beschrijven en aanroepen.'}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`Standaardaantal zoekresultaten voor tools`},help:{"v1-1uchq7t-39":"Standaardaantal zoekresultaten voor tools dat wordt geretourneerd wanneer het model geen limiet opgeeft. Tijdens de uitvoering wordt dit begrensd tot `maxSearchLimit`."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`Tool voor gestructureerde plannen inschakelen`},help:{"v1-1xgegme-4o":"Uniforme statustool `progress_card` voor blijvend opgeslagen plannen en beschrijvende notities in bovenliggende sessies. Standaard ingeschakeld; stel in op false om uit te schakelen. Nooit beschikbaar voor subagenten."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Webtools`},help:{"v1-fpsy5-4y":`Groep beleidsinstellingen voor webtools om zoek- en ophaalproviders, limieten en terugvalgedrag af te stemmen. Zorg dat ingeschakelde instellingen aansluiten op de beschikbaarheid van API-sleutels en het beleid voor uitgaand netwerkverkeer.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`Cache-TTL voor webophalen (min)`},help:{"v1-1hk89qp-17":`Cache-TTL in minuten voor web_fetch-resultaten.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Tool voor webophalen inschakelen`},help:{"v1-yrswld-1f":`Schakel de tool web_fetch in (lichtgewicht ophalen via HTTP).`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`Aanvraagheaders voor webophaling`},help:{"v1-16bjkv5-me":"Extra aanvraagheaders die worden meegestuurd met directe web_fetch-aanvragen, bijvoorbeeld headers voor gatewayroutering of authenticatie. Elke geconfigureerde waarde wordt als gevoelig behandeld en afgeschermd in vrijgegeven configuratiegegevens en debugopnamen. Waarden zijn gewone tekenreeksen, ondersteunen ${VAR}-substitutie en de globale $${VAR}-escape voor letterlijke weergave, en worden verzonden naar URL's die door het model zijn gekozen. Items worden gevalideerd wanneer de aanvraag wordt opgebouwd, niet wanneer de configuratie wordt geladen. Een ongeldige naam of een waarde die niet kan worden verzonden, wordt daarom weggelaten en gelogd in plaats van de functionaliteit uit te schakelen; Accept, Accept-Language, User-Agent en framingheaders zoals Transfer-Encoding worden ook weggelaten. Gebruik tools.web.fetch.userAgent om de useragent te wijzigen. Bij omleidingen naar een andere oorsprong blijven alleen headers uit de lijst met toegestane veilige headers van guarded-fetch behouden. Wijzigingen in de daadwerkelijk verzonden headers leiden tot afzonderlijke cachepartities voor ophaalresultaten."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`Maximumaantal tekens voor webophaling`},help:{"v1-12d1fw7-1d":`Maximumaantal tekens dat door web_fetch wordt geretourneerd (afgekapt).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`Harde tekenlimiet voor webophaling`},help:{"v1-cl2mf1-1v":`Harde bovengrens voor maxChars van web_fetch (geldt voor de configuratie en toolaanroepen).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`Maximumaantal omleidingen voor webophaling`},help:{"v1-t6eak9-1h":`Maximumaantal toegestane omleidingen voor web_fetch (standaard: 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`Maximale downloadgrootte voor webophaling (bytes)`},help:{"v1-q6ld9c-10":`Maximale downloadgrootte voordat de inhoud wordt afgekapt.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`Provider voor webophaling`},help:{"v1-6pb3nv-v":`ID van de terugvalprovider voor het ophalen van webinhoud.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`Extractie met Readability bij het ophalen van webinhoud`},help:{"v1-19exqzx-2c":`Gebruik Readability om de hoofdinhoud uit HTML te extraheren (valt terug op eenvoudige HTML-opschoning).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`SSRF-beleid voor het ophalen van webinhoud`},help:{"v1-qtn7zx-3c":`Gerichte uitzonderingen op het SSRF-beleid voor web_fetch. Houd het bereik beperkt en schakel deze alleen in voor bekende proxyomgevingen op het lokale netwerk.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`Toegestane hostnamen voor het ophalen van webinhoud`},help:{"v1-1j9ctya-35":`Exacte hostnamen of letterlijke IP-adressen die zijn toegestaan voor web_fetch, inclusief doelen die anders worden geblokkeerd. Houd de lijst zo kort mogelijk.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`Uniek lokaal IPv6-bereik toestaan voor het ophalen van webinhoud`},help:{"v1-1eyz55i-3b":`Sta unieke lokale IPv6-adressen (fc00::/7) toe voor compatibiliteit met vertrouwde fake-IP-proxy's zoals sing-box, Clash of Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`RFC 2544-benchmarkbereik toestaan voor het ophalen van webinhoud`},help:{"v1-u5asdb-2y":`Sta IP-adressen in het RFC 2544-benchmarkbereik (198.18.0.0/15) toe voor compatibiliteit met fake-IP-proxy's zoals Clash of Surge.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`Geblokkeerde hostnamen voor het ophalen van webinhoud`},help:{"v1-1164vvk-66":`Hostnaampatronen die bij elke web_fetch-omleiding worden geblokkeerd vóór DNS-resolutie en toestemmingsregels. Ondersteunt exacte hostnamen en "*.example.com" voor alleen subdomeinen; voeg "example.com" afzonderlijk toe om het hoofddomein te blokkeren. Leeg of niet ingesteld voegt geen blokkeringen toe.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`Privénetwerk toestaan bij ophalen van webinhoud (gevaarlijk)`},help:{"v1-2s6mv7-3t":`Staat web_fetch toegang toe tot doelen op privé- en interne netwerken. Laat dit uitgeschakeld tenzij URL's die door het model worden geselecteerd in deze implementatie vertrouwd zijn.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`Time-out voor ophalen van webinhoud (sec)`},help:{"v1-1c3yfr4-16":`Time-out in seconden voor web_fetch-verzoeken.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`User-Agent voor ophalen van webinhoud`},help:{"v1-s7pe8j-1e":`Overschrijf de User-Agent-header voor web_fetch-verzoeken.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`Vertrouwde omgevingsproxy voor ophalen van webinhoud`},help:{"v1-1ypkqj7-54":`Leid web_fetch via een vertrouwde HTTP(S)-proxy die via omgevingsvariabelen is ingesteld en laat de proxy DNS-resolutie uitvoeren. Schakel dit alleen in als die proxy onder controle van de beheerder staat en na DNS-resolutie het beleid voor uitgaand verkeer afdwingt.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`Cache-TTL voor zoeken op het web (min)`},help:{"v1-6trzlf-18":`Cache-TTL in minuten voor web_search-resultaten.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`Tool voor zoeken op het web inschakelen`},help:{"v1-n1cm4y-27":`Schakel beheerde web_search en optioneel de ingebouwde zoekfunctie van Codex in voor modellen die hiervoor in aanmerking komen.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`Maximumaantal webzoekresultaten`},help:{"v1-mrw7mi-z":`Aantal resultaten om terug te geven (1-10).`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Toegestane domeinen voor Codex`},help:{"v1-1cv4y44-43":`Lijst met toegestane domeinen voor native web_search van Codex. Tijdens beurten met native gehoste zoekopdrachten beperkt deze ook beheerde web_fetch; beurten met beheerde providers blijven ongewijzigd.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Grootte van de zoekcontext voor Codex`},help:{"v1-antack-1u":`Indicatie voor de grootte van de native zoekcontext van Codex: "low", "medium" of "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`Native zoeken op het web met Codex inschakelen`},help:{"v1-ek2jzd-1k":`Schakel native zoeken op het web met Codex in voor modellen die Codex ondersteunen.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Modus voor zoeken op het web met Codex`},help:{"v1-1ahyq9f-32":`Voorkeur voor native zoeken op het web met Codex: "cached" (standaard; onbeperkte Codex-beurten gebruiken hiervoor live) of "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Stad van de Codex-gebruiker`},help:{"v1-1y95orp-1d":`Stad bij benadering die wordt doorgegeven aan de native webzoekfunctie van Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`Land van de Codex-gebruiker`},help:{"v1-1xkm5ms-1g":`Land bij benadering dat wordt doorgegeven aan de native webzoekfunctie van Codex.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Regio van de Codex-gebruiker`},help:{"v1-lhar02-1l":`Globale regio of staat die naar de ingebouwde webzoekfunctie van Codex wordt verzonden.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Tijdzone van Codex-gebruiker`},help:{"v1-fgv9fh-1h":`Globale tijdzone die naar de ingebouwde webzoekfunctie van Codex wordt verzonden.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Aanbieder van webzoekopdrachten`},help:{"v1-10omglr-1x":`ID van de zoekaanbieder. Wordt automatisch gedetecteerd op basis van beschikbare API-sleutels als dit niet is opgegeven.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Time-out voor webzoekopdrachten (sec)`},help:{"v1-i0egvw-17":`Time-out in seconden voor web_search-aanvragen.`}},transcripts:{label:{"v1-1iqk6o8-b":`Transcripties`},help:{"v1-1i0sc09-66":`Basisinstellingen voor het vastleggen van transcripties voor vergadernotities, agenttools met opnamefunctie en geconfigureerde bronnen voor het automatisch starten bij livevergaderingen. Vergaderplugins leggen standaard blijvende notities vast; stel enabled in op false om dit overal uit te schakelen.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`Bronnen voor automatisch starten van transcripties`},help:{"v1-1mzsl79-5s":`Livetranscriptiebronnen die automatisch worden beheerd vanaf het opstarten van de gateway. Elke vermelding is ingeschakeld zodra deze aanwezig is; verwijder een vermelding om die bron uit te schakelen. Bronnen leggen continu vast, tenzij whenOccupied is ingeschakeld.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`Account-ID voor transcripties`},help:{"v1-6g2kjj-4b":`Optionele account- of werkruimte-ID bij de aanbieder voor transcriptiebronnen waarbij onderscheid tussen accounts nodig is. Gebruik de account-ID-indeling die in de documentatie van de aanbieder staat.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`Kanaal-ID voor transcripties`},help:{"v1-1lk9d5o-4u":`Kanaal-ID bij de provider voor de bron van de live transcriptie, zoals een Discord-spraakkanaal of een Slack-huddlekanaal. Controleer de providerspecifieke betekenis van de ID voordat je automatisch starten inschakelt.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`Discord-guild-ID`},help:{"v1-fyfgnk-4l":`Optionele Discord-guild-ID voor bronnen van Discord-spraaktranscripties. Configureer deze met de bijbehorende channelId wanneer de provider spraakkanalen binnen een specifieke guild moet opzoeken.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`Vergaderings-URL voor transcriptie`},help:{"v1-1xtt9ci-4f":`Optionele vergaderings-URL voor providers die deelnemen via een URL in plaats van een kanaal-ID. Gebruik alleen vertrouwde vergaderingslinks, omdat automatisch starten ertoe kan leiden dat de vergadering wordt bijgewoond en vastgelegd.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`Provider-ID van transcriptiebron`},help:{"v1-1uur06p-3s":`Provider-ID van de transcriptiebron, zoals een provider voor Discord-spraak of een toekomstige provider voor Slack-huddles. Gebruik de exacte ID die de providerplug-in beschikbaar stelt.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`Transcriptiesessie-ID`},help:{"v1-xyo4x5-5o":`Optionele vaste transcriptiesessie-ID voor deze automatisch startende bron. Wordt genegeerd wanneer whenOccupied true is. Laat deze oningesteld om ID's te laten genereren, tenzij je een stabiele dagelijkse selector nodig hebt en ID-conflicten op dezelfde dag kunt voorkomen.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`Transcriptietitel`},help:{"v1-ycjnmp-5y":`Optionele titel voor toekomstige transcriptopnamen. Als je alleen titels wijzigt, blijven de huidige opnamen actief en worden de bij aanvang vastgelegde titel en opgeslagen notities niet hernoemd. Voor andere bronwijzigingen blijft de normale afhandeling van herstarts gelden.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`Transcriptopname bij aanwezigheid`},help:{"v1-34jid4-78":`Start een nieuwe transcriptsessie telkens wanneer er mensen aanwezig zijn in de bron en stop deze (waarbij notities worden gegenereerd) nadat de laatste persoon is vertrokken. Vereist een provider die aanwezigheid doorgeeft, zoals discord-voice. Standaard: false (doorlopend opnemen vanaf het starten van de gateway).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`Transcripten ingeschakeld`},help:{"v1-fyqqr0-6d":`Schakelt blijvend opgeslagen automatische vergadernotities, de agenttool transcripts en geconfigureerde automatisch startende bronnen in. Standaard: true. Stel in op false om permanente opslag en de tool uit te schakelen; de expliciete transcriptiemodus voor vergaderingen behoudt een beperkt live overzicht van de meest recente transcriptie.`}},tts:{label:{"v1-bmxkk9-e":`Tekst-naar-spraak`},help:{"v1-1o27tk2-4n":`Beleid voor tekst-naar-spraak om agentantwoorden voor te lezen via ondersteunde spraak- of audio-interfaces. Laat dit uitgeschakeld, tenzij spraakweergave deel uitmaakt van de workflow van de beheerder of gebruiker.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`TTS-persona`},help:{"v1-1r0opcb-29":`Standaard-ID voor de TTS-persona. Lokale voorkeuren voor TTS-persona's kunnen dit per host overschrijven.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`TTS-persona's`},help:{"v1-19aybhl-2l":`Benoemde TTS-persona's die een vaste stemidentiteit en providerspecifieke spraakkoppelingen definiëren.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`TTS-persona`},help:{"v1-10s52ah-2l":`Eén TTS-persona. Gebruik providerspecifieke koppelingen voor specifieke stemmen/modellen en promptsjablonen.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`Providerkoppelingen voor TTS-persona's`},help:{"v1-993jop-3e":`Providerspecifieke koppelingen voor TTS-persona's, met de spraakprovider-id als sleutel. Deze worden samengevoegd met tts.providers voor de actieve persona en krijgen daarbij voorrang.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`Instellingen voor TTS-providers`},help:{"v1-1k80nl4-4y":`Providerspecifieke TTS-instellingen, met de spraakprovider-id als sleutel. Gebruik deze in plaats van meegeleverde providerspecifieke sleutels op het hoogste niveau, zodat spraakplug-ins losgekoppeld blijven van het kernconfiguratieschema.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`Configuratie van TTS-provider`},help:{"v1-dwapva-3d":`Providerspecifieke TTS-configuratie voor één spraakprovider-id. Beperk de velden tot de plug-in waartoe die provider behoort.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`API-sleutel van TTS-provider`},help:{"v1-1m2fj0i-2o":`API-sleutel van de provider die door die spraakprovider wordt gebruikt wanneer de plug-in geauthenticeerde TTS-toegang vereist.`}},tui:{label:{"v1-c8hus1-b":`Terminalinterface`},help:{"v1-1fg9vw2-3s":`Weergave-instellingen voor de terminalinterface. Gebruik dit gedeelte voor weergavevoorkeuren die alleen voor de terminal gelden, zonder het gedrag van Gateway of andere interfaces te wijzigen.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`Voettekst van terminalinterface`},help:{"v1-6e12l3-3k":`Weergave-instellingen voor de voettekst van de terminalinterface. Houd optionele context compact, zodat informatie over sessies, modellen, doelen en tokens leesbaar blijft.`}},ui:{label:{"v1-ye4dff-2":`UI`},help:{"v1-dt1924-42":`Weergave-instellingen voor de interface, zoals accenten en weergavevoorkeuren van de beheerder. Gebruik deze om de leesbaarheid aan te passen zonder het runtimegedrag te wijzigen.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`Accentkleur van gebruiker`},help:{"v1-16klzws-4z":`Accentkleur van Control UI: #RRGGBB voor een aangepaste kleur, of 'theme' voor het palet van het geselecteerde thema. Overschrijft ui.seamColor; wis de waarde om de geconfigureerde naadkleur of de standaardkleur van het thema over te nemen.`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`Accentkleur`},help:{"v1-14q3r4h-4g":`Primaire accentkleur die in de interface wordt gebruikt voor nadruk, badges en visuele identiteit. Gebruik contrastrijke waarden die in zowel lichte als donkere thema's goed leesbaar blijven.`}},update:{label:{"v1-k12u1x-7":`Updates`},help:{"v1-11c5k8v-5c":`Instellingen voor het updatekanaal en de controle bij het opstarten om OpenClaw-runtimeversies actueel te houden. Gebruik behoudende kanalen in productie en experimentele kanalen alleen in gecontroleerde omgevingen.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`Automatisch bijwerken ingeschakeld`},help:{"v1-49xs2h-3c":`Schakel automatisch bijwerken op de achtergrond in voor pakketinstallaties via stable en beta; extended-stable wordt nooit automatisch toegepast (standaard: false).`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`Updatekanaal`},help:{"v1-lqtdvf-5b":`Updatekanaal voor git- en npm-installaties ("stable", "extended-stable", "beta" of "dev"). extended-stable is alleen beschikbaar voor pakketten: installatie vindt uitsluitend op de voorgrond plaats, met optionele, alleen-lezen aanwijzingen bij het opstarten.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`Controleren op updates bij het opstarten`},help:{"v1-qy3q9g-5v":`Controleert op updates wanneer de Gateway start, inclusief alleen-lezenmeldingen over extended-stable (standaard: true). Stel in op false om automatische updatecontroles, het automatisch toepassen van updates en anonieme updatepings voor de Gateway en headless nodes uit te schakelen.`}},voicewake:{label:{"v1-txt1wb-a":`Activeren met stem`}},web:{label:{"v1-1ae9z56-b":`Webkanaal`}},wizard:{label:{"v1-28jonk-h":`Installatievoorkeuren`},help:{"v1-14jh6rm-3b":`Installatievoorkeuren die door de gebruiker worden beheerd. De door het systeem beheerde wizardgeschiedenis en bevestigingsstatus worden opgeslagen in de gedeelde statusdatabase.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`Toegang voor detectie tijdens de installatie`},help:{"v1-1nqxt0w-38":`Toestemming voor detectie tijdens de begeleide installatie: "full" scant zonder te vragen, terwijl "guarded" toestemming vraagt voordat lokale applicaties worden onderzocht.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`App-aanbevelingen tijdens de installatie`},help:{"v1-ub8uoi-30":`Bepaalt of de begeleide installatie labels van geïnstalleerde applicaties mag gebruiken om relevante plug-ins en vaardigheden aan te bevelen.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`Tijdstempel van de laatste wizarduitvoering`},help:{"v1-1y0fbk-1k":`Tijdstempel van de laatste succesvol vastgelegde wizarduitvoering.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`Opdracht van de laatste wizarduitvoering`},help:{"v1-x2pfkk-15":`Opdracht waarmee de laatste wizarduitvoering is gestart.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`Commit van de laatste wizarduitvoering`},help:{"v1-h0jkmt-1i":`Broncodecommit die bij de laatste wizarduitvoering in de ontwikkelomgeving is gebruikt.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`Modus van de laatste wizarduitvoering`},help:{"v1-16508qy-1r":`Of de laatste wizarduitvoering gericht was op een installatie met "local" of "remote".`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`Versie van de laatste wizarduitvoering`},help:{"v1-1tr4z9d-19":`OpenClaw-versie die bij de laatste wizarduitvoering is gebruikt.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`Tijdstempel van de beveiligingsbevestiging in de wizard`},help:{"v1-86i182-2a":`Tijdstempel van de beveiligingsbevestiging tijdens de installatie, vastgelegd samen met de doelconfiguratie.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`Worktree-versnelling`},help:{"v1-9es3gc-4r":`Gebruik bestandssysteemversnelling voor nieuwe beheerde worktrees als dit wordt ondersteund (standaard: true). Stel in op false om normale Git-checkout en het kopiëren van bestanden te gebruiken. Geldt alleen voor nieuwe worktrees.`}},worktreeRoot:{label:{"v1-bqutg0-d":`Hoofdmap voor worktrees`},help:{"v1-1tgti9j-5d":`Globale map voor nieuwe beheerde worktrees. Gebruik een absoluut pad of ~ voor je thuismap; de standaardwaarde is <state-dir>/worktrees. Bestaande worktrees behouden hun vastgelegde paden wanneer dit wordt gewijzigd.`}}}}})))()}export{t as n,n as t};